// Which map load_assets should read [RE: maps.md §7 rule 2]. The DEFAULT
// reproduces today's hardcoded selection EXACTLY -- mapsmd03.mix entry
// 0x133a0cb2, which the hunt identified as the campaign mission sov07tmd.map --
// so every gate path that calls load_assets(dir, ra2) is unchanged. The map
// browser passes a real multiplayer map from multimd.mix instead.
struct MapSelection {
    std::string mix  = "mapsmd03.mix";   // top-level mix holding the map
    uint32_t    id   = 0x133a0cb2u;      // entry id; used when `name` is empty
    std::string name;                    // entry NAME; takes precedence when set
};

// Ore/gem overlay art [RE: economy.md §5]: one SHP per [OverlayTypes] name,
// loaded from the temperate theater chain (.tem, then a generic .shp
// fallback) via the existing theater name resolver. Indexed [kind][slot]:
// kind 0 = Ore (tibNN), 1 = Gems (gemNN); slot = the 0-based art index within
// the set (OreField::variant_at). Each SHP's first half is the density
// frames (0..11), second half shadows (verified: tib01.tem = SHP(TS) 60x60,
// 24 frames, frame 12+ empty). Individually guarded: a name missing in every
// candidate leaves present=false and that cell is simply not drawn -- never
// a crash.
//
// PALETTE (task-7 fix round, root-caused from raw-byte dumps): overlays
// palettize with temperat.pal -- the THEATER palette -- NOT isotem.pal (the
// iso TILE palette). The same decoded indices render as multicolored
// confetti under isotem.pal but as the original's golden-amber ore clumps /
// blue-green gem crystals under temperat.pal (scratchpad
// tib01_f11_isotem.png vs tib01_f11_temperat.png).
struct OreArt {
    ra2assets::ShpFile shp[2][20];
    bool present[2][20] = {};
    ra2assets::Palette pal;   // temperat.pal (see PALETTE note above)
    bool has_pal = false;     // false -> draw_ore falls back to the terrain pal
    bool any = false;
};

// `ra2` is the already-open ra2.mix (holds the nested theater/config/palette
// mixes) -- opened ONCE by each mode entry point and shared with
// load_unit_assets(), instead of each loader slurping the 268 MB file
// independently (was 79 s cold start; see docs/superpowers/specs/
// 2026-07-09-foundation-batch-design.md, sub-project 4).
// W8-03-02 / W8-03-01 (w8fix-place): fills Assets::overlay_land and
// land_buildable from rulesmd ([OverlayTypes] Land= / NoUseTileLandType= /
// Tiberium=, [Clear]..[Weeds] Buildable=). A missing rulesmd leaves them at
// the defaults (no override).
Ini load_ini_from_ra2md(const std::string& dir, const std::string& name);
void place_load_overlay_rules(const std::string& dir, Assets& a) {
    try {
        const Ini ini = load_ini_from_ra2md(dir, "rulesmd.ini");
        const std::vector<std::string> names = ra2engine::overlay_names_in_order(ini.section("OverlayTypes"));
        auto get = [&ini](const std::string& sec, const std::string& key) -> std::string {
            for (const auto& kv : ini.section(sec)) {
                std::string k = kv.first;
                for (char& c : k) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                std::string want = key;
                for (char& c : want) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                if (k != want) continue;
                std::string v = kv.second;
                const std::size_t sc = v.find(';');
                if (sc != std::string::npos) v.resize(sc);
                return v;
            }
            return std::string();
        };
        a.overlay_land = ra2engine::overlay_land_table(names, get);
        static const char* kLand[12] = {"Clear", "Road", "Water", "Rock", "Wall", "Tiberium",
                                        "Beach", "Rough", "Ice", "Railroad", "Tunnel", "Weeds"};
        for (int l = 0; l < 12; ++l) {
            const std::string v = get(kLand[l], "Buildable");
            if (v.empty()) continue;
            std::size_t k = 0;
            while (k < v.size() && std::isspace(static_cast<unsigned char>(v[k]))) ++k;
            const char c = k < v.size() ? static_cast<char>(std::tolower(static_cast<unsigned char>(v[k]))) : 'n';
            a.land_buildable[l] = c == 'y' || c == 't' || c == '1';
        }
    } catch (const std::exception&) {
        a.overlay_land.clear();
    }
}

Assets load_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                   const MapSelection& sel = MapSelection{}) {
    load_progress("MAP + THEATER");   // W2-AR-02 loading-screen checkpoint
    // Map: read the selected map INI. The default selection is byte-for-byte
    // the old hardcoded one (mapsmd03.mix / 0x133a0cb2).
    MixFile maps = MixFile::open_path(dir + sel.mix);
    const MixEntry* me = sel.name.empty() ? maps.find(sel.id) : maps.find(sel.name);
    if (!me) throw std::runtime_error("map entry not found in " + sel.mix + ": " +
                                      (sel.name.empty() ? "id 0x133a0cb2" : sel.name));
    auto map_raw = maps.read(*me);
    MapFile map = MapFile::parse(std::string(map_raw.begin(), map_raw.end()));

    // Theater chain [RE: maps.md §6 + §9.4]. Replaces the old TEMPERATE-only
    // throw: every theater now resolves through the recovered table, and the
    // TEMPERATE row's fields are the exact literals this function used before,
    // so the default path is unchanged (maps.md §7 rule 4).
    const std::string theater = map.theater();
    const ra2assets::TheaterChain* chain = ra2assets::theater_chain(theater);
    if (!chain) throw std::runtime_error("unknown theater: " + theater);
    if (!chain->playable)
        throw std::runtime_error("theater has no multiplayer maps: " + theater);

    // Where this theater's containers live [RE: maps.md §9.2/§9.3]. Tiles and
    // palettes for TEMPERATE/SNOW/URBAN are under ra2.mix; the YR theaters
    // (NEWURBAN/DESERT/LUNAR) are under ra2md.mix. The control INI is the one
    // exception: SNOW/URBAN use the *md* variants, which live in
    // ra2md.mix/localmd.mix even though their tiles are under ra2.mix
    // [RE-GATE APPLIED: maps.md §9.4].
    const std::string ini_name = chain->control_ini;
    const bool ini_is_md = ini_name.size() > 6 &&
                           ini_name.compare(ini_name.size() - 6, 6, "md.ini") == 0;
    // ra2md.mix is opened ONLY when this theater actually needs it, so the
    // default TEMPERATE path never touches it (maps.md §7 rule 5).
    std::unique_ptr<MixFile> yr;
    if (chain->yr_only || ini_is_md)
        yr.reset(new MixFile(MixFile::open_path(dir + "ra2md.mix")));
    const MixFile& parent = chain->yr_only ? *yr : ra2;

    // Palette: the iso TILE palette.
    const char* cache_name = chain->yr_only ? "cachemd.mix" : "cache.mix";
    MixFile cache = parent.open_nested(cache_name);
    const MixEntry* pe = cache.find(std::string(chain->iso_pal));
    if (!pe) throw std::runtime_error(std::string(chain->iso_pal) + " not found in " +
                                      cache_name);
    auto pal_raw = cache.read(*pe);
    Palette pal = Palette::load(pal_raw.data(), pal_raw.size());

    // Tile-set control INI. For TEMPERATE this is ra2.mix/local.mix/temperat.ini
    // -- the exact lookup this function did before.
    const char* local_name = (chain->yr_only || ini_is_md) ? "localmd.mix" : "local.mix";
    MixFile local = (chain->yr_only || ini_is_md) ? yr->open_nested(local_name)
                                                  : ra2.open_nested(local_name);
    const MixEntry* ce = local.find(ini_name);
    if (!ce) throw std::runtime_error(ini_name + " not found in " + local_name);
    auto ini_raw = local.read(*ce);
    std::string ini_text(ini_raw.begin(), ini_raw.end());

    // Tiles: the templates live in the BASE iso mix. [RE-GATE APPLIED:
    // maps.md §9.4] the same-named *md mix is an OVERLAY that resolves 0 tiles
    // (it lacks even Clear01) -- opening it instead renders an empty map.
    MixFile iso = parent.open_nested(chain->iso_mix);

    ra2engine::Theater th(std::move(iso), ini_text, chain->ext);
    // W6-05-02: the theater art mix and generic.mix are on the same search
    // list as the iso mix in the original (Init_Theater FUN_00519e70), so
    // tiles stored there (warub*.urb, Ovrpsb*.tem) resolve too.
    for (const std::string& name : {std::string(chain->art_mix), std::string("generic.mix")}) {
        try {
            th.add_fallback(parent.open_nested(name));
        } catch (const std::exception&) {}
    }

    std::cerr << "[assets] theater=" << theater << " size=" << map.width() << "x"
              << map.height() << " cells=" << map.cells().size()
              << " templates=" << th.template_count() << "\n";

    Assets out{std::move(map), pal, std::move(th), chain};
    place_load_overlay_rules(dir, out);   // W8-03-02 / W8-03-01
    return out;
}

// CB-3 Naval [RE-GATE APPLIED: naval.md §2]: resolve every materialized map
// cell's LandType into a grid_w*grid_h array (indexed y*grid_w + x, the SAME
// space build_water_passability/passable_ use). For each MapCell, classify its
// global tile index against the theater [General] tile-set indices via
// Theater::land_type_of_cell (tile -> owning [TileSetNNNN] set -> LandType). The
// .tmp TerrainType byte is NOT used (it was FALSIFIED for LandType). Cells with
// no map entry stay Clear (land, never water). land_type_of_cell is const; `th`
// is by ref only because the Assets member is non-const.
// fv7c: [General] CliffBackImpassability (Rules+0x664, INI read @0x66EC08;
// rulesmd sets 2). resolve_land_types has no Rules in hand and the engine
// runs only the retail rulesmd (decision U-1), so the value is pinned here.
constexpr int kCliffBackImpassability = 2;
std::vector<ra2assets::LandType> resolve_land_types(const ra2assets::MapFile& map,
                                                    ra2engine::Theater& th,
                                                    int grid_w, int grid_h) {
    // fv7c (13a #1) [RE: CellClass recalc FUN_0047D1C0 -> FUN_00544910 =
    // DAT_008278F4[tmp_image+0x29], table {0,8,8,8,8,10,9,3,3,2,6,1,1,0,7,3}
    // read from the exe]: the LandType is per SUB-TILE, the TMP image header's
    // terrain-type byte (the same table w5_arm_combat's speed grid uses). The
    // tile-set classification read YR's cliff set 78 (WaterCliffAPieces), the
    // slope pieces, ... as Clear and every ShorePieces sub-tile as Beach; it
    // stays only as the fall-back for a tile without a TMP header.
    // Then [General] CliffBackImpassability (Rules+0x664, rulesmd 2): a
    // Clear / Water / Beach / Ice cell with any of the six back neighbours
    // (x,y-1) (x-1,y) (x+2,y+2) (x+1,y+1) (x+1,y-1) (x-1,y+1) 4+ levels higher
    // becomes Rock. [RE-OPEN: the overlay branch of FUN_0047D1C0 (wall/rail
    // overlays near a cliff) is not modelled.]
    static const int kTab[16] = {0, 8, 8, 8, 8, 10, 9, 3, 3, 2, 6, 1, 1, 0, 7, 3};
    std::vector<ra2assets::LandType> lt(
        static_cast<std::size_t>(grid_w) * grid_h, ra2assets::LandType::Clear);
    std::vector<int> lvl(lt.size(), 0);
    for (const ra2assets::MapCell& c : map.cells()) {
        if (c.x < 0 || c.y < 0 || c.x >= grid_w || c.y >= grid_h) continue;
        const std::size_t i = static_cast<std::size_t>(c.y) * grid_w + c.x;
        lvl[i] = c.level;
        const ra2assets::TmpFile* t = th.tmp_for_tile(c.tile);
        const std::uint8_t* hdr = nullptr;
        if (t && c.subtile < t->count()) {
            try { hdr = t->image_header(c.subtile); } catch (const std::exception&) { hdr = nullptr; }
        }
        lt[i] = hdr ? static_cast<ra2assets::LandType>(kTab[hdr[41] & 15])
                    : th.land_type_of_cell(c.tile);   // fall-back: tile-set class
    }
    const int cliff_back = kCliffBackImpassability;
    if (cliff_back == 2) {
        static const int kNb[6][2] = {{0, -1}, {-1, 0}, {2, 2}, {1, 1}, {1, -1}, {-1, 1}};
        std::vector<ra2assets::LandType> out = lt;
        for (int y = 0; y < grid_h; ++y)
            for (int x = 0; x < grid_w; ++x) {
                const std::size_t i = static_cast<std::size_t>(y) * grid_w + x;
                const ra2assets::LandType l = lt[i];
                if (l != ra2assets::LandType::Clear && l != ra2assets::LandType::Water &&
                    l != ra2assets::LandType::Beach && l != ra2assets::LandType::Ice)
                    continue;
                for (const auto& d : kNb) {
                    const int nx = x + d[0], ny = y + d[1];
                    const int nl = (nx >= 0 && ny >= 0 && nx < grid_w && ny < grid_h)
                                       ? lvl[static_cast<std::size_t>(ny) * grid_w + nx] : 0;
                    if (nl >= lvl[i] + 4) { out[i] = ra2assets::LandType::Rock; break; }
                }
            }
        lt.swap(out);
    }
    return lt;
}

// Loads the ore/gem overlay SHPs from the temperate theater chain [RE:
// economy.md §5]. Ore uses the TIB set (tib01..tib20), gems use gem01..gem12;
// each name is resolved through theater_candidates (.tem preferred, .shp
// fallback) over the isotemp/temperat/generic nested mixes -- exactly the
// walk load_building_assets uses. Every name is individually guarded (a miss
// leaves present=false; the cell just doesn't draw). Logs a small probe of
// frame counts so a real-install run confirms the density-frame layout.
OreArt load_ore_art(const ra2assets::MixFile& ra2) {
    load_progress("ORE ART");   // W2-AR-02 loading-screen checkpoint
    OreArt oa;
    std::map<std::string, std::unique_ptr<MixFile>> mix_cache;
    auto get_mix = [&](const std::string& name) -> MixFile* {
        auto it = mix_cache.find(name);
        if (it != mix_cache.end()) return it->second.get();
        std::unique_ptr<MixFile> m;
        try {
            m = std::make_unique<MixFile>(ra2.open_nested(name));
        } catch (const std::exception&) { m.reset(); }
        MixFile* raw = m.get();
        mix_cache.emplace(name, std::move(m));
        return raw;
    };
    auto try_load = [&](const std::string& name, ra2assets::ShpFile& out) -> bool {
        // W2-GA-01: the theater's own extension (.tem/.sno/.urb), then .shp
        // [RE: economy.md §5, maps.md §6 TheaterChain].
        const std::string theater_ext = std::string(".") + art_chain().ext;
        for (const std::string& ext : {theater_ext, std::string(".shp")})
            for (const auto& c : ra2assets::theater_candidates(name, art_chain().letter,
                                                               art_chain().iso_mix,
                                                               art_chain().art_mix, ext)) {
                MixFile* m = get_mix(c.mix);
                if (!m) continue;
                if (const MixEntry* e = m->find(c.file)) {
                    try {
                        out = ShpFile::load(m->read(*e));
                        return true;
                    } catch (const std::exception&) { return false; }
                }
            }
        return false;
    };
    int ok = 0;
    for (int i = 0; i < 20; ++i) {
        char nm[16];
        std::snprintf(nm, sizeof nm, "tib%02d", i + 1);
        if (try_load(nm, oa.shp[0][i])) { oa.present[0][i] = true; ++ok; }
    }
    for (int i = 0; i < 12; ++i) {
        char nm[16];
        std::snprintf(nm, sizeof nm, "gem%02d", i + 1);
        if (try_load(nm, oa.shp[1][i])) { oa.present[1][i] = true; ++ok; }
    }
    // The overlay palette: temperat.pal from cache.mix (see OreArt's PALETTE
    // note). Guarded: if absent, draw_ore falls back to the terrain palette
    // (wrong colors, but still renders rather than crashing).
    try {
        MixFile cache = ra2.open_nested("cache.mix");
        if (const MixEntry* pe = cache.find(std::string(art_chain().theater_pal))) {
            auto raw = cache.read(*pe);
            oa.pal = Palette::load(raw.data(), raw.size());
            oa.has_pal = true;
        }
    } catch (const std::exception&) { oa.has_pal = false; }
    oa.any = ok > 0;
    std::cerr << "[ore] art files loaded=" << ok << " pal=" << (oa.has_pal ? art_chain().theater_pal : "FALLBACK")
              << " tib01=" << (oa.present[0][0] ? std::to_string(oa.shp[0][0].count()) : "absent")
              << "f tib02=" << (oa.present[0][1] ? std::to_string(oa.shp[0][1].count()) : "absent")
              << "f gem01=" << (oa.present[1][0] ? std::to_string(oa.shp[1][0].count()) : "absent")
              << "f\n";
    return oa;
}

