// Loads `name` (e.g. "rulesmd.ini", "artmd.ini") from ra2md.mix ONCE per mode
// entry point (nested fallback chain -- these INIs are not always a
// top-level ra2md.mix entry in a stock install; mirrors the exact fallback
// chain proven against the real install in tests/test_rules.cpp's real-asset
// test). The returned Ini must outlive any Rules/Art built from it (both wrap
// their Ini by reference -- see rules.hpp/art.hpp) -- callers keep both as
// locals in the same function scope.
std::vector<uint8_t> read_ra2md_file(const std::string& dir, const std::string& name);
Ini load_ini_from_ra2md(const std::string& dir, const std::string& name) {
    const std::vector<uint8_t> ini_bytes = read_ra2md_file(dir, name);
    return Ini::parse(std::string(ini_bytes.begin(), ini_bytes.end()));
}

// The raw bytes behind load_ini_from_ra2md (multiplayer: the rules CRC the
// lobby/server version gate compares, docs/gap/net/05 §2.5).
std::vector<uint8_t> read_ra2md_file(const std::string& dir, const std::string& name) {
    MixFile top = MixFile::open_path(dir + "ra2md.mix");

    std::vector<uint8_t> ini_bytes;
    if (const MixEntry* e = top.find(mix_id(name))) {
        ini_bytes = top.read(*e);
    } else {
        static const char* candidates[] = {
            "localmd.mix",  "expandmd01.mix", "expandmd02.mix", "expandmd03.mix",
            "expandmd04.mix", "expandmd05.mix", "expandmd99.mix",
            "cachemd.mix",  "conqmd.mix",
        };
        for (const char* cand : candidates) {
            try {
                MixFile nested = top.open_nested(cand);
                if (const MixEntry* e2 = nested.find(mix_id(name))) {
                    ini_bytes = nested.read(*e2);
                    break;
                }
            } catch (const std::exception&) {
                // Nested mix not present in this install/layout; try the next.
            }
        }
    }
    if (ini_bytes.empty())
        throw std::runtime_error(name + " not found in ra2md.mix (top level or nested)");
    return ini_bytes;
}

// --- Audio Playback phase, Task 6: SDL sink + game audio wiring ---------
//
// One unit-type's soundmd.ini section names for its voice/report lines.
// VoiceSelect/VoiceMove/VoiceAttack/DieSound come straight from Rules;
// `report` is the unit's PRIMARY WEAPON's Report= (docs/re/audio-playback.md:
// Report lives on the weapon, not the unit). Any field may be "" if
// rulesmd.ini omits it -- looking that up in AudioSystem::voices and playing
// it is then just a silent no-op (Mixer::play on an empty/unregistered key
// returns false).
struct UnitVoices {
    std::string select, move, attack, die, report, move_sound, crush;   // W2-GA-25 move_sound/crush
    // W5-E (pres_audio_events.inc): the click-mission voices, the hurt voice,
    // deploy/sink/crash sounds and the C4 flag (Sabotage voice).
    std::string feedback, special, enter, capture, harvest, deploy_voice, deploy_snd, undeploy_snd,
        sinking, crashing, voice_sinking, voice_crashing, turret_rotate;
    bool c4 = false;
    // W7-02-06 [RE: VoiceAttack picker 0x708520 -- TechnoType +0x580
    // VoicePrimaryWeaponAttack, +0x584 VoicePrimaryEliteWeaponAttack, +0x588
    // VoiceSecondaryWeaponAttack, +0x58C VoiceSecondaryEliteWeaponAttack, else
    // VoiceAttack, by the weapon index SelectWeapon picks].
    std::string attack_primary, attack_primary_elite, attack_secondary, attack_secondary_elite;
    // W7-03-10 [rules ActivateSound / DeactivateSound / VoiceSelectDeactivated
    // (ROBO)] and W7-10-05 MindClearedSound (else [AudioVisual] MindClearedSound).
    std::string activate, deactivate, select_deactivated, mind_cleared;
    bool spawned = false;      // W7-12-02 Spawned= (TechnoType +0xD54): no EVA_UnitLost
    bool registered = false;   // W7-12-27: add_voices ran for this rules id
};

// Everything the audio wiring needs at runtime. `mixer` is a unique_ptr (not
// a plain Mixer member) because Mixer stores its SoundBank BY REFERENCE (see
// engine/audio_mixer.hpp): init_audio() fully populates `bank` first (every
// voice/report/die clip's variants, then the EVA clip), and only THEN
// constructs the Mixer over the now-stable bank -- so the reference the
// Mixer holds is never invalidated by an earlier/later bank.add() call, and
// AudioSystem itself never needs to move once init_audio returns.
// `enabled` gates ALL per-frame audio work (event collection/acks/pump in
// run_interactive) -- stays false when --no-audio was passed (init_audio is
// then never called at all) or the SDL device failed to open, giving the
// "fully silent game, no crash" robustness guarantee.
struct AudioSystem {
    ra2engine::SoundBank bank;
    std::unique_ptr<ra2engine::Mixer> mixer;
    ra2engine::AudioOutput out;
    std::map<std::string, UnitVoices> voices;  // W7-12-27: by RULES id ("E1","SENGINEER"), filled by the presentation
    int eva_unitlost = -1;                     // bank clip id, -1 if unavailable
    // Chrono Miner teleport sounds [RE: economy.md §3]: soundmd section names
    // from rulesmd [CMIN] ChronoOut/InSound ("" -> silent no-op on play).
    std::string chrono_out, chrono_in;
    // CB-1 transport sounds [RE: transport-cargo.md; spec §6]: soundmd
    // section names from rulesmd [HTK] EnterTransportSound/
    // LeaveTransportSound, falling back to the [AudioVisual] defaults
    // ("" -> silent no-op on play, the chrono pattern).
    std::string enter_transport, leave_transport;
    bool enabled = false;
};

// Audio-local RNG seed for Mixer's variant-selection RNG (docs/re/
// audio-playback.md's RNG-determinism caveat: audio must draw from its OWN
// RNG, never the sim's Randomizer, so --demo-combat's byte-identity gate
// stays unaffected by audio; any fixed constant is fine here since nothing
// about audio playback needs to be bit-reproducible across runs).
constexpr uint32_t kAudioRngSeed = 0x52413221u;

bool has_token(const std::vector<std::string>& tokens, const char* tok) {
    return std::find(tokens.begin(), tokens.end(), tok) != tokens.end();
}

// Resolves every variant name of one soundmd.ini `[key]` section to decoded
// PCM (via `idx`/`bag`, the audio.mix BAG chain), adding each clip to
// `audio.bank` as it goes, and returns the MixerSound to register for `key`.
// NOT registered here -- init_audio collects these into a temporary map and
// registers them only after audio.mixer is constructed (see AudioSystem's
// mixer comment: the bank must be complete before the Mixer is built over
// it). A missing idx entry is logged once and that variant is skipped
// (soundmd.ini's own documented "missing sample" tolerance, docs/re/
// audio-playback.md finding 1); a key with zero resolved variants still
// gets a MixerSound back (empty `variants`) -- Mixer::play() already treats
// that as an unconditional no-op, so there is no separate "unregistered"
// state to implement here.
ra2engine::MixerSound resolve_sound_event(AudioSystem& audio, const ra2assets::Sounds& sounds,
                                          const ra2assets::AudioIdx& idx,
                                          const std::vector<uint8_t>& bag, const std::string& key) {
    const ra2assets::SoundEntry e = sounds.entry(key);
    ra2engine::MixerSound ms;
    for (const std::string& variant : e.sounds) {
        const ra2assets::BagClip* clip = idx.find(variant);
        if (!clip) {
            std::cerr << "[audio] missing clip " << variant << " (key " << key << ")\n";
            continue;
        }
        ra2assets::AudioClipInfo info;
        std::vector<int16_t> pcm = ra2assets::decode_bag_clip(bag.data(), bag.size(), *clip, info);
        ms.variants.push_back(audio.bank.add(std::move(pcm)));
    }
    ms.volume = e.volume;
    // AMENDED (docs/re/audio-playback.md "Decisions for ra2engine"): EVERY
    // event attenuates by distance, voice acks included -- they inherit
    // [Defaults] Type=SCREEN and are positional too, just usually near full
    // volume since they play near an on-screen unit. GLOBAL only adds the
    // MinVolume floor inside gain_permille; it does not mean "non-positional".
    ms.priority = ra2engine::priority_from_string(e.priority);
    ms.limit = e.limit;
    ms.interrupt = has_token(e.control, "interrupt");
    ms.global = has_token(e.type, "global");
    ms.range = e.range;
    ms.min_volume = e.min_volume;
    return ms;
}

// Loads soundmd.ini + the audio.mix BAG chain (language.mix -> audio.mix ->
// audio.idx/audio.bag, the exact chain tests/test_audio.cpp:305-311 uses),
// resolves E1 (GI)/E2 (CONS)'s five voice-line keys apiece (select/move/
// attack/die/report), decodes every variant into audio.bank, builds the
// Mixer over the now-complete bank, and registers every key. Also loads the
// EVA "Unit lost" clip ("ceva064.wav", same audio.mix, WAV/IMA path -- Task
// 3 -- not the BAG path) and opens the SDL sink. NOT called for --no-audio
// (main() skips this call entirely -- see run_interactive/mode_demo_audio)
// or for --demo-combat (its byte-identity gate stays provably unaffected by
// audio).
void init_audio(AudioSystem& audio, const std::string& dir, const Rules& rules) {
    load_progress("AUDIO");   // W2-AR-02 loading-screen checkpoint
    Ini snd_ini = load_ini_from_ra2md(dir, "soundmd.ini");
    ra2assets::Sounds sounds = ra2assets::Sounds::load(snd_ini);

    ra2assets::MixFile language =
        ra2assets::MixFile::open_path(dir + "language.mix");
    ra2assets::MixFile audio_mix = language.open_nested("audio.mix");
    const ra2assets::MixEntry* ie = audio_mix.find("audio.idx");
    if (!ie) throw std::runtime_error("audio.idx not found in language.mix/audio.mix");
    auto idx_bytes = audio_mix.read(*ie);
    ra2assets::AudioIdx idx = ra2assets::AudioIdx::load(idx_bytes.data(), idx_bytes.size());
    const ra2assets::MixEntry* be = audio_mix.find("audio.bag");
    if (!be) throw std::runtime_error("audio.bag not found in language.mix/audio.mix");
    std::vector<uint8_t> bag = audio_mix.read(*be);

    // Resolve both squads' voice/report keys, decoding every referenced clip
    // into audio.bank as we go; collect the MixerSounds in `pending` and
    // register them only once the bank -- and thus the Mixer built over it --
    // is complete (see AudioSystem's mixer comment above).
    std::map<std::string, ra2engine::MixerSound> pending;
    // HTNK (Rhino) added for the Voxel Vehicles phase: the per-image UnitVoices
    // machinery below handles it exactly like the infantry ids (image "HTNK").
    for (const char* unit_id : {"E1", "E2", "HTNK"}) {
        const std::string image = rules.image(unit_id);
        UnitVoices v;
        v.select = rules.voice_select(unit_id);
        v.move = rules.voice_move(unit_id);
        v.attack = rules.voice_attack(unit_id);
        v.die = rules.die_sound(unit_id);
        v.report = rules.weapon_report(rules.primary(unit_id));
        // W7-12-03: NOT stored in audio.voices -- Presentation::add_voices
        // builds the full entry (deploy / fear / move-start / crush ...) by
        // rules id; a partial one here used to block it for GI/CONS/HTNK.
        (void)image;

        for (const std::string& key : {v.select, v.move, v.attack, v.die, v.report}) {
            if (key.empty() || pending.count(key)) continue;
            pending[key] = resolve_sound_event(audio, sounds, idx, bag, key);
        }
    }

    // Building placement sound [RE: building-render.md §5]: rules [AudioVisual]
    // BuildingSlam=PlaceBuilding -> soundmd [PlaceBuilding] Sounds=uplace.
    // Registered globally (a missing section resolves to a silent no-op).
    if (!pending.count("PlaceBuilding"))
        pending["PlaceBuilding"] = resolve_sound_event(audio, sounds, idx, bag, "PlaceBuilding");

    // Chrono Miner teleport sounds [RE: economy.md §3]: rulesmd [CMIN]
    // ChronoOut/InSound name soundmd sections; resolve + register so the
    // interactive loop can play them on ChronoOut/ChronoIn harvest events.
    {
        Ini cmin_ini = load_ini_from_ra2md(dir, "rulesmd.ini");
        audio.chrono_out = cmin_ini.get("CMIN", "ChronoOutSound", "");
        audio.chrono_in = cmin_ini.get("CMIN", "ChronoInSound", "");
        for (const std::string& k : {audio.chrono_out, audio.chrono_in})
            if (!k.empty() && !pending.count(k))
                pending[k] = resolve_sound_event(audio, sounds, idx, bag, k);
        audio.enter_transport = cmin_ini.get("HTK", "EnterTransportSound", "");
        if (audio.enter_transport.empty())
            audio.enter_transport = cmin_ini.get("AudioVisual", "EnterTransportSound", "");
        audio.leave_transport = cmin_ini.get("HTK", "LeaveTransportSound", "");
        if (audio.leave_transport.empty())
            audio.leave_transport = cmin_ini.get("AudioVisual", "LeaveTransportSound", "");
        for (const std::string& k : {audio.enter_transport, audio.leave_transport})
            if (!k.empty() && !pending.count(k))
                pending[k] = resolve_sound_event(audio, sounds, idx, bag, k);
    }

    // EVA: "ceva064.wav" ("Unit lost") lives in the SAME audio.mix, decoded
    // via load_wav_ima (the WAV/IMA container, Task 3), not decode_bag_clip.
    try {
        const ra2assets::MixEntry* we = audio_mix.find("ceva064.wav");
        if (!we) throw std::runtime_error("ceva064.wav not found in language.mix/audio.mix");
        std::vector<uint8_t> wav_bytes = audio_mix.read(*we);
        ra2assets::WavInfo info;
        std::vector<int16_t> pcm = ra2assets::load_wav_ima(wav_bytes.data(), wav_bytes.size(), info);
        audio.eva_unitlost = audio.bank.add(std::move(pcm));
    } catch (const std::exception& ex) {
        std::cerr << "[audio] EVA unavailable: " << ex.what() << "\n";
        audio.eva_unitlost = -1;
    }

    // The bank is now complete -- safe to build the Mixer over it and
    // register every resolved key.
    audio.mixer = std::make_unique<ra2engine::Mixer>(audio.bank, kAudioRngSeed);
    for (auto& [key, ms] : pending) audio.mixer->register_sound(key, ms);

    audio.out.open();
    audio.enabled = audio.out.ok();
    std::cerr << "[audio] device=" << (audio.out.ok() ? "ok" : "none")
              << " clips=" << audio.bank.count() << "\n";
    // W2-AR-01: one SDL device for the process (menu + game share it).
    SDL_Log("[audio] game handle %s: sdl_devices=%d handles=%d", audio.out.ok() ? "ok" : "none",
            ra2engine::AudioOutput::open_device_count(), ra2engine::AudioOutput::handle_count());
}

// One unit id's full combat + movement profile, resolved from an
// already-loaded Rules: Image= (SHP base name), Speed=, Strength=, Armor=,
// then the Primary= weapon's Damage=/ROF=/Range=/Warhead=, then that
// warhead's Verses=.
struct ResolvedUnit {
    ra2engine::UnitCombat combat;
    int speed = 0;
};

// Gap fix C (G-42) / W7-11-01 [RE: docs/re/gamespeed.md §4; TechnoType INI
// FUN_00711510, FootClass::GetCurrentSpeed FUN_004DB0B0]: the original is
// frame-locked -- Speed= is stored as min(255, clamp(Speed,0,100)*256/100)
// leptons per logic frame (TechnoType+0x678) and GetCurrentSpeed multiplies
// it only by the COUNTRY's SpeedUnitsMult / SpeedInfantryMult (1.0), the
// SpeedMultiplier crate and VeteranSpeed. GameSpeedBias (house+0x190) is
// written by AssignHandicap FUN_004F6DD0 and never read. The engine's
// convention is 15 logic frames per engine second (kLogicFps, = GameSpeed 4):
//   cells/sec = trunc(Speed*256/100) * 15 / 256   (raw leptons, no bias).
// Walk and Hover units move these raw leptons; Drive and Ship units cover
// ~1.6x the leptons through their track tables (world_loco.cpp), which is
// where the old "x GameSpeedBias" figure came from.
inline double speed_to_cps(double speed) {
    const double clamped = std::min(100.0, std::max(0.0, speed));
    const int lept = std::min(255, static_cast<int>(clamped * 256.0 / 100.0));
    return lept * 15.0 / 256.0;
}

// Case-insensitive lowercasing (CB-2 Locomotor CLSID compare). File-local.
inline std::string to_lower(std::string s) {
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

// Resolves one unit id and logs it (extends the old load_unit_assets [unit]
// log line with the new combat fields) so a real-install run visibly
// confirms which numbers got pinned for E1/E2 (Task 8 ground truth: E1 GI
// M60 15/20/4 SA armor=none str=125; E2 CONS M1Carbine 15/25/4 SA armor=flak
// str=125).
#include "w2air_main.inc"   // W2-AN: resolve_an_type / resolve_sw_params (wave-2 air/naval/SW)

// W5-B R-062: SpeedType= -> GroundType Cost column (FUN_00673A40 read order).
inline int w5_speed_type_index(std::string s) {
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    const std::size_t sc = s.find_first_of(" ;	");
    if (sc != std::string::npos) s = s.substr(0, sc);
    static const char* kNames[8] = {"foot", "track", "wheel", "hover", "winged", "float", "amphibious", "floatbeach"};
    for (int i = 0; i < 8; ++i)
        if (s == kNames[i]) return i;
    return -1;
}

// W6 fix #2: a unit type's rules id + targeting data (target_w6.hpp).
ra2engine::UnitTypeTgt resolve_unit_w6(const Rules& rules, const std::string& unit_id) {
    ra2engine::UnitTypeTgt w;
    w.rules_id = unit_id;
    for (char& ch : w.rules_id) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
    w.insignificant = rules.section_flag(unit_id, "Insignificant", false);
    w.legal_target = rules.section_flag(unit_id, "LegalTarget", true);
    w.immune_psionics = rules.section_flag(unit_id, "ImmuneToPsionics", false);
    w.guard_range = rules.section_double(unit_id, "GuardRange", 0.0);
    // w7fix-combat: the wave-7 shared-combat type keys (target_w6.hpp).
    w.default_to_guard_area = rules.section_flag(unit_id, "DefaultToGuardArea", false);
    w.opportunity_fire = rules.section_flag(unit_id, "OpportunityFire", false);
    w.selectable_combatant = rules.section_flag(unit_id, "IsSelectableCombatant", false);
    w.to_protect = rules.section_flag(unit_id, "ToProtect", false);
    w.threat_posed = static_cast<int>(rules.section_double(unit_id, "ThreatPosed", 0.0));
    w.special_threat_value = rules.section_double(unit_id, "SpecialThreatValue", 0.0);
    w.attack_cursor_on_friendlies = rules.section_flag(unit_id, "AttackCursorOnFriendlies", false);
    w.prevent_attack_move = rules.section_flag(unit_id, "PreventAttackMove", false);
    w.cost = rules.cost(unit_id);
    return w;
}

ResolvedUnit resolve_combat_unit(const Rules& rules, const std::string& unit_id) {
    ResolvedUnit r;
    r.combat.image = rules.image(unit_id);
    r.speed = rules.speed(unit_id);
    // Gap fix C (G-42): every unit carries its own recovered speed (infantry
    // included -- they used to share World::move_cps).
    r.combat.speed_cps = speed_to_cps(r.speed);
    r.combat.speed_type = w5_speed_type_index(rules.section_string(unit_id, "SpeedType", ""));   // W5-B R-062
    r.combat.strength = rules.strength(unit_id);
    r.combat.sight = rules.sight(unit_id);  // [RE: shroud.md §2] reveal radius
    r.combat.armor = rules.armor(unit_id);
    // W6 fix #2: rules id + the targeting type data (map overrides merged in a
    // campaign: its Rules is rulesmd with the scenario overlaid).
    r.combat.tg = resolve_unit_w6(rules, unit_id);
    // Gap fix C (G-41) [RE: docs/re/weapons.md §1]: the TechnoType slot rule
    // (Primary/Secondary, or Weapon1..N for TurretCount>=1 types -- SREF's
    // Primary is commented out and Weapon1=Comet) via engine/weapon_resolve.
    const ra2engine::TypeWeapons tw = ra2engine::resolve_type_weapons(rules, unit_id);
    const std::string primary = tw.slot[0].id;
    r.combat.damage = rules.weapon_damage(primary);
    r.combat.rof = rules.weapon_rof(primary);
    r.combat.w6.burst = tw.slot[0].valid ? tw.slot[0].burst : 1;   // W6-04-01
    r.combat.w6.omni_fire = tw.slot[0].valid && tw.slot[0].omni_fire;   // W6-04-06
    r.combat.w6.sonic = tw.slot[0].valid && tw.slot[0].sonic;           // W6-04-09
    r.combat.w6.bomb_disarm = tw.slot[0].valid && tw.slot[0].bomb_disarm;   // DefuseKit (+0x16E)
    r.combat.w6.wall_flags = tw.slot[0].valid ? tw.slot[0].wall_flags : 0;   // W6-04-04
    r.combat.w6.powered_unit = rules.section_flag(unit_id, "PoweredUnit", false);   // W6-04-18
    r.combat.w6.decloak_to_fire = !tw.slot[0].valid || rules.section_flag(tw.slot[0].id, "DecloakToFire", true);   // W6-04-25
    r.combat.w6.open_transport_weapon =   // W6-04-15
        static_cast<int>(rules.section_double(unit_id, "OpenTransportWeapon", -1.0));
    r.combat.w6.air_range_bonus = rules.section_double(unit_id, "AirRangeBonus", 0.0);   // W6-04-16
    r.combat.w6.deployed_crushable = rules.section_flag(unit_id, "DeployedCrushable", true);   // W6-04-29
    r.combat.w6.can_approach_target = rules.section_flag(unit_id, "CanApproachTarget", true);   // W6-04-30
    r.combat.w6.omni_crusher = rules.section_flag(unit_id, "OmniCrusher", false);   // W6-04-14
    r.combat.w6.omni_crush_resistant = rules.section_flag(unit_id, "OmniCrushResistant", false);   // W6-04-14
    r.combat.range = rules.weapon_range(primary);
    const std::string warhead = rules.weapon_warhead(primary);
    r.combat.verses = rules.verses(warhead);
    r.combat.inf_death = static_cast<int>(rules.section_double(warhead, "InfDeath", 0.0));   // W3-B
    r.combat.prone_damage = ra2engine::warhead_prone_damage(rules, warhead);
    // gF [RE: docs/re/mcv-deploy.md]: TechnoType DeploysInto= (+0x404, FUN_00711510).
    r.combat.deploys_into = rules.section_string(unit_id, "DeploysInto", "");

    // CB-2 air-to-ground splash [RE-GATE APPLIED: aircraft.md §4 -> combat.md
    // §7]: the warhead's splash radius + edge scale (BlimpBomb -> BlimpHE
    // CellSpread=2 PercentAtMax=.5). Fed to combat.cpp's apply_spread_damage,
    // GATED on cell_spread >= 1 -- so every existing sub-1-cell warhead (tank
    // AP CellSpread=.3, infantry) keeps its EXACT single-target path; only
    // CellSpread>=1 warheads (BlimpHE=2) splash. Default 0 = single-target.
    r.combat.cell_spread = rules.section_double(warhead, "CellSpread", 0.0);
    r.combat.percent_at_max = rules.section_double(warhead, "PercentAtMax", 1.0);
    r.combat.affects_allies = rules.section_flag(warhead, "AffectsAllies", true);   // W5-B R-060

    // Projectile phase (P2) [RE: projectile.md §2/§6]: the primary weapon's
    // projectile class + flight parameters. Resolved for EVERY unit (like every
    // other stat) but consumed ONLY behind World::projectiles_enabled_ -- which
    // no byte-identity gate opens. Not part of the [unit] log line below.
    r.combat.proj = ra2engine::resolve_projectile_spec(rules, primary);
    // W2-SK-22 [RE: rulesmd [Comet] ShrapnelWeapon=CometFragment ShrapnelCount=5;
    // [CometFragment] Damage=30 Range=3 Warhead=CometWH]: the Prism Tank beam
    // splits on impact.
    {
        // W6-04-02: the keys live on the projectile ([LargeCometP]
        // ShrapnelWeapon=CometFragment ShrapnelCount=5); resolve_weapon_slot
        // reads them there (they were read from [Comet], which has none).
        r.combat.shrapnel_count = tw.slot[0].shrapnel_count;
        r.combat.shrapnel_damage = tw.slot[0].shrapnel_damage;
        r.combat.shrapnel_range = tw.slot[0].shrapnel_range;
        r.combat.shrapnel_verses = tw.slot[0].shrapnel_verses;
        r.combat.disguise_when_still = rules.section_flag(unit_id, "CanDisguise", false) &&
                                       rules.section_flag(unit_id, "DisguiseWhenStill", false);
    }
    // W2-SK-13 [RE: rulesmd [V3Launcher] Spawner=yes Damage=1 Warhead=Special;
    // [V3] Spawns=V3ROCKET; [General] V3RocketType=V3ROCKET V3RocketDamage=200;
    // [CombatDamage] V3Warhead=V3WH]: the launcher's 1-damage "Special" shot
    // only releases the spawned missile -- the rocket's explosion is what
    // hurts. Fold the rocket's payload into the shot (V3RocketDamage on
    // V3Warhead). [PARTIAL: the rocket is not a separate 50-HP aircraft that
    // flak can intercept, and MinimumRange=5 is not modelled.]
    if (rules.section_flag(primary, "Spawner", false)) {
        const std::string spawn = rules.section_string(unit_id, "Spawns", "");
        if (!spawn.empty() && spawn == rules.section_string("General", "V3RocketType", "V3ROCKET") &&
            rules.section_flag(spawn, "MissileSpawn", false)) {
            r.combat.damage = (int)rules.general_double("V3RocketDamage", 200.0);
            const std::string vwh = rules.section_string("CombatDamage", "V3Warhead", "V3WH");
            r.combat.verses = rules.verses(vwh);
            r.combat.cell_spread = rules.section_double(vwh, "CellSpread", 0.0);
            r.combat.percent_at_max = rules.section_double(vwh, "PercentAtMax", 1.0);
        }
    }

    // CB-1 cargo stats [RE-GATE APPLIED: transport-cargo.md §1 -- absent-key
    // defaults CONFIRMED: Passengers/SizeLimit -> 0, Size -> 1. In the
    // binary Size/SizeLimit are doubles (type +0x380/+0x388); int is exact
    // for the roster values (1/2/3). Capacity gates on the COUNT
    // (NumPassengers < Passengers); Size/SizeLimit form the per-passenger
    // cap and Size otherwise feeds only the pip display]. Real rulesmd
    // ground truth: [HTK] Passengers=5 SizeLimit=2 Size=3, [FV] Passengers=1
    // SizeLimit=1 Size=3, infantry Size=1.
    r.combat.passengers = (int)rules.section_double(unit_id, "Passengers", 0.0);
    r.combat.size_limit = (int)rules.section_double(unit_id, "SizeLimit", 0.0);
    r.combat.size = (int)rules.section_double(unit_id, "Size", 1.0);

    // CB-2 flight stats. is_aircraft iff the type carries the Jumpjet
    // locomotor CLSID (CONFIRMED from [ZEP] Locomotor=).
    // W7-05-15 [RE: JumpjetLocomotionClass Link FUN_0054AA60 copies the type's
    // +0xD70 JumpJetTurnRate, +0xD74 JumpjetSpeed, +0xD78 Climb, +0xD7C Crash,
    // +0xD80 Height, +0xD84 Accel; the integrator FUN_0054CDA0 steps
    // ftol(CurSpeed) leptons/frame @0x54D1FB]: JumpjetSpeed is RAW leptons per
    // frame -- no *256/100, no GameSpeedBias (Kirov 5 -> ~0.29 cells/s) -- and
    // the turn rate is JumpJetTurnRate<<8 u16/frame (FUN_004C9100: min(rate,
    // 127)<<8), NOT ROT x2 (that is HoverLocomotion FUN_00513AD0). Absent keys
    // take the [JumpjetControls] defaults (TurnRate=4 Speed=14 Climb=5
    // CruiseHeight=500 Acceleration=2; "These are now merely defaults").
    // flight_speed stays in cells/sec and flight_turn in u16/sec (x15 frames).
    static const std::string kJumpjetClsid = "{92612C46-F71F-11d1-AC9F-006008055BB5}";
    const std::string loco = rules.locomotor(unit_id);
    r.combat.is_aircraft =
        (!loco.empty() && to_lower(loco) == to_lower(kJumpjetClsid));
    if (r.combat.is_aircraft) {
        auto jjc = [&](const char* k, double d) { return rules.section_double("JumpjetControls", k, d); };
        const int jjspeed = static_cast<int>(rules.section_double(unit_id, "JumpjetSpeed", jjc("Speed", 14.0)));
        const double jjclimb = rules.section_double(unit_id, "JumpjetClimb", jjc("Climb", 5.0));
        const double jjcrash = rules.section_double(unit_id, "JumpjetCrash", 12.0);
        const int jjturn = std::min(127, std::max(0, static_cast<int>(
            rules.section_double(unit_id, "JumpJetTurnRate", jjc("TurnRate", 4.0)))));
        r.combat.cruise_altitude = rules.section_double(unit_id, "JumpjetHeight", jjc("CruiseHeight", 500.0));
        r.combat.flight_speed = jjspeed * 15.0 / 256.0;           // cells/sec (raw lept/frame x15)
        r.combat.climb_rate   = jjclimb * 15.0;                   // leptons/sec
        r.combat.descend_rate = jjcrash * 15.0;
        r.combat.flight_turn  = jjturn * 256.0 * 15.0;            // u16/sec
        r.combat.an.jj_accel  = rules.section_double(unit_id, "JumpJetAccel", jjc("Acceleration", 2.0));
        r.combat.balloon_hover = rules.balloon_hover(unit_id);
        r.combat.omni_fire = rules.weapon_omnifire(primary);
    }

    // CB-3 naval stats [RE-GATE APPLIED: naval.md §1/§5]. is_naval iff the type
    // carries the naval locomotor CLSID (CONFIRMED from [HYD]/[DEST]/[SUB]/[DRED]
    // Locomotor={2BEA74E1-...}). The [HYD] combat stats are resolved by the SAME
    // ground-vehicle conversions with NO naval special-casing [RE-GATE APPLIED:
    // naval.md §4/§5]: Primary=FlakTrackGun -> damage=25, rof=25 frames,
    // range=5 cells (1280 leptons), verses from Warhead=FlakTWH
    // (150,125,100,60,10,10,30,20,10,100,100); Speed=8/ROT=6 via voxel-render.md
    // §5; Strength=400 -> hp. FlakTWH CellSpread=1.0 (>= 1.0) flows through CB-2's
    // existing apply_spread_damage one-ring splash (PercentAtMax=1.0 -> no
    // falloff) -- NO new code; the instant single-target-cell hit drops the
    // vanilla FlakScatter/Inaccurate RNG (documented deviation). Naval adds only
    // the domain flags. All default INERT for a ground unit (movement_domain=Land).
    static const std::string kNavalClsid = "{2BEA74E1-7CCA-11d3-BE14-00104B62A16C}";
    const std::string nloco = rules.locomotor(unit_id);
    r.combat.is_naval =
        (!nloco.empty() && to_lower(nloco) == to_lower(kNavalClsid));
    if (r.combat.is_naval)
        r.combat.movement_domain = ra2engine::MovementDomain::Water;
    // W2-AN-10 [rules [LCRF]/[SAPC]: SpeedType=Hover, MovementZone=Amphibious]:
    // the landing craft paths over land OR water.
    // W4-MC-01 [RE: gamemd MovementZone name table, docs/re/movement-zones.md]:
    // EVERY Amphibious* zone (AmphibiousDestroyer = Tanya/SEAL/PCOMMANDO/JFISH/
    // CPHAL, AmphibiousCrusher = APC, Amphibious = LCRF/SAPC/HVR) and every
    // SpeedType=Amphibious type crosses land AND water. The old exact match left
    // Tanya land-bound, so the ALL01 GI hand-over (water cells) never fired.
    else if (!r.combat.is_aircraft &&
             ra2engine::is_amphibious_zone(rules.section_string(unit_id, "MovementZone", ""),
                                           rules.section_string(unit_id, "SpeedType", "")))
        r.combat.movement_domain = ra2engine::MovementDomain::Amphibious;

    // P5 Veterancy + Crates [RE: veterancy.md V3/V4/V10/V11/V14/C8]: the
    // per-type experience/ability/elite-weapon keys. Inert unless a World
    // enables veterancy (World copies them into Unit::vet and reads them only
    // past that firewall), so resolving them here moves no existing gate.
    r.combat.cost = rules.cost(unit_id);
    r.combat.trainable = rules.section_flag(unit_id, "Trainable", true);      // default YES
    r.combat.dont_score = rules.section_flag(unit_id, "DontScore", false);
    r.combat.self_healing = rules.section_flag(unit_id, "SelfHealing", false);
    r.combat.crate_goodie = rules.section_flag(unit_id, "CrateGoodie", false);  // default NO
    r.combat.vet_abilities =
        ra2engine::parse_abilities(rules.section_string(unit_id, "VeteranAbilities", ""));
    r.combat.elite_abilities =
        ra2engine::parse_abilities(rules.section_string(unit_id, "EliteAbilities", ""));
    r.combat.rules_speed = r.speed;
    const std::string elite = tw.elite[0].id;   // ElitePrimary / EliteWeapon1 (G-41)
    if (!elite.empty()) {
        r.combat.has_elite = true;
        r.combat.elite.damage = rules.weapon_damage(elite);
        r.combat.elite.rof = rules.weapon_rof(elite);
        r.combat.elite.burst = tw.elite[0].valid ? tw.elite[0].burst : 1;   // W6-04-01
        r.combat.elite.omni_fire = tw.elite[0].valid && tw.elite[0].omni_fire;   // W6-04-06
        r.combat.elite.sonic = tw.elite[0].valid && tw.elite[0].sonic;           // W6-04-09
        r.combat.elite.wall_flags = tw.elite[0].valid ? tw.elite[0].wall_flags : 0;   // W6-04-04
        r.combat.elite.shrapnel_count = tw.elite[0].shrapnel_count;         // W6-04-02
        r.combat.elite.shrapnel_damage = tw.elite[0].shrapnel_damage;
        r.combat.elite.shrapnel_range = tw.elite[0].shrapnel_range;
        r.combat.elite.shrapnel_verses = tw.elite[0].shrapnel_verses;
        r.combat.elite.range = rules.weapon_range(elite);
        const std::string ewh = rules.weapon_warhead(elite);
        r.combat.elite.verses = rules.verses(ewh);
        r.combat.elite.cell_spread = rules.section_double(ewh, "CellSpread", 0.0);
        r.combat.elite.percent_at_max = rules.section_double(ewh, "PercentAtMax", 1.0);
        r.combat.elite.affects_allies = rules.section_flag(ewh, "AffectsAllies", true);   // W5-B R-060
        r.combat.elite.inf_death = static_cast<int>(rules.section_double(ewh, "InfDeath", 0.0));   // W3-B
        r.combat.elite.prone_damage = ra2engine::warhead_prone_damage(rules, ewh);
        r.combat.elite_proj = tw.elite[0].proj;
        r.combat.has_elite_proj = true;
    }
    ra2engine::fill_unit_combat_extras(rules, unit_id, tw, r.combat);
    resolve_an_type(rules, unit_id, tw.slot[0].id, tw.slot[1].id, r);   // W2-AN (w2air_main.inc)

    std::cerr << "[unit] id=" << unit_id << " image=" << r.combat.image << " speed=" << r.speed
              << " strength=" << r.combat.strength << " armor=" << r.combat.armor
              << " primary=" << primary << " damage=" << r.combat.damage
              << " rof=" << r.combat.rof << " range=" << r.combat.range
              << " warhead=" << warhead << "\n";
    return r;
}

// P5 Veterancy [RE: veterancy.md §0]: the [General] veteran factors +
// RepairRate (self-heal cadence) + [AudioVisual] EliteFlashTimer, read from the
// real rulesmd (general_double falls back to [AudioVisual]). Struct defaults
// are this install's values; the read makes any rules edit take effect.
ra2engine::VeterancyRules resolve_veterancy_rules(const ra2assets::Rules& rules) {
    ra2engine::VeterancyRules v;
    v.ratio = rules.general_double("VeteranRatio", v.ratio);
    v.combat = rules.general_double("VeteranCombat", v.combat);
    v.speed = rules.general_double("VeteranSpeed", v.speed);
    v.sight = rules.general_double("VeteranSight", v.sight);
    v.armor = rules.general_double("VeteranArmor", v.armor);
    v.rof = rules.general_double("VeteranROF", v.rof);
    v.cap = rules.general_double("VeteranCap", v.cap);
    v.repair_rate = rules.general_double("RepairRate", v.repair_rate);
    v.elite_flash = (int)rules.general_double("EliteFlashTimer", (double)v.elite_flash);
    return v;
}

// P5 Crates [RE: veterancy.md §0/C7]: [CrateRules] + [Powerups]. CrateRadius
// is read in LEPTONS (ReadLeptons: cells * 256, truncated).
ra2engine::CrateRules resolve_crate_rules(const ra2assets::Rules& rules) {
    ra2engine::CrateRules c;
    c.minimum = (int)rules.section_double("CrateRules", "CrateMinimum", c.minimum);
    c.maximum = (int)rules.section_double("CrateRules", "CrateMaximum", c.maximum);
    c.radius_leptons =
        (int)(rules.section_double("CrateRules", "CrateRadius", c.radius_leptons / 256.0) * 256.0);
    c.regen = rules.section_double("CrateRules", "CrateRegen", c.regen);
    c.powerups = ra2engine::default_powerups();
    for (int i = 0; i < ra2engine::kPowerupCount; ++i) {
        const std::string v = rules.section_string("Powerups", ra2engine::powerup_name(i), "");
        if (!v.empty()) c.powerups[i] = ra2engine::parse_powerup(v);
    }
    return c;
}

// CB-4 Superweapons [RE-GATE APPLIED: superweapon.md §1/§2]: resolve the Nuclear
// Missile grant params from the real rulesmd. RechargeTime is MINUTES -- CONFIRMED
// (single FMUL [0x7F3100]=900.0 + _ftol: frames = trunc(RechargeTime*900); this
// engine keeps SECONDS, so recharge_secs = RechargeTime*60, the same value as
// *900 frames / 15 fps) [RE-GATE APPLIED: superweapon.md §1]. The DAMAGING leg is
// [NukePayload]/[NUKE] (the down-strike), NOT the SW's [NukeCarrier]/NukeMaker
// up-launch (which carries no Damage/Verses -- zero area damage) -- CONFIRMED
// [RE-GATE APPLIED: superweapon.md §2]. Verses is the [NUKE] 11-slot armor array
// (int percents). All values cite docs/re/superweapon.md.
struct SuperweaponParams {
    double recharge_secs = 0.0;
    int damage = 0;
    double cell_spread = 0.0;
    double percent_at_max = 1.0;
    std::array<int, 11> verses{};
    bool ok = false;
};

SuperweaponParams resolve_superweapon(const ra2assets::Rules& rules) {
    SuperweaponParams p;
    const double recharge_min = rules.section_double("NukeSpecial", "RechargeTime", 10.0);
    p.recharge_secs = recharge_min * 60.0;                        // minutes -> seconds
    p.damage = (int)rules.section_double("NukePayload", "Damage", 600.0);
    p.cell_spread = rules.section_double("NUKE", "CellSpread", 10.0);
    p.percent_at_max = rules.section_double("NUKE", "PercentAtMax", 0.02);
    const std::vector<int> v = rules.verses("NUKE");             // [NUKE] Verses (combat.md §1)
    for (std::size_t i = 0; i < p.verses.size(); ++i)
        p.verses[i] = i < v.size() ? v[i] : 100;                 // absent slot -> 100% (no mod)
    p.ok = true;
    std::cerr << "[sw] resolve nuke recharge_secs=" << p.recharge_secs
              << " damage=" << p.damage << " cell_spread=" << p.cell_spread
              << " percent_at_max=" << p.percent_at_max << "\n";
    return p;
}

// Resolves one image's stand/walk/fire/die animation sequence from an
// already-loaded Art (artmd.ini's [image] Sequence= -> that [SequenceName]
// section's Ready/Walk/FireUp/Die1 entries -- docs/re/infantry-anim.md).
// --- P4 Unit special abilities [RE: docs/re/abilities.md] -----------------------
// Rules -> AbilityProfile / AbilityRules, read from the REAL rulesmd keys. Kept
// in main.cpp (World is asset-free). RC-5: Ini::parse now cuts the inline ';'
// comment and trims exactly like the game's INIClass::Load (docs/re/
// ini-reader.md), so this is a plain lookup (the old local strip is gone).
std::string ability_ini_str(const Ini& ini, const std::string& sec, const std::string& key) {
    return ini.get(sec, key, "");
}

// Boolean INI key, the game's Get_Bool ("Teleporter=yes;" reads "yes" now
// that Ini cuts the comment): y/t/1 -> true, n/f/0 -> false, absent -> def.
bool ability_flag(const Ini& ini, const std::string& sec, const std::string& key, bool def) {
    const std::string v = ability_ini_str(ini, sec, key);
    if (v.empty()) return def;
    const char c = static_cast<char>(std::tolower(static_cast<unsigned char>(v[0])));
    if (c == 'y' || c == 't' || c == '1') return true;
    if (c == 'n' || c == 'f' || c == '0') return false;
    return def;
}


// One weapon id -> WeaponSpec. The ability KIND is data-driven from the flags
// the hunt located: weapon Suicide (+0x144, checked FIRST -- the Fire early-out
// precedes any bullet), warhead Parasite (+0x159), Temporal (+0x15A), IvanBomb
// (+0x157). RadLevel (+0x158) defaults 0 [RE: abilities.md §A1/§B/§C/§E/§F].
ra2engine::WeaponSpec resolve_weapon_spec(const Rules& rules, const Ini& ini, const std::string& w) {
    ra2engine::WeaponSpec s;
    if (w.empty() || !ini.has(w)) return s;
    s.valid = true;
    s.damage = rules.weapon_damage(w);
    s.rof = rules.weapon_rof(w);
    s.range = rules.weapon_range(w);
    const std::string wh = rules.weapon_warhead(w);
    s.verses = rules.verses(wh);
    s.cell_spread = rules.section_double(wh, "CellSpread", 0.0);
    s.percent_at_max = rules.section_double(wh, "PercentAtMax", 1.0);
    s.affects_allies = rules.section_flag(wh, "AffectsAllies", true);   // W6-04-03
    s.prone_damage = ra2engine::warhead_prone_damage(rules, wh);
    s.inf_death = static_cast<int>(rules.section_double(wh, "InfDeath", 0.0));
    s.wall_flags = ra2engine::warhead_wall_flags(rules, wh);   // W6-04-04
    s.rad_level = static_cast<int>(rules.section_double(w, "RadLevel", 0.0));
    // P4 [RE: FUN_00700DA0 @0x701327]: warhead CausesDelayKill (+0x130),
    // DelayKillFrames (+0x134), DelayKillAtMax (+0x138).
    s.delay_kill = ability_flag(ini, wh, "CausesDelayKill", false);
    s.delay_kill_frames = static_cast<int>(rules.section_double(wh, "DelayKillFrames", 0.0));
    s.delay_kill_at_max = rules.section_double(wh, "DelayKillAtMax", 1.0);
    if (ability_flag(ini, w, "Suicide", false)) s.kind = ra2engine::AbilityKind::Suicide;
    else if (ability_flag(ini, wh, "Parasite", false)) s.kind = ra2engine::AbilityKind::Parasite;
    else if (ability_flag(ini, wh, "Temporal", false)) s.kind = ra2engine::AbilityKind::Temporal;
    else if (ability_flag(ini, wh, "IvanBomb", false)) s.kind = ra2engine::AbilityKind::IvanBomb;
    {   // wave-5 R-048: projectile AA/AG + flight, the same resolver units use
        const ra2engine::WeaponSlot ws = ra2engine::resolve_weapon_slot(rules, w);
        s.slot_set = ws.valid;
        s.aa = ws.aa;
        s.ag = ws.ag;
        s.proj = ws.proj;
        s.burst = ws.valid ? ws.burst : 1;   // W6-04-01
        s.omni_fire = ws.valid && ws.omni_fire;   // W6-04-06
    }
    return s;
}

ra2engine::AbilityProfile resolve_ability_profile(const Rules& rules, const Ini& ini,
                                                  const std::string& id) {
    ra2engine::AbilityProfile p;
    const ra2engine::WeaponSpec prim = resolve_weapon_spec(rules, ini, rules.primary(id));
    const ra2engine::WeaponSpec sec =
        resolve_weapon_spec(rules, ini, ability_ini_str(ini, id, "Secondary"));
    p.fire_kind = prim.kind;
    p.c4 = ability_flag(ini, id, "C4", false);                              // §D
    p.c4_range = sec.valid ? sec.range : 1.5;
    p.teleporter = ability_flag(ini, id, "Teleporter", false);              // §C1 +0xCD4
    p.explodes = ability_flag(ini, id, "Explodes", false);                  // §F +0xD15
    const std::string dw = ability_ini_str(ini, id, "DeathWeapon");          // §F +0xD18
    p.death = dw.empty() ? prim : resolve_weapon_spec(rules, ini, dw);
    // W6-04-12 [RE: FireDeathWeapon FUN_0070CAC0 @0x70CB1B]: the death shot's
    // damage is ftol(Damage * DeathWeaponDamageModifier) (+0xD1C, default 1).
    if (p.death.valid)
        p.death.damage = static_cast<int>(p.death.damage * rules.section_double(id, "DeathWeaponDamageModifier", 1.0));
    p.deployer = ability_flag(ini, id, "Deployer", false) &&
                 ability_flag(ini, id, "DeployFire", false);                // §A +0x6AC
    if (p.deployer) p.deploy = sec;
    p.immune_radiation = ability_flag(ini, id, "ImmuneToRadiation", false); // +0xD37
    p.parasiteable = ability_flag(ini, id, "Parasiteable", true);           // +0xD38
    p.warpable = ability_flag(ini, id, "Warpable", true);                   // +0xD3A
    p.no_passive_acquire = !ability_flag(ini, id, "CanPassiveAquire", true);
    p.no_retaliate = !ability_flag(ini, id, "CanRetaliate", true);
    p.suppression_threshold =
        static_cast<int>(rules.section_double(id, "SuppressionThreshold", 0.0));  // +0xD6C
    p.ifv_mode = static_cast<int>(rules.section_double(id, "IFVMode", 0.0));       // +0x688
    p.gunner = ability_flag(ini, id, "Gunner", false);                            // +0x805
    if (p.gunner) {
        const int n = static_cast<int>(rules.section_double(id, "WeaponCount", 0.0));
        for (int k = 1; k <= n; ++k)
            p.ifv_weapons.push_back(
                resolve_weapon_spec(rules, ini, ability_ini_str(ini, id, "Weapon" + std::to_string(k))));
        if (!p.ifv_weapons.empty() && !p.ifv_weapons[0].valid) p.ifv_weapons[0] = prim;
        // W6-04-28: the elite IFV fires EliteWeapon<k> (the V10 elite slot rule).
        for (int k = 1; k <= n; ++k)
            p.ifv_weapons_elite.push_back(
                resolve_weapon_spec(rules, ini, ability_ini_str(ini, id, "EliteWeapon" + std::to_string(k))));
    }
    p.infantry = rules.is_infantry(id);
    return p;
}

ra2engine::AbilityRules resolve_ability_rules(const Rules& rules, const Ini& ini) {
    ra2engine::AbilityRules r;   // defaults = this install's values
    r.rad_duration_multiple = (int)rules.section_double("Radiation", "RadDurationMultiple", 1.0);
    r.rad_application_delay = (int)rules.section_double("Radiation", "RadApplicationDelay", 16.0);
    r.rad_level_max = (int)rules.section_double("Radiation", "RadLevelMax", 500.0);
    r.rad_level_delay = (int)rules.section_double("Radiation", "RadLevelDelay", 90.0);
    r.rad_level_factor = rules.section_double("Radiation", "RadLevelFactor", 0.2);
    const std::string rwh = ability_ini_str(ini, "Radiation", "RadSiteWarhead");
    if (!rwh.empty()) r.rad_verses = rules.verses(rwh);
    r.chrono_distance_factor = (int)rules.general_double("ChronoDistanceFactor", 48.0);
    r.chrono_trigger = ability_flag(ini, "General", "ChronoTrigger", true);
    r.chrono_minimum_delay = (int)rules.general_double("ChronoMinimumDelay", 16.0);
    r.chrono_range_minimum = (int)rules.general_double("ChronoRangeMinimum", 0.0);
    r.c4_delay_minutes = rules.section_double("CombatDamage", "C4Delay", 0.03);
    r.ivan_damage = (int)rules.section_double("CombatDamage", "IvanDamage", 450.0);
    r.ivan_timed_delay = (int)rules.section_double("CombatDamage", "IvanTimedDelay", 450.0);
    const std::string iwh = ability_ini_str(ini, "CombatDamage", "IvanWarhead");
    if (!iwh.empty()) {
        r.ivan_warhead.verses = rules.verses(iwh);
        r.ivan_warhead.cell_spread = rules.section_double(iwh, "CellSpread", 1.5);
        r.ivan_warhead.percent_at_max = rules.section_double(iwh, "PercentAtMax", 0.25);
        r.ivan_warhead.affects_allies = rules.section_flag(iwh, "AffectsAllies", true);   // W6-04-03
        r.ivan_warhead.prone_damage = ra2engine::warhead_prone_damage(rules, iwh);
        r.ivan_warhead.inf_death = static_cast<int>(rules.section_double(iwh, "InfDeath", 0.0));
        r.ivan_warhead.wall_flags = ra2engine::warhead_wall_flags(rules, iwh);   // W6-04-04
    }
    r.ivan_warhead.damage = r.ivan_damage;
    return r;
}

// The P4 cast + every [InfantryTypes] entry carrying IFVMode (so an IFV knows
// its passenger's mode). Registers by IMAGE; opens the abilities firewall.
// Called by GameScene (interactive) and the --demo-abilities gate ONLY.
void wire_abilities(ra2engine::World& world, const Rules& rules, const Ini& ini) {
    world.set_ability_rules(resolve_ability_rules(rules, ini));
    std::vector<std::string> ids = {"DRON", "DESO", "CLEG", "TANY", "GHOST", "IVAN", "TERROR", "FV"};
    // W2-SK-17/18: the Demolition Truck (Suicide Demobomb + DeathWeapon), the
    // Apocalypse (Explodes=yes) and both attack dogs (ParasiteDog warhead,
    // Parasite=yes: one bite kills any infantry, Verses 0% vs vehicles).
    for (const char* extra : {"DTRUCK", "APOC", "DOG", "ADOG"}) ids.push_back(extra);
    // Wave-5 (R-049): the Giant Squid's SquidGrab warhead ParasitePlus is
    // Parasite=yes -- the P4 parasite rides the ship it grabs.
    ids.push_back("SQD");
    for (const auto& kv : ini.section("InfantryTypes")) {
        const std::string& id = kv.second;   // RC-5: comment already cut by Ini
        if (!id.empty() && rules.section_double(id, "IFVMode", 0.0) != 0.0 &&
            std::find(ids.begin(), ids.end(), id) == ids.end())
            ids.push_back(id);
    }
    for (const std::string& id : ids) {
        if (!ini.has(id)) continue;
        world.register_ability_profile(rules.image(id), resolve_ability_profile(rules, ini, id));
    }
}

// Wave-5 (agent C) [RE: docs/re/abilities-w5.md]: the real-play-only wave-5
// mechanics -- recovered globals, per-image unit profiles (Tesla Trooper
// ElectricAssault, OpenTopped) and the art-side DelayedFireDelay of every
// roster building. Called by GameScene only (never a gate), after the
// roster may have grown (map tech buildings) too.
void w5_arm_building_art(BuildingAssets& ba, const Ini& art_ini) {
    for (ra2engine::BuildingTypeDef& d : ba.roster) {
        const std::string img = d.image.empty() ? d.id : d.image;
        const std::string v = art_ini.get(img, "IsAnimDelayedFire", "");
        const bool on = !v.empty() && (v[0] == 'y' || v[0] == 'Y' || v[0] == 't' || v[0] == 'T' || v[0] == '1');
        d.w5.delayed_fire_delay = on ? std::max(0, std::atoi(art_ini.get(img, "DelayedFireDelay", "0").c_str())) : 0;
    }
}
// P4 [RE: FUN_00700DA0 -> FireDeathWeapon FUN_0070CAC0; delay kill @0x701327]:
// every roster building's Explodes= / DeathWeapon= / EligibleForDelayKill=
// (barrels CAMISC01/02 and AMMOCRAT chain-explode). Interactive only (GameScene
// after wire_w5 and again after a campaign grew the roster) -- never a gate.
void wire_building_deaths(ra2engine::World& world, BuildingAssets& ba, const Rules& rules, const Ini& ini) {
    bool any = false;
    for (ra2engine::BuildingTypeDef& d : ba.roster) {
        d.w5.explodes = ability_flag(ini, d.id, "Explodes", false);
        d.w5.delay_kill_eligible = ability_flag(ini, d.id, "EligibleForDelayKill", false);
        d.w5.death = d.w5.explodes ? resolve_weapon_spec(rules, ini, ability_ini_str(ini, d.id, "DeathWeapon"))
                                   : ra2engine::WeaponSpec{};
        // W6-04-12 [RE: FireDeathWeapon FUN_0070CAC0 @0x70CB1B: damage =
        // ftol(Weapon.Damage * Type.DeathWeaponDamageModifier (+0xD1C))]:
        // [NANRCT] NukePayload 600 x 0.5 = 300.
        if (d.w5.death.valid)
            d.w5.death.damage = static_cast<int>(
                d.w5.death.damage * rules.section_double(d.id, "DeathWeaponDamageModifier", 1.0));
        any = any || (d.w5.explodes && d.w5.death.valid);
    }
    world.refresh_building_types(ba.roster);
    if (any) world.arm_building_deaths();
}
void wire_w5(ra2engine::World& world, BuildingAssets& ba, const Rules& rules, const Ini& ini,
             const Ini& art_ini) {
    ra2engine::RulesW5 r;
    r.prism_support_modifier = (int)std::lround(rules.general_double("PrismSupportModifier", 150.0));
    r.prism_support_max = (int)rules.general_double("PrismSupportMax", 8.0);
    r.prism_support_delay = (int)rules.general_double("PrismSupportDelay", 45.0);
    r.prism_support_duration = (int)rules.general_double("PrismSupportDuration", 15.0);
    r.self_heal_inf_frames = (int)rules.general_double("SelfHealInfantryFrames", 50.0);
    r.self_heal_inf_amount = (int)rules.general_double("SelfHealInfantryAmount", 20.0);
    r.self_heal_unit_frames = (int)rules.general_double("SelfHealUnitFrames", 75.0);
    r.self_heal_unit_amount = (int)rules.general_double("SelfHealUnitAmount", 5.0);
    r.open_topped_range_bonus = rules.section_double("CombatDamage", "OpenToppedRangeBonus", 2.0);
    r.open_topped_damage_mult = rules.section_double("CombatDamage", "OpenToppedDamageMultiplier", 1.2);
    {   // [General] DefaultMirageDisguises=TREE01,TREE02,TREE03,TREE04
        std::string cur;
        for (char c : rules.general_string("DefaultMirageDisguises", "") + ",") {
            if (c == ',') {
                while (!cur.empty() && std::isspace((unsigned char)cur.back())) cur.pop_back();
                std::size_t a = 0;
                while (a < cur.size() && std::isspace((unsigned char)cur[a])) ++a;
                if (a < cur.size()) r.mirage_trees.push_back(cur.substr(a));
                cur.clear();
            } else cur += c;
        }
    }
    std::map<std::string, ra2engine::UnitProfileW5> prof;
    for (const char* list : {"InfantryTypes", "VehicleTypes", "AircraftTypes"}) {
        if (!ini.has(list)) continue;
        for (const auto& kv : ini.section(list)) {
            const std::string& id = kv.second;
            if (id.empty() || !ini.has(id)) continue;
            ra2engine::UnitProfileW5 p;
            const std::string sec = ra2engine::type_weapon_id(rules, id, 1, false);
            if (!sec.empty()) {
                const std::string wh = rules.section_string(sec, "Warhead", "");
                if (!wh.empty() && rules.section_flag(wh, "ElectricAssault", false)) {
                    p.assault = true;
                    p.assault_rof = (int)rules.section_double(sec, "ROF", 25.0);
                }
            }
            p.open_topped = rules.section_flag(id, "OpenTopped", false);
            if (rules.section_double(id, "Passengers", 0.0) > 0.0)
                p.deploy_frames = (int)(rules.section_double(id, "DeployTime", 0.0) * 900.0);
            p.airstrike_team = (int)rules.section_double(id, "AirstrikeTeam", 0.0);
            if (p.airstrike_team > 0) {
                p.elite_airstrike_team = (int)rules.section_double(id, "EliteAirstrikeTeam", p.airstrike_team);
                p.airstrike_type = rules.section_string(id, "AirstrikeTeamType", "");
                p.airstrike_recharge = (int)rules.section_double(id, "AirstrikeRechargeTime", 0.0);
                p.elite_airstrike_recharge =
                    (int)rules.section_double(id, "EliteAirstrikeRechargeTime", p.airstrike_recharge);
                const std::string fl = ra2engine::type_weapon_id(rules, id, 1, false);
                p.flare_range = fl.empty() ? 12.0 : rules.weapon_range(fl);
                if (p.airstrike_type.empty()) p.airstrike_team = 0;
            }
            {
                const std::string pw = ra2engine::type_weapon_id(rules, id, 0, false);
                const std::string wh = pw.empty() ? std::string() : rules.section_string(pw, "Warhead", "");
                if (!wh.empty() && rules.section_flag(wh, "Parasite", false)) {
                    p.paralyzes = rules.section_double(wh, "Paralyzes", 0.0) > 0.0;
                    p.culling = rules.section_flag(wh, "Culling", false);
                }
            }
            if (p.assault || p.open_topped || p.deploy_frames > 0 || p.airstrike_team > 0 || p.paralyzes ||
                p.culling)
                prof[rules.image(id)] = p;
        }
    }
    w5_arm_building_art(ba, art_ini);
    world.refresh_building_types(ba.roster);
    world.arm_w5(r, prof);
    wire_building_deaths(world, ba, rules, ini);
}

// Logs the fire/die entries (mirrors resolve_combat_unit's [unit] log line)
// so a real-install run visibly confirms the real artmd.ini numbers got
// pinned (ground truth: GI/CONS fireup=164,6,6 die1=134,15).
ra2engine::UnitAnimSeq anim_from_art(const ra2assets::Art& art, const std::string& image) {
    auto conv = [&](const char* name) {
        const ra2assets::ArtSequenceEntry e = art.entry(image, name);
        return ra2engine::SeqEntry{e.start, e.count, e.facing_mult};
    };
    ra2engine::UnitAnimSeq seq{conv("Ready"), conv("Walk"), conv("FireUp"), conv("Die1")};
    std::cerr << "[anim] image=" << image << " fireup=" << seq.fire.first << ","
              << seq.fire.count << "," << seq.fire.fmult << " die1=" << seq.die.first
              << "," << seq.die.count << "\n";
    return seq;
}

// W3-B: the live game's infantry sequence machine (engine/inf_anim.hpp) --
// every [InfantryTypes] image gets its FULL art Sequence= table (all 42 keys,
// with the optional facing label), art Crawls=, rules Fearless= / Fraidycat=
// / NotHuman=, and the [AudioVisual] IdleActionFrequency idle timer base.
// GameScene only; gates keep the 4-entry set_anim tables.
void enable_live_infantry_anims(ra2engine::World& world, const Ini& rules_ini, const Ini& art_ini,
                                int human_house) {
    auto clean = [](std::string v) {
        const std::size_t sc = v.find(';');
        if (sc != std::string::npos) v = v.substr(0, sc);
        while (!v.empty() && std::isspace(static_cast<unsigned char>(v.back()))) v.pop_back();
        while (!v.empty() && std::isspace(static_cast<unsigned char>(v.front()))) v.erase(v.begin());
        return v;
    };
    auto yes = [&](const Ini& ini, const std::string& sec, const char* k, bool d) {
        const std::string v = clean(ini.get(sec, k));
        if (v.empty()) return d;
        const char c = static_cast<char>(std::tolower(static_cast<unsigned char>(v[0])));
        return c == 'y' || c == 't' || c == '1';
    };
    static const char* kFace[8] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    int n = 0;
    for (const auto& kv : rules_ini.section("InfantryTypes")) {
        const std::string id = clean(kv.second);
        if (id.empty()) continue;
        std::string image = clean(rules_ini.get(id, "Image"));
        if (image.empty()) image = id;
        const std::string seq = clean(art_ini.get(image, "Sequence"));
        if (seq.empty()) continue;
        ra2engine::InfTable t;
        for (int q = 0; q < ra2engine::kSqCount; ++q) {
            const std::string v = clean(art_ini.get(seq, ra2engine::inf_seq_name(q)));
            if (v.empty()) continue;
            std::vector<std::string> f;
            std::string cur;
            for (char ch : v) { if (ch == ',') { f.push_back(clean(cur)); cur.clear(); } else cur += ch; }
            f.push_back(clean(cur));
            ra2engine::InfSeqEntry& e = t.e[static_cast<std::size_t>(q)];
            e.has = true;
            e.first = std::atoi(f[0].c_str());
            // W7-12-36: a 0 count stays 0 (PlayAnim refuses it).
            e.count = f.size() > 1 ? std::max(0, std::atoi(f[1].c_str())) : 1;
            e.fmult = f.size() > 2 ? std::atoi(f[2].c_str()) : 0;
            if (f.size() > 3) {
                std::string lab = f[3];
                for (char& ch : lab) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
                for (int k = 0; k < 8; ++k)
                    if (lab == kFace[k]) e.facing = k;
            }
        }
        t.crawls = yes(art_ini, image, "Crawls", true);
        t.fearless = yes(rules_ini, id, "Fearless", false);
        t.fraidycat = yes(rules_ini, id, "Fraidycat", false);
        t.not_human = yes(rules_ini, id, "NotHuman", false);
        // W7-09-02: the sequence table is per image, the Fearless /
        // Fraidycat / NotHuman flags per rules id -- the image entry keeps the
        // FIRST type's flags, each id gets its own.
        std::string uid = id;
        for (char& ch : uid) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
        if (uid == image || !world.inf_table(image)) world.set_inf_table(image, t);
        if (uid != image) world.set_inf_table(uid, t);
        ++n;
    }
    // W7-12-08: InfDeath of the radiation / nuke / storm warheads.
    auto inf_death_of = [&](const std::string& wh) {
        const std::string v = clean(rules_ini.get(clean(wh), "InfDeath"));
        return clean(wh).empty() ? -1 : (v.empty() ? 0 : std::atoi(v.c_str()));
    };
    {
        std::string nwh = clean(rules_ini.get("General", "NukeWarhead"));   // [General] NukeWarhead=Nuke
        if (nwh.empty()) nwh = "NUKE";
        world.set_inf_deaths(inf_death_of(rules_ini.get("Radiation", "RadSiteWarhead")), inf_death_of(nwh),
                             inf_death_of(rules_ini.get("General", "LightningWarhead")));
    }
    const std::string f = clean(rules_ini.get("AudioVisual", "IdleActionFrequency"));
    world.enable_infantry_anims(human_house, f.empty() ? 0.15 : std::atof(f.c_str()));
    std::cerr << "[inf-anim] tables=" << n << std::endl;
}

// Loads one image's SHP from ra2.mix/conquer.mix ("<Image>.shp", falling
// back to the lowercased form -- conquer.mix's stock entry names are
// lowercase, e.g. "gi.shp"/"cons.shp"; try as-is first in case a mod/layout
// differs).
ShpFile load_unit_shp(const MixFile& conquer, const std::string& image) {
    // W3-FIX-A: the global per-theater MIX search list first (the original's
    // single lookup: patch caches, conquer.mix, ..., YR conqmd.mix last).
    {
        std::string lname = image + ".shp";
        for (char& c : lname) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        const MixFile* m = nullptr;
        std::string where;
        if (const MixEntry* ge = asset_fs().find(lname, &m, &where)) {
            ShpFile shp = ShpFile::load(m->read(*ge));
            std::cerr << "[shp] image=" << image << " file=" << where << "/" << lname << " frames=" << shp.count()
                      << " canvas=" << shp.width() << "x" << shp.height() << "\n";
            return shp;
        }
    }
    std::string shp_name = image + ".shp";
    const MixEntry* se = conquer.find(shp_name);
    if (!se) {
        std::string lower = shp_name;
        for (char& c : lower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        se = conquer.find(lower);
        shp_name = lower;
    }
    if (!se) {
        // W2-GA-10: a few RA2-roster SHPs ship only in ra2md.mix/conqmd.mix on
        // a combined install (GGI, the Guardian GI) -- the same conquer ->
        // conqmd pair PresFx::load_shp searches.
        try {
            static const MixFile conqmd =
                MixFile::open_path(env_install_dir() + "ra2md.mix").open_nested("conqmd.mix");
            if (const MixEntry* me = conqmd.find(shp_name)) {
                ShpFile shp = ShpFile::load(conqmd.read(*me));
                std::cerr << "[shp] image=" << image << " file=conqmd.mix/" << shp_name
                          << " frames=" << shp.count() << "\n";
                return shp;
            }
        } catch (const std::exception&) {}
        throw std::runtime_error("unit SHP not found in ra2.mix/conquer.mix: " + image + ".shp");
    }
    ShpFile shp = ShpFile::load(conquer.read(*se));
    std::cerr << "[shp] image=" << image << " file=" << shp_name << " frames=" << shp.count()
              << " canvas=" << shp.width() << "x" << shp.height() << "\n";
    return shp;
}

// Loads everything both squads need: rulesmd.ini once -> ONE Rules -> E1
// (GI) + E2 (Conscript) resolved combat/speed profiles, their two SHPs
// (GI.SHP, CONS.SHP), and the shared unittem.pal. `ra2` is the already-open
// ra2.mix shared with load_assets() (opened once by the mode entry points --
// avoids slurping the 268 MB file again).
UnitAssets load_unit_assets(const std::string& dir, const ra2assets::MixFile& ra2) {
    load_progress("INFANTRY ART");   // W2-AR-02 loading-screen checkpoint
    Ini ini = load_ini_from_ra2md(dir, "rulesmd.ini");
    Rules rules = Rules::load(ini);

    const ResolvedUnit gi = resolve_combat_unit(rules, "E1");
    const ResolvedUnit cons = resolve_combat_unit(rules, "E2");

    MixFile conquer = ra2.open_nested("conquer.mix");
    UnitAssets ua;
    ua.shps.emplace(gi.combat.image, load_unit_shp(conquer, gi.combat.image));
    ua.shps.emplace(cons.combat.image, load_unit_shp(conquer, cons.combat.image));

    MixFile cache = ra2.open_nested("cache.mix");
    const MixEntry* pe = cache.find(std::string(art_chain().unit_pal));   // G-86
    if (!pe) throw std::runtime_error("unit palette not found in ra2.mix/cache.mix");
    auto pal_raw = cache.read(*pe);
    ua.pal = Palette::load(pal_raw.data(), pal_raw.size());

    // artmd.ini: resolve both images' animation sequences. The Ini/Art locals
    // stay alive only for this scope (Art wraps its Ini by reference -- see
    // art.hpp), but anim_from_art returns plain UnitAnimSeq values, so storing
    // them in ua.anims after art/art_ini go out of scope is safe.
    Ini art_ini = load_ini_from_ra2md(dir, "artmd.ini");
    Art art = Art::load(art_ini);
    ua.anims.emplace(gi.combat.image, anim_from_art(art, gi.combat.image));
    ua.anims.emplace(cons.combat.image, anim_from_art(art, cons.combat.image));

    ua.gi = gi.combat;
    ua.gi_speed = gi.speed;
    ua.cons = cons.combat;
    ua.cons_speed = cons.speed;
    return ua;
}

// Spawns `count` combat units of the given type/house on distinct walkable,
// unoccupied cells, spiralling ring-by-ring out from (origin_x, origin_y).
// Shared by both squads in build_world so their spawn geometry -- and thus
// --demo-combat's bit-identical replay, which depends on that geometry being
// reproduced exactly every run -- comes from one code path.
void spawn_squad(ra2engine::World& world, int origin_x, int origin_y, int count, int house,
                 const ra2engine::UnitCombat& combat) {
    int placed = 0;
    for (int r = 0; r <= 12 && placed < count; ++r)
        for (int dy = -r; dy <= r && placed < count; ++dy)
            for (int dx = -r; dx <= r && placed < count; ++dx) {
                if (std::abs(dx) != r && std::abs(dy) != r) continue;  // ring border only
                const int x = origin_x + dx, y = origin_y + dy;
                if (world.walkable(x, y) && world.unit_at_cell(x, y) < 0) {
                    world.add_combat_unit(x, y, house, combat);
                    ++placed;
                }
            }
}

// Loads everything the Rhino (or any single voxel vehicle) needs to render +
// fight: its combat/locomotion profile from rulesmd.ini, the hull/turret/barrel
// VXL+HVA parts + voxels.vpl from ra2.mix -> local.mix, six load-time facing
// caches (hull/turret/barrel x house 0/1, palette per house via pal_for_house
// over the shared unit palette `unit_pal` == ua.pal), the PrimaryFireFLH muzzle
// offset from artmd.ini, and the death-explosion SHP + its palette. EVERY step
// is guarded: on ANY failure the whole load is abandoned (logged once) and `ok`
// stays false, so the game runs infantry-only and never crashes. `ra2` is the
// shared already-open ra2.mix. Turret/barrel absence is not an error for a
// non-turreted vehicle (Rules::has_turret gates the attempt).
VehicleAssets load_vehicle_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                                  const ra2assets::Palette& unit_pal, const std::string& unit_id) {
    load_progress("VEHICLE VOXELS");   // W2-AR-02 loading-screen checkpoint
    VehicleAssets va;
    try {
        Ini rules_ini = load_ini_from_ra2md(dir, "rulesmd.ini");
        Rules rules = Rules::load(rules_ini);
        Ini art_ini = load_ini_from_ra2md(dir, "artmd.ini");
        Art art = Art::load(art_ini);

        const ResolvedUnit ru = resolve_combat_unit(rules, unit_id);
        va.combat = ru.combat;
        va.combat.is_vehicle = true;
        va.combat.rot = rules.rot(unit_id);
        va.combat.turret = rules.has_turret(unit_id);
        va.combat.speed_cps = speed_to_cps(ru.speed);  // Speed 6 -> 1.41 cps (G-42)

        const std::string image = va.combat.image;  // "HTNK"
        std::string base = image;
        for (char& ch : base) ch = static_cast<char>(std::tolower((unsigned char)ch));  // "htnk"

        MixFile local = ra2.open_nested("local.mix");
        // [RE: roster2.md §A] P6: YR-only voxels (BFRT/SCHP/ROBO) live in
        // ra2md.mix/localmd.mix. Opened LAZILY and consulted ONLY when a part is
        // absent from local.mix, so every unit that already loaded resolves
        // byte-identically (no existing caller asks for a local.mix-absent hull).
        std::unique_ptr<MixFile> md_top, md_local;
        bool md_tried = false;
        auto md_mix = [&]() -> MixFile* {
            if (!md_tried) {
                md_tried = true;
                try {
                    md_top = std::make_unique<MixFile>(
                        MixFile::open_path(dir + "ra2md.mix"));
                    md_local = std::make_unique<MixFile>(md_top->open_nested("localmd.mix"));
                } catch (const std::exception&) { md_local.reset(); }
            }
            return md_local.get();
        };
        auto load_part = [&](const std::string& part_base, ra2assets::VxlModel& m,
                             ra2assets::HvaModel& h) -> bool {
            // W3-FIX-A: the global per-theater MIX search list (patch caches
            // first, YR localmd.mix last) [RE: asset-search.md §1].
            {
                std::vector<uint8_t> vr, hr;
                if (asset_read(part_base + ".vxl", vr) && asset_read(part_base + ".hva", hr)) {
                    m = ra2assets::load_vxl(vr.data(), vr.size());
                    h = ra2assets::load_hva(hr.data(), hr.size());
                    return true;
                }
            }
            MixFile* src = &local;
            const MixEntry* ve = local.find(part_base + ".vxl");
            const MixEntry* he = local.find(part_base + ".hva");
            if (!ve || !he) {
                MixFile* md = md_mix();
                if (!md) return false;
                ve = md->find(part_base + ".vxl");
                he = md->find(part_base + ".hva");
                if (!ve || !he) return false;
                src = md;
            }
            auto vr = src->read(*ve);
            auto hr = src->read(*he);
            m = ra2assets::load_vxl(vr.data(), vr.size());
            h = ra2assets::load_hva(hr.data(), hr.size());
            return true;
        };

        ra2assets::VxlModel hull_m, tur_m, barl_m;
        ra2assets::HvaModel hull_h, tur_h, barl_h;
        if (!load_part(base, hull_m, hull_h))
            throw std::runtime_error("hull vxl/hva missing (" + base + ")");

        va.has_turret = rules.has_turret(unit_id);
        if (va.has_turret) {
            // W6-04-17 [RE-FALLBACK: a Turret=yes type without a turret voxel
            // draws its body only]: the YR Siege Chopper ([SCHP] Turret=yes, no
            // schptur.vxl in any archive) was dropped from the roster here.
            if (!load_part(base + "tur", tur_m, tur_h)) {
                std::cerr << "[vehicle] " << base << ": no turret voxel, hull only\n";
                va.has_turret = false;
            } else {
                va.has_barrel = load_part(base + "barl", barl_m, barl_h);  // barrel absence OK
            }
        }

        const MixEntry* pe = local.find("voxels.vpl");
        if (!pe) throw std::runtime_error("voxels.vpl missing");
        auto vpl_raw = local.read(*pe);
        ra2assets::Vpl vpl = ra2assets::Vpl::load(vpl_raw.data(), vpl_raw.size());

        art.fire_flh(image, va.flh);  // leaves {0,0,0} if absent/malformed
        // W7-12-44 [RE: shadow FUN_00706710 flattens ShadowIndex alone].
        va.shadow_index = std::atoi(art_ini.get(image, "ShadowIndex", "0").c_str());
        // W7-03-05/07: tur1..tur{TurretCount-1}.
        std::vector<std::pair<ra2assets::VxlModel, ra2assets::HvaModel>> alt_tur;
        if (va.has_turret) {
            const int tcount = static_cast<int>(rules.section_double(unit_id, "TurretCount", 0.0));
            for (int n = 1; n < tcount; ++n) {
                std::pair<ra2assets::VxlModel, ra2assets::HvaModel> t;
                if (!load_part(base + "tur" + std::to_string(n), t.first, t.second)) break;
                alt_tur.push_back(std::move(t));
            }
            if (!alt_tur.empty()) std::cerr << "[veh] " << image << " turrets=" << alt_tur.size() + 1 << "\n";
        }
        // W3-B [art TurretOffset=, HARV 50, HTK -80 ...]: the turret sits that
        // many leptons forward of the hull centre along the body facing.
        va.turret_offset = std::atoi(art_ini.get(image, "TurretOffset", "0").c_str());
        va.hva_frames = static_cast<int>(std::max<std::size_t>(
            hull_h.frames.size(), std::max(tur_h.frames.size(), barl_h.frames.size())));
        if (va.hva_frames > 1 || va.turret_offset != 0)
            std::cerr << "[veh] " << image << " hva_frames=" << va.hva_frames << " turret_offset=" << va.turret_offset
                      << std::endl;
        // P2: the muzzle offset is also the projectile launch point (projectile.md
        // §4 step 1 -- FLH resolved before the bullet exists).
        for (int k = 0; k < 3; ++k) {
            va.combat.proj.flh[k] = va.flh[k];
            // Gap fix C: the other slots launch from the same muzzle.
            va.combat.elite_proj.flh[k] = va.flh[k];
            va.combat.secondary.proj.flh[k] = va.flh[k];
            va.combat.elite_secondary.proj.flh[k] = va.flh[k];
        }

        {   // G-16: keep the sources for per-colour sets.
            auto src = std::make_shared<VehicleAssets::VoxelSrc>();
            src->hull = hull_m; src->tur = tur_m; src->barl = barl_m;
            src->hull_h = hull_h; src->tur_h = tur_h; src->barl_h = barl_h;
            src->vpl = vpl;
            src->pal = unit_pal;
            src->alt_tur = std::move(alt_tur);
            if (rules.section_flag(unit_id, "NoSpawnAlt", false))
                src->has_wo = load_part(base + "wo", src->wo, src->wo_h);
            va.vsrc = src;
        }
        for (int house = 0; house <= 1; ++house) {
            const ra2assets::Palette hp = ra2engine::pal_for_house(unit_pal, house);
            va.hull[house] =
                ra2engine::build_facing_set(hull_m, hull_h, ra2engine::kVehicleFacings, vpl, hp);
            if (va.has_turret)
                va.turret[house] =
                    ra2engine::build_facing_set(tur_m, tur_h, ra2engine::kVehicleFacings, vpl, hp);
            if (va.has_barrel)
                va.barrel[house] =
                    ra2engine::build_facing_set(barl_m, barl_h, ra2engine::kVehicleFacings, vpl, hp);
        }

        // Death explosion (Rules::explosion_first -> SHP from conquer.mix,
        // drawn with anim.pal from cache.mix if present, else the unit pal).
        // Individually guarded: a missing explosion downgrades the death visual
        // (tank simply vanishes) but does NOT fail the whole vehicle load.
        va.explosion_image = rules.explosion_first(unit_id);
        va.explosion_pal = unit_pal;
        if (!va.explosion_image.empty()) {
            try {
                MixFile conquer = ra2.open_nested("conquer.mix");
                va.explosion =
                    std::make_unique<ShpFile>(load_unit_shp(conquer, va.explosion_image));
                try {
                    MixFile cache = ra2.open_nested("cache.mix");
                    const MixEntry* ape = cache.find(std::string("anim.pal"));
                    if (ape) {
                        auto apal = cache.read(*ape);
                        va.explosion_pal = Palette::load(apal.data(), apal.size());
                    }
                } catch (const std::exception&) { /* keep unit pal */ }
            } catch (const std::exception& ex) {
                std::cerr << "[vehicle] explosion SHP unavailable: " << ex.what() << "\n";
                va.explosion.reset();
            }
        }

        va.ok = true;
        const auto& hs = hull_m.sections.empty() ? ra2assets::VxlSection{} : hull_m.sections[0];
        std::cerr << "[vehicle] image=" << image << " facings=" << ra2engine::kVehicleFacings
                  << " hull=" << hs.size_x << "x" << hs.size_y << "x" << hs.size_z
                  << " turret=" << (va.has_turret ? "yes" : "no")
                  << " barrel=" << (va.has_barrel ? "yes" : "no")
                  << " speed_cps=" << va.combat.speed_cps << " rot=" << va.combat.rot << "\n";
    } catch (const std::exception& ex) {
        std::cerr << "[vehicle] assets unavailable (" << ex.what()
                  << "); running infantry-only\n";
        va.ok = false;
    }
    return va;
}

// Spawns `n` Rhino tanks per side (docs/re/voxel-render.md spawn rules): house 0
// 4 cells WEST of the GI origin (pick_start_cell), house 1 4 cells EAST of the
// CONS origin (GI origin + 8 east). Reuses spawn_squad verbatim with va.combat.
// Called ONLY when va.ok, and NEVER from the byte-identity-gated demos
// (--demo-combat/move/retarget/group) -- interactive/screenshot/demo-tank only.
void spawn_tank_squads(ra2engine::World& world, const Assets& a, const VehicleAssets& va, int n) {
    const ra2assets::MapCell* c = ra2engine::pick_start_cell(a.map);
    if (!c) return;
    spawn_squad(world, c->x - 4, c->y, n, /*house=*/0, va.combat);
    spawn_squad(world, c->x + 12, c->y, n, /*house=*/1, va.combat);
    std::cerr << "[world] spawned " << n << " tank(s)/side; total units now "
              << world.units().size() << "\n";
}

// The two harvester types the economy needs [RE: economy.md §1-§3], plus each
// type's Storage= (bales) and chrono flag. HARV/CMIN are voxel units loaded
// exactly like the Rhino (load_vehicle_assets: HARV has a turret, CMIN none).
// A type whose voxel assets fail to load keeps ok=false and is simply never
// spawned (economy silently degrades; a demo prints the [vehicle] failure).
struct MinerAssets {
    VehicleAssets harv;   // Soviet War Miner (drives home)
    VehicleAssets cmin;   // Allied Chrono Miner (warps home)
    int harv_storage = 40;
    int cmin_storage = 20;
};

MinerAssets load_miner_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                              const ra2assets::Palette& unit_pal, const Rules& rules) {
    load_progress("MINER ART");   // W2-AR-02 loading-screen checkpoint
    MinerAssets m;
    m.harv = load_vehicle_assets(dir, ra2, unit_pal, "HARV");
    m.cmin = load_vehicle_assets(dir, ra2, unit_pal, "CMIN");
    const int hs = rules.storage("HARV"), cs = rules.storage("CMIN");
    m.harv_storage = hs > 0 ? hs : 40;
    m.cmin_storage = cs > 0 ? cs : 20;
    std::cerr << "[miner] harv ok=" << (m.harv.ok ? "y" : "n") << " storage=" << m.harv_storage
              << " cmin ok=" << (m.cmin.ok ? "y" : "n") << " storage=" << m.cmin_storage << "\n";
    return m;
}

// Resolves a FreeUnit id (GAREFN->"CMIN", NAREFN->"HARV") to the loaded
// VehicleAssets + its chrono flag + storage; nullptr if the id isn't a known
// miner or its assets failed to load.
const VehicleAssets* miner_for_id(const MinerAssets& m, const std::string& id, bool& chrono,
                                  int& storage) {
    if (id == "HARV") { chrono = false; storage = m.harv_storage; return m.harv.ok ? &m.harv : nullptr; }
    if (id == "CMIN") { chrono = true;  storage = m.cmin_storage; return m.cmin.ok ? &m.cmin : nullptr; }
    return nullptr;
}

// CB-1: the demo/interactive multi-capacity transport [spec: Transport
// choice; RE: transport-cargo.md §1]. HTK (Soviet Flak Track: Passengers=5
// SizeLimit=2 Size=3, ground Drive, art PRESENT on this install) with FV
// (IFV, Passengers=1, already producible) as the art-guard fallback;
// multi-passenger logic is fully implemented regardless (capacity>1 is
// covered host-only by the pure tests). load_vehicle_assets already
// resolves the cargo stats via resolve_combat_unit, so a candidate is
// usable iff its art loaded AND it is actually a transport.
struct TransportAssets {
    VehicleAssets va;      // voxel render assets + combat (cargo stats included)
    std::string id;        // "HTK" or "FV"
    bool ok = false;       // art present AND Passengers > 0
};

TransportAssets load_transport_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                                      const ra2assets::Palette& unit_pal) {
    load_progress("TRANSPORT ART");   // W2-AR-02 loading-screen checkpoint
    TransportAssets ta;
    for (const char* id : {"HTK", "FV"}) {
        VehicleAssets va = load_vehicle_assets(dir, ra2, unit_pal, id);
        if (!va.ok || va.combat.passengers <= 0) continue;  // art-guard-drop ->
        ta.va = std::move(va);                              // try the fallback
        ta.id = id;
        ta.ok = true;
        break;
    }
    if (ta.ok)
        std::cerr << "[transport] id=" << ta.id
                  << " passengers=" << ta.va.combat.passengers
                  << " size_limit=" << ta.va.combat.size_limit
                  << " size=" << ta.va.combat.size << "\n";
    else
        std::cerr << "[transport] unavailable (HTK and FV art both missing); "
                     "cargo gestures degrade to no-ops\n";
    return ta;
}

// CB-2 Aircraft render assets [RE: aircraft.md]. load_vehicle_assets already
// resolves the flight stats via resolve_combat_unit, so a candidate is usable
// iff its voxel art loaded AND it is actually a flight-locomotor unit.
struct AircraftAssets {
    VehicleAssets va;      // voxel render assets + combat (flight stats included)
    std::string id;        // "ZEP", "ORCA", or "BEAG"
    bool ok = false;       // art present AND is_aircraft
};

AircraftAssets load_aircraft_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                                    const ra2assets::Palette& unit_pal) {
    AircraftAssets aa;
    for (const char* id : {"ZEP", "ORCA", "BEAG"}) {
        VehicleAssets va = load_vehicle_assets(dir, ra2, unit_pal, id);
        if (!va.ok || !va.combat.is_aircraft) continue;   // art-guard-drop -> fallback
        aa.va = std::move(va);
        aa.id = id;
        aa.ok = true;
        break;
    }
    if (aa.ok)
        std::cerr << "[aircraft] id=" << aa.id
                  << " cruise_alt=" << aa.va.combat.cruise_altitude
                  << " speed=" << aa.va.combat.flight_speed
                  << " climb=" << aa.va.combat.climb_rate
                  << " omni=" << (aa.va.combat.omni_fire ? "yes" : "no") << "\n";
    else
        std::cerr << "[aircraft] unavailable (ZEP/ORCA/BEAG art missing)\n";
    return aa;
}

// CB-3 Naval render assets [RE: naval.md §5]. A ship is a voxel vehicle at
// altitude 0 -- load_vehicle_assets already resolves the naval stats via
// resolve_combat_unit, so a candidate is usable iff its voxel art loaded AND it
// is actually a naval-locomotor unit. No new render work: the ship draws
// through the EXISTING draw_vehicle_unit/draw_voxel_sprite + facing_cache path.
struct NavalAssets {
    VehicleAssets va;      // voxel render assets + combat (naval flags included)
    std::string id;        // "HYD", "DRED", or "DEST"
    bool ok = false;       // art present AND is_naval
};

NavalAssets load_naval_assets(const std::string& dir, const ra2assets::MixFile& ra2,
                              const ra2assets::Palette& unit_pal) {
    NavalAssets na;
    for (const char* id : {"HYD", "DRED", "DEST"}) {
        VehicleAssets va = load_vehicle_assets(dir, ra2, unit_pal, id);
        if (!va.ok || !va.combat.is_naval) continue;   // art-guard-drop -> fallback
        na.va = std::move(va);
        na.id = id;
        na.ok = true;
        break;
    }
    if (na.ok)
        std::cerr << "[naval] id=" << na.id
                  << " strength=" << na.va.combat.strength
                  << " speed=" << na.va.combat.speed_cps
                  << " range=" << na.va.combat.range
                  << " domain=" << (na.va.combat.movement_domain ==
                                    ra2engine::MovementDomain::Water ? "water" : "land")
                  << "\n";
    else
        std::cerr << "[naval] unavailable (HYD/DRED/DEST art missing or not naval)\n";
    return na;
}

// The Allied producible-unit roster + its render/cameo assets [RE-GATE
// APPLIED: production.md §1.6]. `defs` holds each UnitTypeDef (index = the
// unit-queue slot type); `vehicles` holds one VehicleAssets per is_vehicle def
// (appended in def order, so the k-th vehicle def maps to vehicles[k]); the
// cameo SHP + present flag are parallel to `defs`. Infantry render/combat come
// from the existing UnitAssets pipeline + UnitTypeDef::combat, so no per-def
// infantry SHP store is needed here.
struct UnitRoster {
    std::vector<ra2engine::UnitTypeDef> defs;
    std::vector<VehicleAssets> vehicles;
    std::vector<ra2assets::ShpFile> cameos;  // parallel to defs
    std::vector<char> has_cameo;             // parallel to defs
};

// Every entry is opt-guarded: a def whose cost/tech/cameo is unusable, whose vehicle
// voxel assets fail to load, or whose combat can't resolve is DROPPED from
// `defs` (never a crash — mirrors Task 6's defense guard). Cameo SHPs load
// from cameo.mix (language.mix) exactly like building cameos, keyed by unit id.
// Hoisted from load_unit_roster so the AI-2 Soviet table reuses the loop.
struct UnitRosterEnt { const char* id; bool vehicle; const char* prereq; };

// Shared roster-loading loop [RE-GATE APPLIED: production.md §1.1/§1.6]. Loads
// the given (ents, n) into a UnitRoster with EVERY guard identical to the
// former load_unit_roster body (cost/tech/cameo drop, vehicle-asset drop,
// per-entry catch/log) — the GATOW/art-guard lesson. Consumed by the player
// roster (load_unit_roster) and the AI-2 Soviet roster (load_soviet_unit_roster).
UnitRoster load_unit_roster_table(const std::string& dir, const ra2assets::MixFile& ra2,
                                  const UnitAssets& ua, const Rules& rules, const Art& art,
                                  const UnitRosterEnt* ents, std::size_t n, bool full_parse) {
    UnitRoster ur;
    // cameo.mix lives inside language.mix (same chain load_building_assets uses
    // for building cameos); opened once here, guarded so a missing archive just
    // leaves every unit cameo absent (defs still gate on the cameo NAME string).
    std::unique_ptr<MixFile> cameo_mix;
    try {
        MixFile language = MixFile::open_path(dir + "language.mix");
        cameo_mix = std::make_unique<MixFile>(language.open_nested("cameo.mix"));
    } catch (const std::exception&) { cameo_mix.reset(); }

    for (std::size_t i = 0; i < n; ++i) {
        const UnitRosterEnt& e = ents[i];
        try {
            ra2engine::UnitTypeDef d;
            d.id = e.id;
            d.cost = rules.cost(e.id);
            d.tech_level = rules.tech_level(e.id);
            d.is_vehicle = e.vehicle;
            // CB-5 [RE-GATE APPLIED: techtree.md §1/§5]: the PLAYER roster full-parses
            // the real rulesmd [<id>] Prerequisite= (the same list buildings already
            // use, main.cpp:1435) so multi-token + group-token (TECH) unit prereqs
            // resolve through the EXISTING prerequisites_met. The SOVIET AI roster
            // keeps its hardcoded proxy token (APOC->NAWEAP) UNCHANGED to protect
            // ai_team_hash (spec §8; real [APOC] Prerequisite=NAWEAP,NATECH -- the
            // NATECH conjunct the AI base never builds, so dropping it in the proxy
            // never makes APOC buildable where the real rule would not; techtree.md
            // §5 CONFIRMED). Byte-identity anchor CONFIRMED (techtree.md §5):
            // [E1]=GAPILE, [GGI]=GAPILE, [MTNK]=GAWEAP, [FV]=GAWEAP -- ALL single
            // plain building tokens (no group token), so the full-parse resolves them
            // BYTE-IDENTICALLY to the retired hardcoded tokens. Defensive fallback to
            // the proxy token if rulesmd has no Prerequisite= for this id.
            if (full_parse) {
                d.prerequisite = rules.prerequisite(e.id);
                if (d.prerequisite.empty()) d.prerequisite = {e.prereq};
            } else {
                d.prerequisite = {e.prereq};
            }
            // DEVIATION from brief (`art.cameo(e.id)`): the cameo must come from
            // the unit's IMAGE art section (the one it actually renders as), not
            // the rules id. In this artmd.ini E1's section is [GI]
            // (Cameo=GIICON) and, critically, rules [MTNK] Image=GTNK — the
            // Grizzly — while the legacy [MTNK] art section is the *Apocalypse*
            // (Cameo=MTNKICON). Keying on rules.image(id) yields GTNK->GTNKICON
            // (Grizzly), the correct cameo. Fall back to the id-keyed section if
            // the image section has none.
            const std::string image = rules.image(e.id);
            d.cameo = art.cameo(image);
            if (d.cameo.empty()) d.cameo = art.cameo(e.id);
            if (d.cost <= 0 || d.tech_level <= 0 || d.cameo.empty()) continue;  // not producible

            // Cameo SHP (guarded; absence only downgrades the sidebar icon).
            ra2assets::ShpFile cshp;
            bool have_cameo = false;
            if (cameo_mix) {
                std::string cn = d.cameo;
                for (char& ch : cn) ch = (char)std::tolower((unsigned char)ch);
                if (const MixEntry* ce = cameo_mix->find(cn + ".shp")) {
                    try { cshp = ShpFile::load(cameo_mix->read(*ce)); have_cameo = true; }
                    catch (const std::exception&) { have_cameo = false; }
                }
            }

            if (e.vehicle && !art.voxel(image) &&
                to_lower(rules.section_string(e.id, "Locomotor", "")).find("2bea74e1") != std::string::npos) {
                // W2-AN-15 [RE: artmd [DLPH]/[SQD] Voxel=no WalkFrames= FiringFrames=]:
                // the Dolphin and the Giant Squid are SHP ships, not voxels --
                // their SHP is loaded by the scene (w2_setup) like an infantry body.
                const ResolvedUnit ru = resolve_combat_unit(rules, e.id);
                d.combat = ru.combat;
                d.combat.is_vehicle = true;
                d.combat.speed_cps = speed_to_cps(ru.speed);
                // W5-B: the SHP ship needs its ROT too -- with rot 0 its aim
                // facing never slewed onto a target, so the vehicle aim gate
                // (FireError::FACING) held the Giant Squid's / Dolphin's fire forever.
                d.combat.rot = rules.rot(e.id);
            } else if (e.vehicle && !art.voxel(image)) {
                // W6-04-10 [rules [DRON] TechLevel=4 Prerequisite=NAWEAP; artmd
                // [DRON] Voxel=no]: a LAND SHP vehicle (the Terror Drone) went to
                // the voxel loader, failed and was dropped -- no cameo, and the
                // AI roster lost it too. It rides the infantry path, the same
                // registration as the campaign (W3-FIX-A) and the cheat spawn
                // (W2-GA-11 draws it with the SHP-vehicle frame rule); it is
                // still built at the War Factory (UnitTypeDef::is_vehicle).
                const ResolvedUnit ru = resolve_combat_unit(rules, e.id);
                d.combat = ru.combat;
                d.combat.is_vehicle = false;
                d.combat.speed_cps = speed_to_cps(ru.speed);
            } else if (e.vehicle) {
                VehicleAssets va = load_vehicle_assets(dir, ra2, ua.pal, e.id);
                if (!va.ok) continue;                 // assets missing -> drop
                d.combat = va.combat;
                ur.vehicles.push_back(std::move(va));
            } else {
                const ResolvedUnit ru = resolve_combat_unit(rules, e.id);  // infantry combat + SHP image
                d.combat = ru.combat;
                d.combat.is_vehicle = false;
                d.combat.speed_cps = speed_to_cps(ru.speed);
            }
            ur.defs.push_back(std::move(d));
            ur.cameos.push_back(std::move(cshp));
            ur.has_cameo.push_back(have_cameo ? 1 : 0);
        } catch (const std::exception& ex) {
            std::cerr << "[unit-roster] " << e.id << " unavailable (" << ex.what() << ")\n";
        }
    }
    std::cerr << "[unit-roster] producible=" << ur.defs.size() << "\n";
    return ur;
}

// Loads the curated Allied producibles + assets [RE-GATE APPLIED:
// production.md §1.1/§1.6 — recovered per-unit prereqs are PLAIN building ids:
// E1/GGI=GAPILE, MTNK/FV=GAWEAP, not the Barracks/Factory group tokens].
UnitRoster load_unit_roster(const std::string& dir, const ra2assets::MixFile& ra2,
                            const UnitAssets& ua, const Rules& rules, const Art& art) {
    static const UnitRosterEnt kUnits[] = {
        {"E1",  false, "GAPILE"}, {"GGI", false, "GAPILE"},
        {"MTNK", true, "GAWEAP"}, {"FV",  true, "GAWEAP"},
        // CB-5 [RE-GATE APPLIED: techtree.md §4]: the Prism Tank (advanced tier-3
        // unit), appended at index 4 so E1/GGI/MTNK/FV (0..3) stay stable ->
        // --demo-prod's mtnk_slot/gi_slot lookups + prod_hash unaffected.
        // full_parse=true (Task 2) resolves its CONFIRMED real Prerequisite=GAWEAP,
        // GATECH (techtree.md §4; TechLevel=8, Cost=1200); the "GAWEAP" token here is
        // only the Task-2 defensive fallback. SREF art is PRESENT on this install
        // (sref.vxl+sref.hva in local.mix, cameo sreficon.shp in cameo.mix -- the
        // Prism Tank renders; techtree.md §4/§5) so NO synthetic unit fallback is
        // needed, but the art-guard stays defensively: were SREF SHP/cameo absent it
        // would be dropped from ur.defs and --demo-techtree would synthesize a probe
        // def (spec §6).
        {"SREF", true, "GAWEAP"},
    };
    return load_unit_roster_table(dir, ra2, ua, rules, art, kUnits, 5, /*full_parse=*/true);
}

