#include "pres_effects.inc"  // W3-FX particles / debris / trails / wakes / twinkles
#include "pres_compat.inc"  // W5-PRES hooks onto w4fix-seq / agent-B sim state
#include "pres_map.inc"
#include "pres_light.inc"    // W2-GA-05 map [Lighting]
#include "pres_layers.inc"   // W5-PRES R-100/R-101 deck + air layers
#include "pres_state.inc"    // W5-PRES R-120 Iron Curtain / elite flash / chrono warp
#include "pres_turret.inc"   // W2-GA-13 defence turrets
#include "w5_combat_arm.inc"  // W5-B: sub-cells / land speed / crush arming of the real World
// W8-03-02 / W8-03-01 (w8fix-place) -- the ONE overlay land-type hook
// (called by depth_set_terrain just before World::set_land_terrain):
//  1. FUN_0047D1C0's overlay branch on `lt` -- rocks/fences become Rock,
//     tracks Railroad (engine/overlay_land.hpp). The low-bridge overlays stay
//     with depth_set_terrain's own override (w8fix-bridge).
//  2. The static buildable grid of CanThisExistHere FUN_0047C530: Buildable
//     LandType, no non-ore overlay (bridges included), flat (TMP ramp 0).
void place_overlay_terrain(ra2engine::World& world, Assets& a, std::vector<ra2assets::LandType>& lt) {
    if (a.overlay_land.empty()) return;   // rules not read: legacy terrain
    const int gw = world.grid_w(), gh = world.grid_h();
    const std::size_t n = static_cast<std::size_t>(gw) * gh;
    std::vector<int> ovl(n, -1), lvl(n, 0);
    std::vector<std::uint8_t> ramp(n, 0), blocks(n, 0), land(n, 0);
    for (const ra2assets::MapCell& c : a.map.cells()) {
        if (c.x < 0 || c.y < 0 || c.x >= gw || c.y >= gh) continue;
        const std::size_t i = static_cast<std::size_t>(c.y) * gw + c.x;
        lvl[i] = c.level;
        if (const ra2assets::TmpFile* t = a.theater.tmp_for_tile(c.tile)) {
            if (c.subtile < t->count()) {
                try {
                    if (const std::uint8_t* hdr = t->image_header(c.subtile)) ramp[i] = hdr[42];
                } catch (const std::exception&) {}
            }
        }
        if (!a.map.has_overlay()) continue;
        const int id = a.map.overlay_at(c.x, c.y);
        if (id < 0 || id == 255) continue;
        ovl[i] = id;
        const bool ore = id < static_cast<int>(a.overlay_land.size()) && a.overlay_land[id].tiberium;
        blocks[i] = ore ? 0 : 1;   // ore is live (OreField); every other overlay refuses a building
    }
    ra2engine::apply_overlay_land(lt, ovl, lvl, gw, gh, a.overlay_land, kCliffBackImpassability,
                                  [](int id) { return ra2engine::is_low_bridge_overlay(id); });
    for (std::size_t i = 0; i < n && i < lt.size(); ++i) land[i] = static_cast<std::uint8_t>(lt[i]);
    world.set_build_static(ra2engine::buildable_static(land, blocks, ramp, {}, a.land_buildable));
}

#include "world_depth.inc"    // G16 (agent G): bridges/garrison arming of the real World      // G-87 [Terrain]/overlays/[Smudge]/neutral [Structures]
#include "pres_radar.inc"    // G-09 render half: isometric radar minimap

// Draws one building in render_world's merged back-to-front pass. Anchors the
// SHP canvas CENTER on the TOP vertex of the foundation's origin cell
// [RE: building-render.md §2, W4-FIX-POS -- BuildingClass vtbl+0xAC
// FUN_00459ee0 = Location - (128,128); RA2 FUN_00453c70], via the shared
// ra2engine::building_draw_point (bib, slot anims, fires, rubble too). State selects SHP + frame: Buildup -> buildup MK frame;
// Idle -> main frame 0 (healthy) / 1 (damaged, hp/max<=ConditionYellow); Dead
// -> explosion anim (TWLT070) over kBuildingDieSecs. `level` = the foundation
// origin cell's terrain level (buildings flatten their footprint).
void draw_building(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2engine::Building& b,
                   const BuildingAssets& ba, int level, double condition_yellow,
                   const ra2engine::Camera& cam, int W, int H,
                   const std::vector<ra2engine::Building>* all = nullptr) {
    if (b.type < 0 || b.type >= static_cast<int>(ba.art.size())) return;
    const BuildingArt& art = ba.art[b.type];
    if (!art.ok) return;
    if (art.invisible) return;   // W3-FIX-A InvisibleInGame=yes [RE: asset-search.md §3]
    const ra2engine::BuildingTypeDef& def = ba.roster[b.type];
    g_overlay_bld = &b;   // W2-GA-14: per-building anim state for the overlay pass
    g_overlay_id = def.id;   // W3-B

    // Foundation screen bbox = union of the fw*fh cell diamonds (60x30 rects).
    int minx = INT_MAX, miny = INT_MAX, maxx = INT_MIN, maxy = INT_MIN;
    for (int j = 0; j < b.fh; ++j)
        for (int i = 0; i < b.fw; ++i) {
            const ra2engine::ScreenPt p =
                ra2engine::cell_to_screen(b.cx + i, b.cy + j, level, 60, 30, 15);
            const int x0 = p.x + cam.x, y0 = p.y + cam.y;
            minx = std::min(minx, x0);
            miny = std::min(miny, y0);
            maxx = std::max(maxx, x0 + 60);
            maxy = std::max(maxy, y0 + 30);
        }
    // W4-FIX-POS: the draw point (canvas centre) is the origin cell's top
    // vertex; (minx..maxy) stays for the demo HP bar only.
    const ra2engine::ScreenPt dp = ra2engine::building_draw_point(b.cx, b.cy, level);
    const int fcx = dp.x + cam.x, fcy = dp.y + cam.y;

    // Dead: explosion anim at the draw point (render-only nicety).
    if (b.state == ra2engine::Building::State::Dead) {
        // W3-B LeaveRubble=yes: the rubble frame (and its shadow) stays.
        const int rf = (g_fx && !b.sold) ? pres_building_rubble_frame(def.id, art.shp.count()) : -1;
        if (rf >= 0 && rf < art.shp.count()) {
            const ra2assets::Palette rp =
                art.own_pal ? *art.own_pal : ra2engine::house_draw_palette(ba.unit_pal, b.house);
            g_fx->blit_shadow(ren, tc, art.shp, "rubs:" + def.id, rf + art.shp.count() / 2, fcx, fcy, W, H);
            g_fx->blit(ren, tc, art.shp, "rub:" + def.id + ":c" + std::to_string(ra2engine::house_draw_key(b.house)),
                       rf, fcx, fcy, 255, W, H, &rp);
        }
        if (!b.alive) return;
        // A SOLD building is Limbo()'d and deleted in the original -- it does
        // not explode [RE: repair-sell.md §B2 state 2].
        // G-83: in the live game the FX layer plays the type's Explosion= anims.
        if (ba.explosion && ba.explosion->count() > 0 && !b.sold && !g_fx) {
            int frame = static_cast<int>(b.die_time * 15.0);
            frame = std::clamp(frame, 0, ba.explosion->count() - 1);
            const ra2assets::ShpFile::Frame f = ba.explosion->frame_info(frame);
            SDL_Rect dst{fcx - ba.explosion->width() / 2 + f.x,
                         fcy - ba.explosion->height() / 2 + f.y, f.w, f.h};
            if (dst.x + dst.w <= 0 || dst.y + dst.h <= 0 || dst.x >= W || dst.y >= H) return;
            char key[96];
            std::snprintf(key, sizeof key, "bldx:%s:%d", def.id.c_str(), frame);
            SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
            if (!tex) {
                std::vector<uint8_t> idx = ba.explosion->decode_indexed(frame);
                tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, ba.explosion_pal));
            }
            SDL_RenderCopy(ren, tex, nullptr, &dst);
        }
        return;
    }

    // [RE: repair-sell.md §B2] A SELLING building plays the buildup range
    // MIRRORED (Shape_Number's `start + count - stage - 1`) -- the buildup runs
    // BACKWARDS over the same frame count at the same rate. `selling` is false
    // on every gate path, so the two original branches are unchanged there.
    const bool selling = (b.selling && art.has_buildup);
    const bool buildup =
        selling || (b.state == ra2engine::Building::State::Buildup && art.has_buildup);
    const ra2assets::ShpFile& shp = buildup ? art.buildup : art.shp;
    int frame = selling ? ra2engine::mirrored_buildup_frame(b, art.buildup.count())
              : buildup ? ra2engine::buildup_frame(b, art.buildup.count())
                        : ra2engine::building_frame(b, art.shp.count(), condition_yellow);
    // W3-B: CanBeOccupied 4-state / Gate stages (live game only, g_fx).
    if (!buildup && g_fx) frame = pres_building_main_frame(b, def.id, def.image.empty() ? def.id : def.image,
                                                         frame, art.shp.count(), condition_yellow);
    // [RE: roster2.md TL;DR 2/3, §D] a wall draws its connection frame:
    // stage*16 + the N/E/S/W same-wall/same-house mask (Wall_Update). Render-only.
    if (!buildup && all && b.type < static_cast<int>(ba.wall.size()) && ba.wall[b.type] &&
        art.shp.count() >= 32) {
        auto same_wall = [&](int x, int y) {
            for (const ra2engine::Building& o : *all)
                if (o.alive && o.state != ra2engine::Building::State::Dead && o.type == b.type &&
                    o.house == b.house && o.cx == x && o.cy == y)
                    return true;
            return false;
        };
        frame = ra2engine::wall_frame(ra2engine::wall_mask(b.cx, b.cy, same_wall),
                                      ra2engine::wall_stage(b.hp, b.max_hp, condition_yellow));
    }
    if (frame < 0 || frame >= shp.count()) return;
    // G-85: ActiveAnim/Bib/damage-fire overlays (live game only; g_fx null in gates).
    const bool overlay = g_fx && !buildup && b.state == ra2engine::Building::State::Idle;
    const bool bdamaged = b.max_hp > 0 && b.hp <= condition_yellow * b.max_hp;
    const ra2assets::Palette opal = overlay ? ra2engine::house_draw_palette(ba.unit_pal, b.house) : ba.unit_pal;
    const std::string& oimg = def.image.empty() ? def.id : def.image;
    if (overlay)
        pres_building_overlay(ren, tc, oimg, fcx, fcy, bdamaged, !(b.house == g_local_house && g_pres_low_power), opal,
                              ra2engine::house_draw_key(b.house), W, H, 0);
    // G-85: the shadow half (frame + Frames/2) first, darkened 50 % [RE:
    // presentation.md §7, FUN_00705290 + the Darken blitter dst = dst >> 1].
    if (overlay && shp.count() >= 2 && frame < shp.count() / 2) {
        const int sf = frame + shp.count() / 2;
        const ra2assets::ShpFile::Frame s = shp.frame_info(sf);
        if (s.w > 0 && s.h > 0) {
            char skey[96];
            std::snprintf(skey, sizeof skey, "bldsh:%s:%c:%d", def.id.c_str(), buildup ? 'b' : 'm', sf);
            SDL_Texture* st = static_cast<SDL_Texture*>(tc.peek(skey));
            if (!st) {
                const std::vector<uint8_t> si = shp.decode_indexed(sf);
                std::vector<uint8_t> rgba(si.size() * 4, 0);
                for (std::size_t k = 0; k < si.size(); ++k) if (si[k]) rgba[k * 4 + 3] = 128;
                st = static_cast<SDL_Texture*>(tc.get_rgba(skey, rgba.data(), s.w, s.h));
            }
            SDL_Rect sd{fcx - shp.width() / 2 + s.x, fcy - shp.height() / 2 + s.y, s.w, s.h};
            SDL_RenderCopy(ren, st, nullptr, &sd);
        }
    }
    const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
    SDL_Rect dst{fcx - shp.width() / 2 + f.x, fcy - shp.height() / 2 + f.y, f.w, f.h};
    if (!(dst.x + dst.w <= 0 || dst.y + dst.h <= 0 || dst.x >= W || dst.y >= H)) {
        char key[96];
        std::snprintf(key, sizeof key, "bld:%s:%c:c%d:%d", def.id.c_str(), buildup ? 'b' : 'm',
                      ra2engine::house_draw_key(b.house), frame);
        SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
        if (!tex) {
            std::vector<uint8_t> idx = shp.decode_indexed(frame);
            // W3-FIX-A: art Palette= draws through that palette, unremapped.
            const ra2assets::Palette hp =
                art.own_pal ? *art.own_pal : ra2engine::house_draw_palette(ba.unit_pal, b.house);   // G-16
            tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, hp));
        }
        ra2engine::blit_object(ren, tex, &dst);   // W5-PRES ObjTint (none in the gates)
    }
    if (overlay)
        pres_building_overlay(ren, tc, oimg, fcx, fcy, bdamaged, !(b.house == g_local_house && g_pres_low_power), opal,
                              ra2engine::house_draw_key(b.house), W, H, 1);
    // W4-FIX-POS: RA2_POS_DBG=1 outlines the foundation (magenta) and marks
    // the draw point (green x) -- the visual check for the anchor.
    static const bool pos_dbg = std::getenv("RA2_POS_DBG") != nullptr;
    if (pos_dbg) {
        SDL_SetRenderDrawColor(ren, 255, 0, 255, 255);
        for (int j = 0; j < b.fh; ++j)
            for (int i = 0; i < b.fw; ++i) {
                const ra2engine::ScreenPt p = ra2engine::cell_to_screen(b.cx + i, b.cy + j, level, 60, 30, 15);
                const int x = p.x + cam.x, y = p.y + cam.y;
                const SDL_Point d[5] = {{x + 30, y}, {x + 60, y + 15}, {x + 30, y + 30}, {x, y + 15}, {x + 30, y}};
                SDL_RenderDrawLines(ren, d, 5);
            }
        SDL_SetRenderDrawColor(ren, 40, 255, 40, 255);
        SDL_RenderDrawLine(ren, fcx - 6, fcy - 6, fcx + 6, fcy + 6);
        SDL_RenderDrawLine(ren, fcx - 6, fcy + 6, fcx + 6, fcy - 6);
    }

    // Foundation-width HP bar when damaged (render-only). W2-GA-19: the live
    // game (g_map_dressing set) shows building health only on the SELECTED
    // building (GameScene::draw_selected_building's pips, ConditionYellow/
    // Red), as the original does; the demos keep this debug bar.
    if (!g_map_dressing && b.hp < b.max_hp && b.max_hp > 0) {
        const int bw = std::max(24, maxx - minx - 8);
        const int bx = (minx + maxx) / 2 - bw / 2, by = miny - 6;
        SDL_Rect bg{bx - 1, by - 1, bw + 2, 5};
        SDL_SetRenderDrawColor(ren, 0, 0, 0, 200);
        SDL_RenderFillRect(ren, &bg);
        const double frac = static_cast<double>(b.hp) / b.max_hp;
        SDL_Rect fg{bx, by, static_cast<int>(bw * frac), 3};
        if (frac > 2.0 / 3) SDL_SetRenderDrawColor(ren, 0, 220, 0, 255);
        else if (frac > 1.0 / 3) SDL_SetRenderDrawColor(ren, 220, 220, 0, 255);
        else SDL_SetRenderDrawColor(ren, 220, 0, 0, 255);
        SDL_RenderFillRect(ren, &fg);
    }
}

// W6-01-01: true when building `b`'s drawn art has an opaque pixel at window
// pixel (px, py): the main frame draw_building uses (the SAME SHP / frame /
// anchor: buildup, mirrored sell, healthy / damaged) and, in the live game,
// its always-on slot anims (ActiveAnim..Four, IdleAnim, SuperAnim..Four --
// the Prism Tower's head, the Weather Device's dish) at their slot offsets.
// `masks` caches each decoded frame (key = SHP address + frame). The touch
// pick tests this before the original foundation pick (Input::pick_building).
// Turrets and a wall's connection frame are not tested: the foundation
// fallback covers walls.
using ArtMaskCache = std::map<std::pair<const void*, int>, std::vector<uint8_t>>;
bool shp_frame_opaque(const ra2assets::ShpFile& shp, int frame, int cx, int cy, int px, int py,
                      ArtMaskCache& masks) {
    if (frame < 0 || frame >= shp.count()) return false;
    const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
    const int x0 = cx - shp.width() / 2 + f.x, y0 = cy - shp.height() / 2 + f.y;
    if (f.w <= 0 || f.h <= 0 || px < x0 || py < y0 || px >= x0 + f.w || py >= y0 + f.h) return false;
    const auto key = std::make_pair(static_cast<const void*>(&shp), frame);
    auto it = masks.find(key);
    if (it == masks.end()) it = masks.emplace(key, shp.decode_indexed(frame)).first;
    const std::size_t k = static_cast<std::size_t>(py - y0) * f.w + static_cast<std::size_t>(px - x0);
    return k < it->second.size() && it->second[k] != 0;
}
bool building_art_opaque(const ra2engine::Building& b, const BuildingAssets& ba, int level,
                         double condition_yellow, const ra2engine::Camera& cam, int px, int py,
                         ArtMaskCache& masks) {
    if (b.type < 0 || b.type >= static_cast<int>(ba.art.size())) return false;
    const BuildingArt& art = ba.art[b.type];
    if (!art.ok || art.invisible) return false;
    const bool selling = (b.selling && art.has_buildup);
    const bool buildup =
        selling || (b.state == ra2engine::Building::State::Buildup && art.has_buildup);
    const ra2assets::ShpFile& shp = buildup ? art.buildup : art.shp;
    const int frame = selling ? ra2engine::mirrored_buildup_frame(b, art.buildup.count())
                    : buildup ? ra2engine::buildup_frame(b, art.buildup.count())
                              : ra2engine::building_frame(b, art.shp.count(), condition_yellow);
    const ra2engine::ScreenPt dp = ra2engine::building_draw_point(b.cx, b.cy, level);
    const int fcx = dp.x + cam.x, fcy = dp.y + cam.y;
    if (shp_frame_opaque(shp, frame, fcx, fcy, px, py, masks)) return true;
    if (buildup || !g_fx || b.type >= static_cast<int>(ba.roster.size())) return false;
    const ra2engine::BuildingTypeDef& def = ba.roster[b.type];
    const PresFx::BldAnims& an = g_fx->building(pres_upper(def.image.empty() ? def.id : def.image));
    static const int kSlots[] = {kBsActive, kBsActive + 1, kBsActive + 2, kBsActive4, kBsIdle,
                                 kBsSuper, kBsSuper + 1, kBsSuper + 2, kBsSuper4};
    for (int s : kSlots) {
        const PresFx::BldAnims::Slot& sl = an.slot[s];
        if (!sl.t || !sl.t->shp) continue;
        if (shp_frame_opaque(*sl.t->shp, sl.t->start, fcx + sl.x, fcy + sl.y + sl.t->ydraw, px, py, masks))
            return true;
    }
    return false;
}

// Draws one voxel vehicle in render_world's back-to-front loop: a dying tank
// shows the death-explosion SHP (frame = min(die_time*15, count-1), the same
// 15 fps as infantry deaths); a live tank draws its hull, then (if turreted)
// turret + barrel facing sprites via the cached FacingSets, then -- while
// firing -- a muzzle flash at the PrimaryFireFLH point (docs/re/voxel-render.md
// §6: rotate (F, L) by the quantized turret yaw, leptons->cells /256, project
// with the same 60x30 diamond shear draw_unit uses; H raises the flash).
// Voxel sprite sets exist for houses 0/1 only (VehicleAssets::hull[2]); a
// campaign/multi-house world draws every other house with set 1. Houses 0/1
// map to themselves, so every existing render is unchanged. [P10]
inline int vxl_house(int h) { return h == 0 ? 0 : 1; }
// G-16 (render): the facing set for part (0 hull, 1 turret, 2 barrel) in house
// h's colour. Unconfigured worlds (every gate) keep the pre-built blue/red sets;
// a configured skirmish rasterizes each MP colour once, on first draw.
std::shared_ptr<std::array<ra2engine::FacingSet, 3>> vxl_build_color(const VehicleAssets& va, int key) {
    auto set = std::make_shared<std::array<ra2engine::FacingSet, 3>>();
    const VehicleAssets::VoxelSrc& s = *va.vsrc;
    const ra2assets::Palette hp = ra2engine::pal_for_color(s.pal, key - 10);
    (*set)[0] = ra2engine::build_facing_set(s.hull, s.hull_h, ra2engine::kVehicleFacings, s.vpl, hp);
    if (va.has_turret)
        (*set)[1] = ra2engine::build_facing_set(s.tur, s.tur_h, ra2engine::kVehicleFacings, s.vpl, hp);
    if (va.has_barrel)
        (*set)[2] = ra2engine::build_facing_set(s.barl, s.barl_h, ra2engine::kVehicleFacings, s.vpl, hp);
    return set;
}
const ra2engine::FacingSet& vxl_set(const VehicleAssets& va, int part, int house) {
    const int key = ra2engine::house_draw_key(house);
    if (key < 10 || !va.vsrc) {
        const int hi = vxl_house(house);
        return part == 0 ? va.hull[hi] : part == 1 ? va.turret[hi] : va.barrel[hi];
    }
    std::lock_guard<std::mutex> lk(g_vxl_mu);
    auto& slot = va.color_sets[key];
    if (!slot) slot = vxl_build_color(va, key);   // not prewarmed yet: build now
    return (*slot)[part];
}
// W2-GA-P4: rasterise a (vehicle, colour) set off the draw path; a no-op when
// the draw path got there first.
void vxl_prewarm(const VehicleAssets& va, int key) {
    if (key < 10 || !va.vsrc) return;
    {
        std::lock_guard<std::mutex> lk(g_vxl_mu);
        auto it = va.color_sets.find(key);
        if (it != va.color_sets.end() && it->second) return;
    }
    auto built = vxl_build_color(va, key);   // outside the lock
    std::lock_guard<std::mutex> lk(g_vxl_mu);
    auto& slot = va.color_sets[key];
    if (!slot) slot = std::move(built);
}
// W2-GA-12: the hull's ground shadow at facing bi (built once per type).
const ra2engine::VoxelSprite* vxl_shadow(const VehicleAssets& va, int bi) {
    if (!va.vsrc) return nullptr;
    std::lock_guard<std::mutex> lk(g_vxl_mu);
    if (!va.shadow) {
        auto v = std::make_shared<std::vector<ra2engine::VoxelSprite>>();
        // W7-12-44 [RE: 0x73A3A0 tail / 0x4144B0 -> FUN_004DAFE0(body,
        // ShadowIndex) -> FUN_00706710: only that section, HVA frame 0]: the
        // rotor-less DUMMY01 silhouette of SHAD / SCHP / SPYP.
        const ra2assets::VxlModel* m = &va.vsrc->hull;
        const ra2assets::HvaModel* h = &va.vsrc->hull_h;
        ra2assets::VxlModel one;
        ra2assets::HvaModel one_h;
        const int si = va.shadow_index;
        if (si > 0 && si < static_cast<int>(m->sections.size()) && !h->frames.empty() &&
            si < static_cast<int>(h->frames[0].size())) {
            one = *m;
            one.sections = {m->sections[static_cast<std::size_t>(si)]};
            one_h.frame_count = 1;
            one_h.frames = {{h->frames[0][static_cast<std::size_t>(si)]}};
            m = &one;
            h = &one_h;
        }
        for (int i = 0; i < ra2engine::kVehicleFacings; ++i)
            v->push_back(ra2engine::rasterize_shadow(*m, *h, ra2engine::index_to_yaw(i, ra2engine::kVehicleFacings), 128));
        va.shadow = v;
    }
    if (bi < 0 || bi >= static_cast<int>(va.shadow->size())) return nullptr;
    return &(*va.shadow)[static_cast<std::size_t>(bi)];
}
// W3-B: one part at facing `fi`, HVA frame `hf` > 0, in the house colours
// (rasterised on first use; only multi-frame models ever ask).
const ra2engine::VoxelSprite& vxl_frame_sprite(const VehicleAssets& va, int part, int house, int fi, int hf) {
    static std::map<std::string, ra2engine::VoxelSprite> cache;
    static const ra2engine::VoxelSprite empty;
    if (!va.vsrc) return empty;
    const std::string key = va.combat.image + ":" + std::to_string(part) + ":" +
                            std::to_string(ra2engine::house_draw_key(house)) + ":" + std::to_string(fi) + ":" +
                            std::to_string(hf);
    std::lock_guard<std::mutex> lk(g_vxl_mu);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;
    const VehicleAssets::VoxelSrc& s = *va.vsrc;
    const ra2assets::VxlModel& m = part == 0 ? s.hull : part == 1 ? s.tur : s.barl;
    const ra2assets::HvaModel& h = part == 0 ? s.hull_h : part == 1 ? s.tur_h : s.barl_h;
    const ra2assets::Palette hp = ra2engine::house_draw_palette(s.pal, house);
    return cache.emplace(key, ra2engine::rasterize_model(m, h, ra2engine::index_to_yaw(fi, ra2engine::kVehicleFacings),
                                                         s.vpl, hp, hf)).first->second;
}
// W7-03-05/07: turret model `n` >= 1 at facing `fi` (rasterised on first use).
const ra2engine::VoxelSprite* vxl_alt_turret(const VehicleAssets& va, int n, int house, int fi, int hf) {
    if (!va.vsrc || n < 1 || n > static_cast<int>(va.vsrc->alt_tur.size())) return nullptr;
    static std::map<std::string, ra2engine::VoxelSprite> cache;
    const std::string key = va.combat.image + ":t" + std::to_string(n) + ":" +
                            std::to_string(ra2engine::house_draw_key(house)) + ":" + std::to_string(fi) + ":" +
                            std::to_string(hf);
    std::lock_guard<std::mutex> lk(g_vxl_mu);
    auto it = cache.find(key);
    if (it != cache.end()) return &it->second;
    const VehicleAssets::VoxelSrc& s = *va.vsrc;
    const auto& t = s.alt_tur[static_cast<std::size_t>(n - 1)];
    const ra2assets::Palette hp = ra2engine::house_draw_palette(s.pal, house);
    const int f = t.second.frames.empty() ? 0 : hf % static_cast<int>(t.second.frames.size());
    return &cache.emplace(key, ra2engine::rasterize_model(t.first, t.second,
                                                          ra2engine::index_to_yaw(fi, ra2engine::kVehicleFacings),
                                                          s.vpl, hp, f)).first->second;
}
// The current turret model index of `u`:
//  * W7-03-07 [RE: TechnoClass::AI 0x6F9380 -- IsChargeTurret (+0x810) and
//    multiple turrets: CurrentTurretNumber = TurretCount (+0x808) * the
//    RearmTimer's time left / its length, clamped to [0, TurretCount-1]];
//  * W7-03-05 [rules [FV] <Mode>TurretIndex / <Mode>TurretWeapon]: a Gunner
//    shows the turret its current weapon index maps to.
int pres_turret_index(const ra2engine::Unit& u, const VehicleAssets& va) {
    if (!va.vsrc || va.vsrc->alt_tur.empty() || !g_walk_rules) return 0;
    const std::string id = pres_type_id(u);
    struct TI { bool charge = false; int count = 1; std::map<int, int> by_weapon; };
    static std::map<std::string, TI> cache;
    auto it = cache.find(id);
    if (it == cache.end()) {
        TI t;
        const std::string ct = pres_lower(pres_clean(g_walk_rules->get(id, "IsChargeTurret")));
        t.charge = !ct.empty() && (ct[0] == 'y' || ct[0] == 't' || ct[0] == '1');
        t.count = std::max(1, std::atoi(pres_clean(g_walk_rules->get(id, "TurretCount")).c_str()));
        for (const auto& kv : g_walk_rules->section(id)) {
            const std::string k = kv.first;
            const std::string suf = "TurretWeapon";
            if (k.size() > suf.size() && k.compare(k.size() - suf.size(), suf.size(), suf) == 0) {
                const std::string mode = k.substr(0, k.size() - suf.size());
                const std::string ix = pres_clean(g_walk_rules->get(id, mode + "TurretIndex"));
                if (!ix.empty()) t.by_weapon[std::atoi(pres_clean(kv.second).c_str())] = std::atoi(ix.c_str());
            }
        }
        it = cache.emplace(id, t).first;
    }
    const TI& t = it->second;
    int n = 0;
    if (t.charge) {
        const int len = std::max(1, u.w_rof);
        n = std::clamp(t.count * std::max(0, u.rearm_frames) / len, 0, t.count - 1);
    } else if (u.abil.gunner) {
        auto w = t.by_weapon.find(u.ifv_current);
        if (w != t.by_weapon.end()) n = w->second;
    }
    return std::clamp(n, 0, static_cast<int>(va.vsrc->alt_tur.size()));
}
void draw_vehicle_unit(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2engine::Unit& u,
                       const VehicleAssets& va, const ra2engine::Camera& cam, int W, int H) {
    // W2-AN-07/25: a crashing flier keeps its hull until impact; a sinking
    // ship (ShipSinkingWeight) slides under instead of exploding.
    // W7-12-11: in the live game the sinking hull is the presentation's
    // (draw_sinking_hulls), not the dying unit.
    if (u.die_time >= 0.0 && u.an.sinking && g_fx && g_sink_drop_px == 0) return;
    if (u.die_time >= 0.0 && !u.an.crashing && !u.an.sinking) {
        // W3-B: in the live game the FX layer plays a RANDOM Explosion= entry
        // (Presentation::unit_fx_tick) [RE: presentation.md §5 FUN_007376c0].
        if (va.explosion && va.explosion->count() > 0 && !g_fx) {
            int frame = static_cast<int>(u.die_time * 15.0);
            if (frame >= va.explosion->count()) frame = va.explosion->count() - 1;
            if (frame < 0) frame = 0;
            // Reuse draw_unit's SHP canvas-center anchor. house 1 -> identity
            // pal_for_house remap, so the explosion keeps its own fire colors
            // (a house-0 remap would recolor any 16..31 indices to blue).
            ra2engine::Unit tmp = u;
            tmp.frame = frame;
            tmp.image = va.explosion_image;
            tmp.house = 1;
            ra2engine::draw_unit(ren, tc, tmp, *va.explosion, va.explosion_pal, cam, W, H);
        }
        return;  // dying vehicle: explosion instead of the tank
    }

    const std::string& img = va.combat.image;
    const int bi = ra2engine::facing_to_index(u.body_facing, ra2engine::kVehicleFacings);

    // CB-2 Aircraft [RE-GATE APPLIED: aircraft.md §3]: an airborne unit is drawn RAISED
    // by altitude_to_screen_dy, with a ground shadow at the un-raised cell.
    // Guarded on is_aircraft && altitude > 0 -- no existing demo spawns an
    // aircraft, so no existing screenshot changes [spec §8].
    const int extra_dy =
        g_sink_drop_px > 0 ? -g_sink_drop_px   // W7-12-11: the presentation's sinking hull
        : (u.is_aircraft && u.altitude > 0.0) ? ra2engine::altitude_to_screen_dy(u.altitude) +
                                                  pres_jumpjet_wobble_px(g_draw_unit_idx, u)   // W5-PRES wobble
        : (u.an.sinking && u.die_time >= 0.0) ? -static_cast<int>(u.die_time * 24.0)   // W2-AN-25
        : 0;
    if (u.an.t.no_shadow || g_sink_drop_px > 0) {   // W7-12-11: no shadow while sinking
        // W4: NoShadow=yes (V3ROCKET / DMISL) -- no ground shadow at all.
    } else if (extra_dy > 0 && g_map_dressing && vxl_shadow(va, bi)) {
        // W5-PRES [RE: Shadow_Point 0x55A550 / AircraftClass::Draw 0x4144B0 /
        // FUN_00755680]: an airborne voxel casts its own silhouette straight
        // down on the ground, same size at any height (live game).
        ra2engine::draw_voxel_sprite(ren, tc, "vxlsh:" + img + ":" + std::to_string(bi), *vxl_shadow(va, bi), u.fx,
                                     u.fy, u.level, cam, W, H, 0);
    } else if (extra_dy > 0)
        ra2engine::draw_ground_shadow(ren, u.fx, u.fy, u.level,
                                      vxl_set(va, 0, u.house).sprites[bi].w, cam, W, H);
    else if (const ra2engine::VoxelSprite* sh = vxl_shadow(va, bi))
        ra2engine::draw_voxel_sprite(ren, tc, "vxlsh:" + img + ":" + std::to_string(bi), *sh, u.fx, u.fy,
                                     u.level, cam, W, H, 0);   // W2-GA-12 ground shadow

    // W3-B: a multi-frame HVA (Night Hawk / Spy Plane rotors, Kirov
    // propellers) shows frame WalkedFramesSoFar % frames [RE: voxel draw
    // FUN_0073a3a0 reads the walk stage +0x538 modulo the HVA frame count].
    const int hf = va.hva_frames > 1 ? pres_walk_stage(g_draw_unit_idx) % va.hva_frames : 0;
    auto part_sprite = [&](int part, int fi) -> const ra2engine::VoxelSprite& {
        if (hf == 0) return vxl_set(va, part, u.house).sprites[fi];
        return vxl_frame_sprite(va, part, u.house, fi, hf);
    };
    const std::string fkey = hf ? ":f" + std::to_string(hf) : std::string();
    // W4: a RocketLocomotion rocket draws its hull at its pitch (the tilt on
    // the launcher, the climb, the arc, the dive) [FUN_00661D00 +0x50].
    if (u.an.t.missile && va.vsrc && std::fabs(u.an.rocket.pitch) > 1e-3) {
        const int pq = static_cast<int>(std::lround(u.an.rocket.pitch * 180.0 / 3.14159265358979 / 5.0));
        const std::string key = "vxlp:" + img + ":" + std::to_string(ra2engine::house_draw_key(u.house)) + ":" +
                                std::to_string(bi) + ":" + std::to_string(pq);
        static std::map<std::string, ra2engine::VoxelSprite> pitched;
        auto it = pitched.find(key);
        if (it == pitched.end()) {
            const VehicleAssets::VoxelSrc& s = *va.vsrc;
            it = pitched.emplace(key, ra2engine::rasterize_model(
                                          s.hull, s.hull_h, ra2engine::index_to_yaw(bi, ra2engine::kVehicleFacings),
                                          s.vpl, ra2engine::house_draw_palette(s.pal, u.house), 0,
                                          pq * 5.0 * 3.14159265358979 / 180.0)).first;
        }
        ra2engine::draw_voxel_sprite(ren, tc, key, it->second, u.fx, u.fy, u.level, cam, W, H, extra_dy);
        return;
    }
    // W7-06-12 / W7-04-27: out of spawns -> the xxxxWO hull [RE-FALLBACK: the
    // draw consumer of NoSpawnAlt was not traced; spawn_ready == 0 = none docked].
    if (va.vsrc && va.vsrc->has_wo && u.an.t.spawns_number > 0 && u.an.spawn_ready == 0) {
        static std::map<std::string, ra2engine::VoxelSprite> wo_cache;
        const std::string key = "vxl:" + img + ":wo:" + std::to_string(ra2engine::house_draw_key(u.house)) + ":" +
                                std::to_string(bi);
        const ra2engine::VoxelSprite* spr = nullptr;
        {
            std::lock_guard<std::mutex> lk(g_vxl_mu);
            auto it = wo_cache.find(key);
            if (it == wo_cache.end())
                it = wo_cache.emplace(key, ra2engine::rasterize_model(
                                               va.vsrc->wo, va.vsrc->wo_h,
                                               ra2engine::index_to_yaw(bi, ra2engine::kVehicleFacings), va.vsrc->vpl,
                                               ra2engine::house_draw_palette(va.vsrc->pal, u.house), 0)).first;
            spr = &it->second;
        }
        ra2engine::draw_voxel_sprite(ren, tc, key, *spr, u.fx, u.fy, u.level, cam, W, H, extra_dy);
    } else
    ra2engine::draw_voxel_sprite(
        ren, tc, "vxl:" + img + ":h:" + std::to_string(ra2engine::house_draw_key(u.house)) + ":" + std::to_string(bi) + fkey,
        part_sprite(0, bi), u.fx, u.fy, u.level, cam, W, H, extra_dy);
    if (va.has_turret) {
        const int ti = ra2engine::facing_to_index(u.turret_facing, ra2engine::kVehicleFacings);
        // W3-B TurretOffset: forward along the BODY facing (FLH axes, §6).
        double tfx = u.fx, tfy = u.fy;
        if (va.turret_offset != 0) {
            const double yaw = ra2engine::index_to_yaw(bi, ra2engine::kVehicleFacings);
            const double f = va.turret_offset / 256.0;
            tfx += f * std::cos(yaw);
            tfy -= f * std::sin(yaw);
        }
        const int tn = pres_turret_index(u, va);   // W7-03-05/07
        const ra2engine::VoxelSprite* alt = tn > 0 ? vxl_alt_turret(va, tn, u.house, ti, hf) : nullptr;
        auto draw_turret = [&]() {
            if (alt)
                ra2engine::draw_voxel_sprite(ren, tc,
                                             "vxl:" + img + ":t" + std::to_string(tn) + ":" +
                                                 std::to_string(ra2engine::house_draw_key(u.house)) + ":" +
                                                 std::to_string(ti) + fkey,
                                             *alt, tfx, tfy, u.level, cam, W, H, extra_dy);
            else
                ra2engine::draw_voxel_sprite(
                    ren, tc, "vxl:" + img + ":t:" + std::to_string(ra2engine::house_draw_key(u.house)) + ":" + std::to_string(ti) + fkey,
                    part_sprite(1, ti), tfx, tfy, u.level, cam, W, H, extra_dy);
        };
        auto draw_barrel = [&]() {
            if (va.has_barrel)
                ra2engine::draw_voxel_sprite(
                    ren, tc, "vxl:" + img + ":b:" + std::to_string(ra2engine::house_draw_key(u.house)) + ":" + std::to_string(ti) + fkey,
                    part_sprite(2, ti), tfx, tfy, u.level, cam, W, H, extra_dy);
        };
        // W7-12-41 [RE: 0x73A3A0 @0x73ACBB-0x73ADD4 -- q = ((turret facing
        // >> 13) + 1 >> 1) & 3; q 0 (N) or 3 (W) draws the barrel BEFORE the
        // turret, else after].
        const int q = (((static_cast<int>(u.turret_facing) & 0xFFFF) >> 13) + 1 >> 1) & 3;
        if (q == 0 || q == 3) {
            draw_barrel();
            draw_turret();
        } else {
            draw_turret();
            draw_barrel();
        }
    }

    // Muzzle flash at the FLH point while firing (voxel-render.md §6).
    if (u.fire_flash > 0.0 && !g_fx) {   // G-83: the FX layer draws the weapon's Anim= instead
        const double yaw = ra2engine::index_to_yaw(
            ra2engine::facing_to_index(u.turret_facing, ra2engine::kVehicleFacings),
            ra2engine::kVehicleFacings);
        const double fc = va.flh[0] / 256.0, lc = va.flh[1] / 256.0;  // leptons -> cells
        const double mx = fc * std::cos(yaw) - lc * std::sin(yaw);    // cells, model X
        const double my = fc * std::sin(yaw) + lc * std::cos(yaw);    // cells, model Y
        const int flash_dx = static_cast<int>(std::lround((mx + my) * 30.0));
        // H (up) term: the recovered vertical scale is 0.866·60/√2 ≈ 36.74 px
        // per cell-of-z (docs/re/voxel-render.md §6 FLH via §1's buf_y = ... −
        // 0.866·v.z coefficient, in 256√2/60 px-per-lepton units), NOT the
        // 30 px/cell diamond half-height that applies to the F/L ground plane.
        const int flash_dy =
            static_cast<int>(std::lround((mx - my) * 15.0 - (va.flh[2] / 256.0) * 36.74));
        const int cx = static_cast<int>(std::lround((u.fx - u.fy) * 30.0)) + cam.x + 30;
        const int cy =
            static_cast<int>(std::lround((u.fx + u.fy) * 15.0 - u.level * 15)) + cam.y + 15 -
            extra_dy;   // CB-2: track the raised hull when airborne
        SDL_Rect fr{cx + flash_dx - 3, cy + flash_dy - 3, 6, 6};
        if (!(fr.x + fr.w <= 0 || fr.y + fr.h <= 0 || fr.x >= W || fr.y >= H)) {
            SDL_SetRenderDrawColor(ren, 255, 230, 120, 255);
            SDL_RenderFillRect(ren, &fr);
        }
    }
}

// Ore/overlay render pass [RE: economy.md §5]: drawn immediately after the
// terrain tiles and below all objects (units/buildings). For every visible
// map cell that has_ore, pick the tiberium set's art by the cell's variant
// (OreField::variant_at) and select the density frame within the SHP's IMAGE
// half -- min(density, count/2 - 1); the second half is shadow frames, empty
// for ore (verified frame 12 of tib01.tem decodes 0x0). Anchor it exactly
// like a terrain tile (cell_to_screen top-left + the SHP frame's own bbox
// offset) and palettize with the THEATER palette temperat.pal (OreArt::pal;
// see OreArt's PALETTE root-cause note -- isotem.pal renders confetti).
// Cells whose variant art is absent simply don't draw.
void draw_ore(SDL_Renderer* ren, ra2engine::TextureCache& tc, const OreArt& oa,
              const ra2engine::OreField& ore, const ra2assets::MapFile& map,
              const ra2assets::Palette& pal, const ra2engine::Camera& cam, int W, int H,
              const ra2engine::World* vis = nullptr) {
    if (!oa.any) return;
    const ra2assets::Palette& ore_pal = oa.has_pal ? oa.pal : pal;
    // W2-GA-P1: only the cells that can reach the view (cached painter rows).
    ra2engine::for_each_visible_cell(map, cam, W, H, 48, [&](const ra2assets::MapCell& c, int, int) {
        if (!ore.has_ore(c.x, c.y)) return;
        if (vis && !vis->explored_at(g_local_house, c.x, c.y)) return;   // G-84: never under shroud
        const int kind = (ore.kind_at(c.x, c.y) == ra2engine::OreKind::Gems) ? 1 : 0;
        int slot = ore.variant_at(c.x, c.y);
        if (slot < 0 || slot >= 20) slot = 0;
        // W5-PRES [RE: CellClass draw overlay 0x47F5B0]: the art variant is the
        // cell hash (X*Y) % 12 on flat ground; ramps 1..4 use the slope images
        // 12 + (ramp-1)*2 + (X*Y) % 2 (gems have none). Live game only.
        if (g_map_dressing) {
            const int ramp = g_pres_assets ? pres_cell_ramp(*g_pres_assets, c.x, c.y) : 0;
            const int h = (c.x * c.y) & 0x7fffffff;
            slot = (ramp >= 1 && ramp <= 4 && kind == 0) ? 12 + (ramp - 1) * 2 + h % 2 : h % 12;
        }
        // Variant picks the SHP; density picks the frame within it. Fall back
        // to the set's base art (slot 0) when this exact variant is absent.
        if (!oa.present[kind][slot]) {
            slot = 0;
            if (!oa.present[kind][slot]) return;
        }
        const ra2assets::ShpFile& shp = oa.shp[kind][slot];
        if (shp.count() <= 0) return;
        // Image frames = first half (second half shadows), like every TS SHP.
        const int image_frames = std::max(1, shp.count() / 2);
        int frame = ore.density_at(c.x, c.y);
        if (frame >= image_frames) frame = image_frames - 1;
        if (frame < 0) frame = 0;
        // W4-FIX-POS [RE: FUN_005fd4b0 Tiberium=yes]: centred on the cell
        // centre - 12 px (was canvas top-left -> drawn in the cell below).
        const ra2engine::ScreenPt p = ra2engine::overlay_draw_center(
            c.x, c.y, static_cast<int>(c.level), ra2engine::overlay_y_offset(true, false, -1, false, 0));
        const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
        SDL_Rect dst{p.x + cam.x - shp.width() / 2 + f.x, p.y + cam.y - shp.height() / 2 + f.y, f.w, f.h};
        if (dst.x + dst.w <= 0 || dst.y + dst.h <= 0 || dst.x >= W || dst.y >= H) return;
        char key[48];
        // Theater-tagged: each theater draws its ore with its own palette.
        std::snprintf(key, sizeof key, "ore:%s:%d:%d:%d", art_chain().ext, kind, slot, frame);
        SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
        if (!tex) {
            std::vector<uint8_t> idx = shp.decode_indexed(frame);
            tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, ore_pal));
        }
        SDL_RenderCopy(ren, tex, nullptr, &dst);
    });
}

// --- P5 Veterancy + Crates art [RE: veterancy.md V13/C3] ---------------------
// PIPS.SHP (the YR conqmd.mix copy: frame 14 = veteran chevron, 15 = elite;
// the RA2 conquer.mix copy is a different 19-frame layout and is only the
// fallback), palette.pal (the PALETTE_PAL convert the binary draws pips with,
// by YRpp-offset analogy -- PROBABLE), and the CRATE overlay (crate.tem in the
// theater mix, drawn with the ore/overlay palette). Loaded ONLY by GameScene
// and --demo-veterancy, published through g_p5_art; every other mode leaves
// it null and render_world draws exactly what it drew before. Render-only
// (no hash reads pixels).
struct P5Art {
    ra2assets::ShpFile pips;
    bool has_pips = false;
    ra2assets::Palette pips_pal;
    bool has_pips_pal = false;
    ra2assets::ShpFile crate;
    bool has_crate = false;
};
const P5Art* g_p5_art = nullptr;

P5Art load_p5_art(const std::string& dir, const ra2assets::MixFile& ra2) {
    load_progress("VETERANCY ART");   // W2-AR-02 loading-screen checkpoint
    P5Art art;
    try {
        MixFile top = MixFile::open_path(dir + "ra2md.mix");
        MixFile conqmd = top.open_nested("conqmd.mix");
        if (const MixEntry* e = conqmd.find(std::string("pips.shp"))) {
            art.pips = ShpFile::load(conqmd.read(*e));
            art.has_pips = true;
        }
    } catch (const std::exception&) {}
    if (!art.has_pips) {
        try {
            MixFile conquer = ra2.open_nested("conquer.mix");
            if (const MixEntry* e = conquer.find(std::string("pips.shp"))) {
                art.pips = ShpFile::load(conquer.read(*e));
                art.has_pips = true;
            }
        } catch (const std::exception&) {}
    }
    try {
        MixFile cache = ra2.open_nested("cache.mix");
        if (const MixEntry* pe = cache.find(std::string("palette.pal"))) {
            auto raw = cache.read(*pe);
            art.pips_pal = Palette::load(raw.data(), raw.size());
            art.has_pips_pal = true;
        }
    } catch (const std::exception&) {}
    try {
        for (const auto& c : ra2assets::theater_candidates("crate", art_chain().letter,
                                                           art_chain().iso_mix, art_chain().art_mix,
                                                           std::string(".") + art_chain().ext)) {
            MixFile m = ra2.open_nested(c.mix);
            if (const MixEntry* e = m.find(c.file)) {
                art.crate = ShpFile::load(m.read(*e));
                art.has_crate = true;
                break;
            }
        }
    } catch (const std::exception&) {}
    std::cerr << "[p5-art] pips=" << (art.has_pips ? art.pips.count() : 0)
              << " palette.pal=" << (art.has_pips_pal ? "yes" : "no")
              << " crate=" << (art.has_crate ? "yes" : "no") << "\n";
    return art;
}

// Draws one SHP frame with its 16x16-style canvas CENTERED on (sx, sy).
void draw_shp_centered(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ShpFile& shp,
                       int frame, const ra2assets::Palette& pal, const char* tag, int sx, int sy,
                       int W, int H) {
    if (frame < 0 || frame >= shp.count()) return;
    const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
    if (f.w <= 0 || f.h <= 0) return;
    SDL_Rect dst{sx - shp.width() / 2 + f.x, sy - shp.height() / 2 + f.y, f.w, f.h};
    if (dst.x + dst.w <= 0 || dst.y + dst.h <= 0 || dst.x >= W || dst.y >= H) return;
    char key[48];
    std::snprintf(key, sizeof key, "p5:%s:%d", tag, frame);
    SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
    if (!tex) {
        std::vector<uint8_t> idx = shp.decode_indexed(frame);
        tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, pal));
    }
    SDL_RenderCopy(ren, tex, nullptr, &dst);
}

// [V13] Chevrons: PIPS frame 14 (veteran) / 15 (elite) at the object point
// +(5,2) infantry / +(10,6) others. In a veterancy World the rank comes from
// Unit::vet; otherwise the legacy veteran_rank (spy-factory units) shows one
// chevron. Disguised units show none (the original skips disguised-as).
void draw_p5_chevrons(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2engine::World& world,
                      const ra2assets::Palette& fallback_pal, const ra2engine::Camera& cam,
                      int W, int H) {
    if (!g_p5_art || !g_p5_art->has_pips) return;
    const ra2assets::Palette& pal = g_p5_art->has_pips_pal ? g_p5_art->pips_pal : fallback_pal;
    for (const ra2engine::Unit& u : world.units()) {
        if (!u.alive || u.die_time >= 0.0 || u.cargo_of >= 0) continue;
        // W7-12-46 [RE: IsDisguisedAs(PlayerPtr) 0x745580 / 0x522520 is false
        // for the viewer's own objects]: only a disguise seen by someone else
        // hides the chevron.
        if (u.disguised && u.house != g_local_house && !world.are_allied(g_local_house, u.house)) continue;
        // W7-12-19 [RE: 0x6F46F0 @0x6F48C0 -- no chevron when VisualCharacter
        // is Hidden (5): cloaked / submerged enemies], nor under shroud / fog.
        if (world.unit_hidden_from(g_local_house, u)) continue;
        if (u.house != g_local_house && !world.object_visible_at(g_local_house, u.cell_x, u.cell_y)) continue;
        if (u.ia.vanish || pres_crushed(static_cast<int>(&u - world.units().data()))) continue;
        const int rank = world.veterancy_enabled() ? ra2engine::vet_rank(u.vet.veterancy)
                                                   : (u.veteran_rank > 0 ? 1 : 0);
        if (rank <= 0) continue;
        const int frame = rank >= 2 ? 15 : 14;
        const double ufx = u.fx + u.sub_x / 256.0, ufy = u.fy + u.sub_y / 256.0;   // W5-B sub-cell
        // W7-12-20 [RE: 0x709E10 offsets from the same draw point as the
        // health bar]: lifted by the flight altitude and a bridge deck.
        const int up = (u.is_aircraft && u.altitude > 0.0) ? ra2engine::altitude_to_screen_dy(u.altitude) : 0;
        const int lv = u.level + pres_unit_lift_levels(world, u);
        const int sx = static_cast<int>(std::lround((ufx - ufy) * 30.0)) + cam.x + 30;
        const int sy = static_cast<int>(std::lround((ufx + ufy) * 15.0 - lv * 15)) + cam.y + 15 - up;
        // W7-12-21: +(5,2) for InfantryClass only (the drone is a Unit).
        const bool inf = pres_rtti_infantry(u);
        const int ox = inf ? 5 : 10, oy = inf ? 2 : 6;
        draw_shp_centered(ren, tc, g_p5_art->pips, frame, pal, "pips", sx + ox, sy + oy, W, H);
    }
}

// [C3] Crates: the CRATE overlay on every active crate cell.
void draw_p5_crates(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2engine::World& world,
                    const ra2assets::MapFile& map, const ra2assets::Palette& pal,
                    const ra2engine::Camera& cam, int W, int H) {
    if (!g_p5_art || !g_p5_art->has_crate || !world.crates_enabled()) return;
    for (const ra2engine::World::Crate& c : world.crates()) {
        if (c.x < 0) continue;
        if (!world.explored_at(g_local_house, c.x, c.y)) continue;   // G-84: crates respect shroud
        const ra2assets::MapCell* mc = map.at(c.x, c.y);
        const int level = mc ? static_cast<int>(mc->level) : 0;
        // W4-FIX-POS [RE: FUN_005fd4b0 Crate=yes]: cell centre - 12 px, centred.
        const ra2engine::ScreenPt p =
            ra2engine::overlay_draw_center(c.x, c.y, level, ra2engine::overlay_y_offset(true, false, -1, false, 0));
        const ra2assets::ShpFile::Frame f = g_p5_art->crate.frame_info(0);
        SDL_Rect dst{p.x + cam.x - g_p5_art->crate.width() / 2 + f.x, p.y + cam.y - g_p5_art->crate.height() / 2 + f.y,
                     f.w, f.h};
        if (dst.x + dst.w <= 0 || dst.y + dst.h <= 0 || dst.x >= W || dst.y >= H) continue;
        SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek("p5:crate:0"));
        if (!tex) {
            std::vector<uint8_t> idx = g_p5_art->crate.decode_indexed(0);
            tex = static_cast<SDL_Texture*>(tc.get("p5:crate:0", idx.data(), f.w, f.h, pal));
        }
        SDL_RenderCopy(ren, tex, nullptr, &dst);
    }
}

// Finds the loaded VehicleAssets whose resolved image matches `image` (Rhino
// HTNK and the two miners HARV/CMIN all render through the voxel path); nullptr
// if none matches or the list is null. Lets render_world draw several distinct
// voxel types in one scene instead of the old single-`va` special case.
const VehicleAssets* va_for_image(const std::vector<const VehicleAssets*>* vlist,
                                  const std::string& image) {
    if (!vlist) return nullptr;
    for (const VehicleAssets* v : *vlist)
        if (v && v->ok && v->combat.image == image) return v;
    return nullptr;
}

// Draws one full frame of the world into the current render target (does NOT
// clear or present): terrain, the ordered path + selection diamond (alive,
// non-dying units only), the unit sprites (back-to-front; dying units
// included so their die anim plays, tombstoned units excluded -- see
// unit_draw_order), HP bars (alive, non-dying, selected-or-damaged units),
// then the live selection box on top. Shared by every mode so they stay
// visually consistent. House color (pal_for_house) is applied inside
// draw_unit itself via its house-keyed texture cache entry -- no extra work
// needed here. `va` (optional): when non-null AND va->ok, units whose image
// matches the vehicle's draw via voxel sprites (draw_vehicle_unit) instead of
// SHP, and their selection diamond / HP bar size to the hull sprite width.
// Passed nullptr by the SHP-only modes (including --demo-combat, whose
// byte-identity gate requires tanks NEVER spawn there).
// Projectile phase (P2) [RE: projectile.md §3/§6]: draws every projectile in
// flight as a small shell (ballistic) or bomb (vertical) plus a ground shadow,
// with the SAME projection as the FLH muzzle flash in draw_vehicle_unit:
// ((x-y)*30, (x+y)*15) px per cell on the ground plane, the cell's terrain level
// at 15 px, and height at 0.866*60/sqrt2 = 36.74 px per 256 leptons
// (voxel-render.md §6). The projectile Image= SHPs (120MM/ZBOMB) are a recorded
// cosmetic carry-forward.
bool pres_draw_projectile(SDL_Renderer* ren, ra2engine::TextureCache& tc,
                          const ra2engine::World& world, const ra2engine::Projectile& p, int gx,
                          int sy, int W, int H);   // G-83 (pres_fx.inc)
void draw_projectiles(SDL_Renderer* ren, const ra2engine::World& world,
                      const ra2assets::MapFile& map, const ra2engine::Camera& cam, int W, int H,
                      ra2engine::TextureCache* tc = nullptr) {
    for (const ra2engine::Projectile& p : world.projectiles()) {
        const double x = p.x / 256.0, y = p.y / 256.0;
        const ra2assets::MapCell* mc =
            map.at(ra2engine::lepton_to_cell(p.x), ra2engine::lepton_to_cell(p.y));
        // G-84: a shell over a cell house 0 cannot currently see is not drawn.
        if (!world.object_visible_at(g_local_house, ra2engine::lepton_to_cell(p.x), ra2engine::lepton_to_cell(p.y)))
            continue;
        const int level = mc ? mc->level : 0;
        const int gx = static_cast<int>(std::lround((x - y) * 30.0)) + cam.x + 30;
        const int gy = static_cast<int>(std::lround((x + y) * 15.0 - level * 15)) + cam.y + 15;
        const int sy = gy - static_cast<int>(std::lround((p.z / 256.0) * 36.74));
        if (gx < -8 || gx > W + 8 || sy > H + 8 || gy < -8) continue;
        // W4: the FIRING weapon's art (slot / base defence / voxel bullet).
        if (tc && g_fx3 && g_fx3->draw_projectile(ren, *tc, world, p, gx, sy, gy, W, H)) continue;
        // G-83: the projectile's Image= art when the live game's FX layer has it.
        if (tc && pres_draw_projectile(ren, *tc, world, p, gx, sy, W, H)) continue;
        SDL_Rect shadow{gx - 2, gy - 1, 4, 2};
        SDL_SetRenderDrawColor(ren, 20, 20, 20, 255);
        SDL_RenderFillRect(ren, &shadow);
        const bool bomb = (p.kind == ra2engine::ProjKind::Vertical);
        const int r = bomb ? 3 : 2;
        SDL_Rect outline{gx - r - 1, sy - r - 1, 2 * r + 2, 2 * r + 2};  // dark rim: readable on grass
        SDL_SetRenderDrawColor(ren, 30, 20, 10, 255);
        SDL_RenderFillRect(ren, &outline);
        SDL_Rect shell{gx - r, sy - r, 2 * r, 2 * r};
        if (bomb)
            SDL_SetRenderDrawColor(ren, 110, 110, 125, 255);
        else
            SDL_SetRenderDrawColor(ren, 255, 240, 170, 255);
        SDL_RenderFillRect(ren, &shell);
    }
}


bool pres_target_lines();   // G-88: RA2.INI UnitActionLines (defined after g_user_settings)

// W2-GA-11 [RE: RE-Q14, UnitTypeClass art read FUN_00746450 + ctor defaults
// FUN_00745f00; UnitClass SHP draw FUN_0073b520]: SHP (artmd Voxel=no)
// vehicles -- Terror Drone, Dolphin, Squid -- pick their frame from the
// facing group and Walk/Standing/Firing ranges instead of an infantry
// sequence. Filled by GameScene for roster images with Voxel=no; render-only
// (the sim keeps the unit's existing semantics).
struct ShpVehicleArt {
    int facings = 8, walk = 12, fire = 0, stand = 0;
    int start_walk = 0, start_stand = 0, start_fire = 0;
};
std::map<std::string, ShpVehicleArt> g_shp_vehicles;
ShpVehicleArt shp_vehicle_art(const Ini& art, const std::string& image) {
    auto gi = [&](const char* k, int d) {
        const std::string v = pres_clean(art.get(image, k));
        return v.empty() ? d : std::atoi(v.c_str());
    };
    ShpVehicleArt s;
    s.walk = gi("WalkFrames", 12);
    s.fire = gi("FiringFrames", 0);
    s.stand = gi("StandingFrames", s.fire > 0 ? 1 : 0);
    const bool turret = pres_lower(pres_clean(art.get(image, "Turret"))).rfind("y", 0) == 0;
    s.facings = gi("Facings", (s.fire == 0 && !turret) ? 1 : 8);
    s.start_walk = std::max(0, gi("StartWalkFrame", 0));
    const int ss = gi("StartStandFrame", -1);
    s.start_stand = ss >= 0 ? ss : (s.stand ? s.walk * s.facings : s.start_walk);
    const int sf = gi("StartFiringFrame", -1);
    s.start_fire = sf >= 0 ? sf : (s.fire ? (s.walk + s.stand) * s.facings : s.start_stand);
    return s;
}
int shp_vehicle_frame(const ShpVehicleArt& s, const ra2engine::Unit& u, int count) {
    // facing group: (((raw>>12)+1)>>1)+1)&7 for Facings=8, else group 0.
    // An infantry-path unit (the sim keeps DRON there) carries the SHP facing
    // block index directly (u.facing, the infantry-anim.md §4 order).
    int fg = 0;
    if (s.facings == 8) {
        if (!u.is_vehicle) {
            fg = ((u.facing % 8) + 8) % 8;
        } else {
            const int raw = static_cast<int>(u.body_facing) & 0xFFFF;
            fg = ((((raw >> 12) + 1) >> 1) + 1) & 7;
        }
    }
    const long t = g_pres_tick;
    // W3-B [RE: UnitClass SHP draw FUN_0073b520 + FootClass::AI walk stage
    // FUN_004da440]: walk frames step with the unit's WalkedFramesSoFar --
    // +1 every WalkRate frames while moving, every IdleRate frames standing
    // (IdleRate 0: the standing frames).
    const int stage = pres_walk_stage(g_draw_unit_idx);
    int f;
    if (u.fire_flash > 0 && s.fire > 0)
        f = s.fire * fg + s.start_fire + static_cast<int>((t / 2) % s.fire);
    else if (u.moving() || pres_idle_rate(u.image) > 0)
        f = stage % std::max(1, s.walk) + s.walk * fg + s.start_walk;
    else if (s.stand)
        f = s.stand * fg + s.start_stand;
    else
        f = s.walk * fg + s.start_walk;
    return std::clamp(f, 0, std::max(0, count / 2 - 1));   // second half = shadows
}

// NET L1: the selection is UI state now (engine/selection.hpp). The game draws
// its Input's selection; the non-interactive demos draw this one.
ra2engine::Selection g_demo_selection;

void render_world(SDL_Renderer* ren, ra2engine::TextureCache& tc, Assets& a,
                  UnitAssets& ua, ra2engine::World& world, const ra2engine::Camera& cam,
                  int W, int H, const ra2engine::Input* input = nullptr,
                  const std::vector<const VehicleAssets*>* vlist = nullptr,
                  const BuildingAssets* ba = nullptr, const OreArt* ore_art = nullptr) {
    const ra2engine::Selection& rsel = input ? input->selection() : g_demo_selection;
    ra2engine::set_color_world(&world);   // G-16: house colours for every sprite draw
    g_pres_assets = &a;                   // W5-PRES: ramp lookups (ore slopes)
    tc.next_frame();                      // W2-GA-P5: LRU clock (evicts only over budget)
    // W2-GA-02: never-explored cells are not drawn at all (their cliff/slope
    // extras no longer leak through the shroud); the SHROUD.SHP post-pass
    // (draw_shroud_pass below) softens the edges over every object.
    g_terrain_drawn = ra2engine::draw_terrain(ren, tc, a.map, a.theater, a.pal, cam, W, H, &world, g_local_house);   // W2-GA-02 (net: the local house's shroud)
    // Ore/overlay layer: above terrain tiles, below every object [economy.md §5].
    if (ore_art) draw_ore(ren, tc, *ore_art, world.ore(), a.map, a.pal, cam, W, H, &world);
    // G-87: map smudges + non-ore overlays (walls/fences/bridges), live game only.
    if (g_map_dressing) g_map_dressing->draw_ground(ren, tc, world, g_map_pals, cam, W, H);
    if (g_fx && g_map_dressing) g_fx->draw_radiation(ren, world, a.map, cam, W, H);   // W2-GA-15
    if (g_fx3) g_fx3->draw_ground(ren, tc, cam, W, H);   // W3-FX wakes / ore twinkles (ground layer)
    // P5 [RE: veterancy.md C3]: crate overlays (no-op unless g_p5_art + crates).
    draw_p5_crates(ren, tc, world, a.map, (ore_art && ore_art->has_pal) ? ore_art->pal : a.pal,
                   cam, W, H);
    if (g_fx) g_fx->draw(ren, tc, cam, W, H, 0);   // W3-B Flat / ground-layer anims under objects
    const std::vector<ra2engine::Unit>& us = world.units();
    auto usel = [&](const ra2engine::Unit& u) { return rsel.has(static_cast<int>(&u - us.data())); };
    // Hull sprite width for a vehicle unit (0 for infantry) -- sizes the
    // selection diamond + HP bar to the wider voxel sprite.
    auto veh_width = [&](const ra2engine::Unit& u) -> int {
        const VehicleAssets* va = va_for_image(vlist, u.image);
        if (!va) return 0;
        const int bi = ra2engine::facing_to_index(u.body_facing, ra2engine::kVehicleFacings);
        return vxl_set(*va, 0, u.house).sprites[bi].w;
    };
    // Paths + selection markers first (under the sprites); skip dead/dying
    // units entirely (no path, no selection marker for a corpse-in-progress).
    for (const ra2engine::Unit& u : us) {
        if (!u.alive || u.die_time >= 0.0 || u.cargo_of >= 0) continue;  // CB-1:
        // G-88: in the real game only the player's SELECTED units show their
        // route, and only with RA2.INI "Target Lines" on (UnitActionLines);
        // the non-interactive render paths keep the old every-unit debug lines.
        if (!input || (usel(u) && u.house == g_local_house && pres_target_lines()))
            ra2engine::draw_path(ren, u, cam, W, H);   // carried units draw nothing
        // W2-UI-11: in the real game the selection marker IS the pip board
        // (drawn with the bars below); other render paths keep the diamond.
        if (usel(u) && !(input && g_pips)) ra2engine::draw_selection(ren, u, cam, W, H, veh_width(u));
    }
    // Sprites back-to-front so nearer units overlap farther ones. Vehicles
    // (an image with a VehicleAssets entry) draw via voxel sprites; otherwise
    // pick the SHP by the unit's own image ("GI"/"CONS"). An unrecognized
    // image is logged and skipped (not thrown) so one bad unit can't take
    // down the whole frame.
    auto draw_one_unit = [&](int idx) {
        // W5-PRES R-100: a unit on a high-bridge deck draws BridgeHeight up.
        std::optional<ra2engine::Unit> lifted;
        const ra2engine::Unit* up = &us[idx];
        if (const int lv = pres_unit_lift_levels(world, *up)) {
            lifted.emplace(*up);
            lifted->level += lv;
            up = &*lifted;
        }
        const ra2engine::Unit& u = *up;
        // W5-PRES R-120: Iron Curtain / elite flash / chrono warp draw tint.
        ra2engine::ObjTint tint;
        struct TintScope {
            explicit TintScope(const ra2engine::ObjTint* t) { ra2engine::set_obj_tint(t); }
            ~TintScope() { ra2engine::set_obj_tint(nullptr); }
        } tint_scope([&]() -> const ra2engine::ObjTint* {
            bool has = pres_unit_tint(world, idx, tint);
            // W7-06-13 [RE-FALLBACK: the cloak shimmer (TechnoClass draw
            // VisualType) not traced]: a submerged unit the player sees (own,
            // or sonar-detected) is drawn half translucent, not as surfaced.
            if (u.an.submerged && g_map_dressing) {
                tint.alpha = static_cast<unsigned char>(std::min<int>(tint.alpha, 128));
                has = true;
            }
            return has ? &tint : nullptr;
        }());
        // Shroud/Fog [RE: shroud.md §5, W2-GA-03]: hide mobile objects in cells
        // house 0 cannot see (object_visible_at: explored, or visible with FogOfWar). Inert with shroud
        // off (visible_at returns true on empty grids) -> every existing render
        // is pixel-identical. Own units (u.house == 0) are always drawn.
        if (u.house != g_local_house && !world.object_visible_at(g_local_house, u.cell_x, u.cell_y)) return;
        // W2-AN-13: a submerged enemy sub without our sonar contact is unseen.
        if (world.unit_hidden_from(0, u)) return;
        if (u.ia.vanish) return;   // W3-B: a death anim replaced the body
        if (u.die_time >= 0.0 && pres_crushed(idx)) return;   // W7-04-25: crushed -> removed at once
        // W5-PRES R-047 [RE: abilities-w5.md §9]: an enemy viewer sees a still
        // Mirage as its DefaultMirageDisguises tree; owner and allies see the tank.
        if (u.house != g_local_house && world.is_enemy(g_local_house, u.house) && g_map_dressing) {
            const std::string tree = pres_mirage_tree(u);
            if (!tree.empty() && g_map_dressing->draw_tree_at(ren, tc, world, tree, u.cell_x, u.cell_y, u.level,
                                                             g_map_pals, cam, W, H))
                return;
        }
        // Engineer/Spy Capture [RE: capture.md §C1]: a disguised unit selects the
        // SHP for its disguise type (draw_unit then blits it in the disguised
        // house's palette). When NOT disguised draw_image == u.image -> this is
        // byte-identical to the pre-Task-7 lookup.
        const std::string& draw_image = u.disguised ? u.disguised_as_type : u.image;
        const VehicleAssets* va_found = va_for_image(vlist, draw_image);
        if (!va_found && g_map_dressing && !u.disguised && !u.tg.t.rules_id.empty()) {
            // W7-09-16 / W7-10-10: a voxel type no roster / map preload
            // resolved (trigger / team / cheat spawns, captured-factory
            // output) loads on first sight instead of staying invisible.
            static std::map<std::string, std::unique_ptr<VehicleAssets>> on_demand;
            auto od = on_demand.find(draw_image);
            if (od == on_demand.end()) {
                std::unique_ptr<VehicleAssets> nv;
                bool vehicle = false;
                if (g_walk_rules)
                    for (const char* sec : {"VehicleTypes", "AircraftTypes"})
                        for (const auto& kv : g_walk_rules->section(sec))
                            if (pres_upper(pres_clean(kv.second)) == u.tg.t.rules_id) vehicle = true;
                if (vehicle && ua.shps.find(draw_image) == ua.shps.end()) {
                    try {
                        static const MixFile ra2m = MixFile::open_path(env_install_dir() + "ra2.mix");
                        nv = std::make_unique<VehicleAssets>(load_vehicle_assets(env_install_dir(), ra2m, ua.pal,
                                                                                 u.tg.t.rules_id));
                        if (!nv->ok || nv->combat.image != draw_image) nv.reset();
                    } catch (const std::exception&) { nv.reset(); }
                    std::cerr << "[render] on-demand voxel " << u.tg.t.rules_id << " image=" << draw_image
                              << (nv ? " ok" : " unavailable") << '\n';
                }
                od = on_demand.emplace(draw_image, std::move(nv)).first;
            }
            va_found = od->second.get();
        }
        if (const VehicleAssets* va = va_found) {
            g_draw_unit_idx = idx;   // W3-B: walk stage (HVA frame)
            // W3-B [RE: FUN_0073c1cc, Harvester=yes + unloading -> UnloadingClass]:
            // a harvester dumping at the refinery draws its UnloadingClass.
            if (u.is_harvester && u.harv == ra2engine::HarvState::Unloading) {
                auto ul = g_unloading_class.find(draw_image);
                if (ul != g_unloading_class.end() && ul->second) va = ul->second;
            }
            draw_vehicle_unit(ren, tc, u, *va, cam, W, H);
            return;
        }
        auto it = ua.shps.find(draw_image);
        if (it == ua.shps.end() && g_map_dressing) {
            // Live game only: a unit type no roster registered (a cheat /
            // trigger / captured-factory spawn) loads its SHP on first sight
            // (conquer.mix, then conqmd.mix) instead of staying invisible.
            static std::set<std::string> tried;
            if (tried.insert(draw_image).second) {
                try {
                    static const MixFile conquer =
                        MixFile::open_path(env_install_dir() + "ra2.mix").open_nested("conquer.mix");
                    it = ua.shps.emplace(draw_image, load_unit_shp(conquer, draw_image)).first;
                } catch (const std::exception&) {}
            }
        }
        if (it == ua.shps.end()) {
            std::cerr << "[render] no SHP loaded for image=" << draw_image << " (unit " << idx
                      << "); skipping\n";
            return;
        }
        auto sv = g_shp_vehicles.find(draw_image);
        if (sv != g_shp_vehicles.end() && u.die_time < 0.0) {   // W2-GA-11
            ra2engine::Unit tmp = u;
            g_draw_unit_idx = idx;   // W3-B walk stage (WalkRate / IdleRate)
            tmp.frame = shp_vehicle_frame(sv->second, u, it->second.count());
            ra2engine::draw_unit(ren, tc, tmp, it->second, ua.pal, cam, W, H);
            return;
        }
        ra2engine::draw_unit(ren, tc, u, it->second, ua.pal, cam, W, H);
    };
    // Merge alive buildings (depth key = center x+y with (f-1)/2, [RE-GATE
    // APPLIED: building-render.md §3]) into the unit draw order (fx+fy);
    // buildings precede units on ties (std::merge takes the first range when
    // keys tie). With no BuildingAssets (or no buildings) this is exactly the
    // old unit-only pass -- the byte-identity-gated demos spawn no buildings.
    const std::vector<int> uorder = ra2engine::unit_draw_order(us);
    struct DrawItem { double key; int kind; int idx; };  // kind 0=building, 1=unit
    std::vector<DrawItem> merged;
    if (ba) {
        const std::vector<ra2engine::Building>& bs = world.buildings();
        auto bkey = [&](int i) {
            const ra2engine::Building& b = bs[i];
            return (b.cx + (b.fw - 1) / 2.0) + (b.cy + (b.fh - 1) / 2.0);
        };
        std::vector<DrawItem> A, B;
        for (int i = 0; i < static_cast<int>(bs.size()); ++i)
            if ((bs[i].alive || pres_building_leaves_rubble(bs[i], *ba)) && pres_building_seen(world, bs[i]))
                A.push_back({bkey(i), 0, i});
        std::sort(A.begin(), A.end(), [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
        // G-87: map [Terrain] objects / civilian buildings sort with the buildings.
        // W2-GA-P1: they are static, so their order is built once per dressing
        // set and merged (buildings first on ties, as the stable sort gave).
        if (g_map_dressing) {
            static const PresMap* s_for = nullptr;
            static std::size_t s_n = 0;
            static std::vector<DrawItem> s_objs;
            const auto& objs = g_map_dressing->objects();
            static bool s_decks = false;   // W5-PRES: rebuilt when deck layering toggles
            if (s_for != g_map_dressing || s_n != objs.size() || s_decks != g_map_dressing->layer_decks()) {
                s_for = g_map_dressing;
                s_n = objs.size();
                s_decks = g_map_dressing->layer_decks();
                s_objs.clear();
                for (int i = 0; i < static_cast<int>(objs.size()); ++i)
                    s_objs.push_back({(objs[i].x + (objs[i].fw - 1) / 2.0) + (objs[i].y + (objs[i].fh - 1) / 2.0), 2, i});
                // W5-PRES R-100: high-bridge decks sort with the objects (kind 3).
                for (int di : g_map_dressing->decks()) {
                    const auto& o = g_map_dressing->overlays()[static_cast<std::size_t>(di)];
                    if (g_map_dressing->layer_decks()) s_objs.push_back({o.x + o.y + kPresDeckBias, 3, di});
                }
                std::stable_sort(s_objs.begin(), s_objs.end(),
                                 [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
            }
            std::vector<DrawItem> AB(A.size() + s_objs.size());
            std::merge(A.begin(), A.end(), s_objs.begin(), s_objs.end(), AB.begin(),
                       [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
            A.swap(AB);
        }
        // W5-PRES R-100/R-101: on-deck units sort after their deck; airborne
        // units leave the ground sort for the air layer (drawn below).
        for (int i : uorder)
            if (!(g_map_dressing && pres_airborne(us[i]))) B.push_back({pres_unit_key(world, us[i]), 1, i});
        std::stable_sort(B.begin(), B.end(), [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
        merged.resize(A.size() + B.size());
        std::merge(A.begin(), A.end(), B.begin(), B.end(), merged.begin(),
                   [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
    } else {
        for (int i : uorder) merged.push_back({0.0, 1, i});
    }
    for (const DrawItem& d : merged) {
        if (d.kind == 3) {
            g_map_dressing->draw_deck(ren, tc, world, d.idx, g_map_pals, cam, W, H);
        } else if (d.kind == 2) {
            g_map_dressing->draw(ren, tc, world, g_map_dressing->objects()[d.idx], g_map_pals, cam, W, H);
        } else if (d.kind == 0) {
            const ra2engine::Building& b = world.buildings()[d.idx];
            const ra2assets::MapCell* mc = a.map.at(b.cx, b.cy);
            ra2engine::ObjTint btint;   // W5-PRES R-120 Iron Curtain envelope
            ra2engine::set_obj_tint(pres_building_tint(world, b, btint) ? &btint : nullptr);
            draw_building(ren, tc, b, *ba, mc ? mc->level : 0, ba->condition_yellow, cam, W, H,
                          &world.buildings());
            if (g_turrets && b.type >= 0 && b.type < static_cast<int>(ba->roster.size()))   // W2-GA-13
                g_turrets->draw(ren, tc, world, b, ba->roster[static_cast<std::size_t>(b.type)].id,
                                mc ? mc->level : 0, cam, W, H);
            ra2engine::set_obj_tint(nullptr);
        } else {
            draw_one_unit(d.idx);
        }
    }
    // W5-PRES R-101: the air layer -- airborne aircraft / jumpjets over every
    // ground object (live game; the gates keep the single sort above).
    if (ba && g_map_dressing) {
        std::vector<DrawItem> air;
        for (int i : uorder)
            if (pres_airborne(us[i])) air.push_back({us[i].fx + us[i].fy, 1, i});
        std::stable_sort(air.begin(), air.end(), [](const DrawItem& x, const DrawItem& y) { return x.key < y.key; });
        for (const DrawItem& d : air) draw_one_unit(d.idx);
    }
    // W7-12-11: sinking hulls, lowered 5 leptons per frame and clipped at
    // their waterline [RE-FALLBACK: the waterline = the ground point + 10 px].
    for (const PresSinker& sk : g_pres_sinkers) {
        if (sk.unit < 0 || sk.unit >= static_cast<int>(us.size())) continue;
        const VehicleAssets* va = va_for_image(vlist, sk.image);
        if (!va) continue;
        if (sk.house != g_local_house &&
            !world.object_visible_at(g_local_house, static_cast<int>(std::lround(sk.fx)), static_cast<int>(std::lround(sk.fy))))
            continue;
        ra2engine::Unit tmp = us[static_cast<std::size_t>(sk.unit)];
        tmp.fx = sk.fx;
        tmp.fy = sk.fy;
        tmp.sub_x = tmp.sub_y = 0;
        tmp.level = sk.level;
        tmp.body_facing = sk.body;
        tmp.turret_facing = sk.turret;
        tmp.house = sk.house;
        tmp.die_time = -1.0;
        tmp.alive = true;
        tmp.an.sinking = false;
        tmp.an.crashing = false;
        tmp.is_aircraft = false;
        const long age = g_pres_tick - sk.start;
        g_sink_drop_px = std::max(1, static_cast<int>(std::lround(age * 5 * 36.74 / 256.0)));
        const int wy = static_cast<int>(std::lround((sk.fx + sk.fy) * 15.0 - sk.level * 15)) + cam.y + 15 + 10;
        SDL_Rect clip{0, 0, W, std::max(0, std::min(H, wy))};
        SDL_RenderSetClipRect(ren, &clip);
        g_draw_unit_idx = -1;
        draw_vehicle_unit(ren, tc, tmp, *va, cam, W, H);
        SDL_RenderSetClipRect(ren, nullptr);
        g_sink_drop_px = 0;
    }
    // W4-SQ-06: paratroopers under their parachutes (off the map until they
    // land: cargo_of == kParachuteCargo), raised by their height.
    for (int i = 0; i < static_cast<int>(us.size()); ++i) {
        const ra2engine::Unit& u = us[i];
        if (u.cargo_of != ra2engine::kParachuteCargo || !u.alive || u.an.para_alt <= 0.0) continue;
        auto it = ua.shps.find(u.image);
        if (it == ua.shps.end()) continue;
        ra2engine::Unit tmp = u;
        const double lift = ra2engine::altitude_to_screen_dy(u.an.para_alt) / 30.0;
        tmp.fx -= lift;
        tmp.fy -= lift;
        ra2engine::draw_unit(ren, tc, tmp, it->second, ua.pal, cam, W, H);
        pres_draw_parachute(ren, tc, i, tmp, cam, W, H);   // W5-PRES R-122
    }
    pres_draw_landed_chutes(world, ren, tc, cam, W, H);   // W5-PRES R-122 chute collapse
    // Projectile phase (P2): shells/bombs in flight, over the objects. EMPTY
    // unless enable_projectiles was called (the game + --demo-projectile), so
    // no existing demo screenshot changes.
    draw_projectiles(ren, world, a.map, cam, W, H, &tc);
    if (g_fx) g_fx->draw(ren, tc, cam, W, H);   // G-83 muzzle / impact / death anims
    if (g_fx3) g_fx3->draw(ren, tc, cam, W, H);   // W3-FX particles / debris / line trails
    // W2-GA-05: the map's ambient light over every world sprite (GameScene only).
    if (g_light) g_light->pass(ren, W, H, cam);   // W3-FIX-A: + light sources
    // W7-12-33: UseNormalLight anims and the beams at full brightness, after the light.
    if (g_fx && g_fx->split_light_) g_fx->draw(ren, tc, cam, W, H, 2);
    // G-84: fog + shroud over every object, under the HUD bars.
    draw_shroud_pass(ren, tc, a.map, world, cam, W, H);
    // HP bars after sprites, before the selection box: alive, non-dying,
    // NON-CARRIED units that are selected or currently damaged. A selected
    // transport also shows its loaded pip row -- filled with the SIZE-SUM
    // (cargo_total_size), the pip-only metric [RE-GATE APPLIED:
    // transport-cargo.md §1]; capacity itself is the COUNT [spec §6].
    // W7-12-22: the local house's Tech Hospital / Machine Shop counts.
    int heal_inf = 0, heal_unit = 0;
    if (ba)
        for (const ra2engine::Building& b : world.buildings())
            if (b.alive && b.state != ra2engine::Building::State::Dead && b.house == g_local_house && b.type >= 0 &&
                b.type < static_cast<int>(ba->roster.size())) {
                heal_inf += ba->roster[static_cast<std::size_t>(b.type)].w5.inf_self_heal;
                heal_unit += ba->roster[static_cast<std::size_t>(b.type)].w5.unit_self_heal;
            }
    static int heal_inf_frames = -1, heal_unit_frames = -1;
    if (heal_inf_frames < 0 && g_walk_rules) {
        auto n = [&](const char* k, int d) {
            const std::string v = pres_clean(g_walk_rules->get("General", k));
            return v.empty() ? d : std::atoi(v.c_str());
        };
        heal_inf_frames = n("SelfHealInfantryFrames", 50);
        heal_unit_frames = n("SelfHealUnitFrames", 75);
    }
    for (const ra2engine::Unit& u : us) {
        if (!u.alive || u.die_time >= 0.0 || u.cargo_of >= 0) continue;
        if (world.unit_hidden_from(g_local_house, u)) continue;   // W2-AN-13 submerged, no sonar contact
        // W7-12-19: nothing over a unit the local player cannot see (shroud /
        // fog), whatever the hover pick returned.
        if (u.house != g_local_house && !world.object_visible_at(g_local_house, u.cell_x, u.cell_y)) continue;
        if (input && g_pips) {   // W2-UI-11: PIPBRD + PIPS on the selected units only
            const int idx = static_cast<int>(&u - us.data());
            const bool hovered = g_hover_unit == idx;   // W6-05-07
            if (usel(u) || hovered) {
                const int up = (u.is_aircraft && u.altitude > 0.0) ? ra2engine::altitude_to_screen_dy(u.altitude) : 0;
                const double ufx = u.fx + u.sub_x / 256.0, ufy = u.fy + u.sub_y / 256.0;   // W5-B
                const int sx = static_cast<int>(std::lround((ufx - ufy) * 30.0)) + cam.x + 30;
                const int lv = u.level + pres_unit_lift_levels(world, u);   // W5-PRES R-100 deck
                const int sy = static_cast<int>(std::lround((ufx + ufy) * 15.0 - lv * 15)) + cam.y + 15 - up;
                draw_unit_pips(ren, tc, u, sx, sy, g_pip_yellow, g_pip_red, usel(u));
                // W7-12-04/05/16/17/18/22 [RE: DrawHealthBar 0x6F5A00 tail]: the
                // pip rows, group number and self-heal mark, own objects only.
                if (u.house == g_local_house) {
                    const ra2assets::Rgba hc = world.house_palette(ua.pal, u.house)[16];
                    draw_unit_overlays(ren, tc, world, us, u, sx, sy, input->group_of(idx),
                                       SDL_Color{hc.r, hc.g, hc.b, 255}, heal_inf, heal_unit, heal_inf_frames,
                                       heal_unit_frames);
                }
            }
        } else {
            if (usel(u) || u.hp < u.max_hp) ra2engine::draw_hp_bar(ren, u, cam, W, H, veh_width(u));
            if (usel(u) && u.passengers_max > 0)
                ra2engine::draw_cargo_pips(ren, u, ra2engine::cargo_total_size(us, u),
                                           u.passengers_max, cam, W, H);
        }
    }
    // W6-04-11 [rules [AudioVisual] IvanIconFlickerRate=8 "this many frames
    // and the icon goes back and forth within one of the 6 2-frame anims";
    // RE-FALLBACK: the icon is conquer.mix bomb.shp, the anim picked by the
    // fuse's elapsed sixth, drawn above the object]: a bombed object shows
    // the flickering bomb, so the player sees what carries one.
    draw_bomb_icons(ren, tc, world, us, cam);
    // P5 [RE: veterancy.md V13]: veterancy chevrons (no-op unless g_p5_art).
    draw_p5_chevrons(ren, tc, world, ua.pal, cam, W, H);
    // Live selection box on top (interactive only).
    if (input) {
        int x0, y0, x1, y1;
        if (input->selection_box(x0, y0, x1, y1))
            ra2engine::draw_selection_box(ren, x0, y0, x1, y1);
    }
}

// Read the framebuffer back and write it to a PNG. Throws on failure.
void capture_png(SDL_Renderer* ren, const std::string& out_path, int W, int H) {
    std::vector<uint8_t> px(static_cast<size_t>(W) * H * 4);
    if (SDL_RenderReadPixels(ren, nullptr, SDL_PIXELFORMAT_RGBA32, px.data(), W * 4) != 0)
        throw std::runtime_error(std::string("RenderReadPixels: ") + SDL_GetError());
    if (!stbi_write_png(out_path.c_str(), W, H, 4, px.data(), W * 4))
        throw std::runtime_error("stbi_write_png failed: " + out_path);
}

// Center the camera so the map's projected bounding-box center lands in the
// middle of the view (guarantees a populated region is shown).
ra2engine::Camera centered_camera(const MapFile& map, int view_w, int view_h) {
    ra2engine::Camera cam;
    int mnx, mny, mxx, mxy;
    if (ra2engine::terrain_screen_bounds(map, mnx, mny, mxx, mxy)) {
        cam.x = view_w / 2 - (mnx + mxx) / 2;
        cam.y = view_h / 2 - (mny + mxy) / 2;
    }
    return cam;
}

// Sidebar helpers (defined below, before run_interactive) used by both the
// screenshot HUD and the interactive loop.
std::vector<int> sidebar_buildable(const BuildingAssets& ba);
void draw_sidebar(SDL_Renderer* ren, ra2engine::TextureCache& tc, const BuildingAssets& ba,
                  const ra2engine::SidebarLayout& lay, const ra2engine::ProductionState& ps,
                  const ra2engine::World& world, int credits_shown, double t_now, int active_tab,
                  const UnitRoster* ur = nullptr, bool unit_factory_alive = true,
                  int armed_mode = 0);   // 0 none, 1 repair, 2 sell [repair-sell.md §C1]

int run_screenshot(const std::string& out_path) {
    const int W = 1280, H = 720;
    // ra2.mix opened ONCE and shared by both loaders; the buffer stays
    // resident for the run (accepted tradeoff, see the load_assets comment).
    const std::string dir = env_install_dir();
    ra2assets::MixFile ra2 = ra2assets::MixFile::open_path(dir + "ra2.mix");
    Assets a = load_assets(dir, ra2);
    UnitAssets ua = load_unit_assets(dir, ra2);
    VehicleAssets va = load_vehicle_assets(dir, ra2, ua.pal, "HTNK");
    ra2assets::MixFile language =
        ra2assets::MixFile::open_path(dir + "language.mix");
    Ini rules_ini = load_ini_from_ra2md(dir, "rulesmd.ini");
    Rules rules = Rules::load(rules_ini);
    Ini art_ini = load_ini_from_ra2md(dir, "artmd.ini");
    Art art = Art::load(art_ini);
    BuildingAssets ba = load_building_assets(ra2, language, rules, art);
    MinerAssets miners = load_miner_assets(dir, ra2, ua.pal, rules);
    OreArt ore_art = load_ore_art(ra2);
    // Producible-unit roster (logs [unit-roster] producible=N) so the HUD
    // screenshot can render a unit tab with the real unit cameos.
    UnitRoster ur = load_unit_roster(dir, ra2, ua, rules, art);
    const std::vector<const VehicleAssets*> vlist{&va, &miners.harv, &miners.cmin};
    ra2engine::World world = build_world(a, ua, 5);
    if (va.ok) spawn_tank_squads(world, a, va, 3);
    // Player ConYard + enemy full base flanking the existing squads (visual
    // gate: buildings on their foundations, blue player vs red enemy remap).
    if (ba.ok) {
        const ra2assets::MapCell* sc = ra2engine::pick_start_cell(a.map);
        if (sc) {
            spawn_base(world, ba, /*house=*/0, sc->x, sc->y + 4);
            spawn_base(world, ba, /*house=*/1, sc->x + 14, sc->y, /*with_refinery=*/true,
                       miners.harv.ok ? &miners.harv : nullptr, /*harv_chrono=*/false,
                       miners.harv_storage);
        }
    }

    if (SDL_Init(SDL_INIT_VIDEO) != 0) throw std::runtime_error(SDL_GetError());
    SDL_Window* win = SDL_CreateWindow("RA2 Engine (screenshot)", SDL_WINDOWPOS_CENTERED,
                                       SDL_WINDOWPOS_CENTERED, W, H, SDL_WINDOW_HIDDEN);
    if (!win) throw std::runtime_error(SDL_GetError());
    SDL_Renderer* ren = SDL_CreateRenderer(win, -1, SDL_RENDERER_ACCELERATED);
    if (!ren) throw std::runtime_error(SDL_GetError());

    // Scope the TextureCache so all SDL_Texture objects are destroyed BEFORE
    // the renderer / SDL_Quit below (destroying textures after SDL teardown is
    // an access violation).
    {
        ra2engine::TextureCache tc(ren);
        ra2engine::Camera cam = centered_camera(a.map, W, H);
        // With bases present, frame the player ConYard region so the visual
        // gate can verify foundation registration + house remap directly.
        if (ba.ok) {
            const ra2assets::MapCell* sc = ra2engine::pick_start_cell(a.map);
            if (sc) {
                const ra2engine::ScreenPt p =
                    ra2engine::cell_to_screen(sc->x + 4, sc->y + 4, 0, 60, 30, 15);
                cam.x = W / 2 - p.x;
                cam.y = H / 2 - p.y;
            }
        }

        SDL_SetRenderDrawColor(ren, 10, 20, 60, 255);
        SDL_RenderClear(ren);
        render_world(ren, tc, a, ua, world, cam, W, H, /*input=*/nullptr, &vlist,
                     ba.ok ? &ba : nullptr, ore_art.any ? &ore_art : nullptr);
        // Sidebar HUD so --screenshot shows the full UI. Render the Vehicle tab
        // (tab 3) so the wired unit-roster cameos (MTNK/FV) are visible, with an
        // idle unit queue's ProductionState.
        if (ba.ok && ba.sidebar_ok) {
            std::vector<int> buildable;   // tab 3 (Vehicle): unit-roster indices
            for (int i = 0; i < static_cast<int>(ur.defs.size()); ++i)
                if (ur.defs[i].is_vehicle) buildable.push_back(i);
            const int active_tab = buildable.empty() ? 0 : 3;
            if (buildable.empty()) buildable = sidebar_buildable(ba);
            const ra2engine::SidebarLayout lay =
                ra2engine::SidebarLayout::compute(W, H, buildable);
            ra2engine::ProductionState ps;
            ps.credits = rules.mp_money();
            draw_sidebar(ren, tc, ba, lay, ps, world, static_cast<int>(ps.credits), 0.0,
                         active_tab, &ur);
        }
        capture_png(ren, out_path, W, H);

        std::cerr << "[screenshot] wrote " << out_path << " (" << W << "x" << H << ")\n";
    }

    SDL_DestroyRenderer(ren);
    SDL_DestroyWindow(win);
    SDL_Quit();
    return 0;
}

// ---- Buildings & Construction Task 7e: sidebar + production glue ----------

// True if `house` owns an alive, Idle ConYard (the BuildingType factory).
bool conyard_alive(const ra2engine::World& world, const BuildingAssets& ba, int house) {
    for (const ra2engine::Building& b : world.buildings()) {
        if (!b.alive || b.state != ra2engine::Building::State::Idle || b.house != house) continue;
        if (b.type >= 0 && b.type < static_cast<int>(ba.roster.size()) && ba.roster[b.type].conyard)
            return true;
    }
    return false;
}

// Per-frame construction glue [RE: construction.md §8/§10], headless-safe (no
// SDL): recompute power, advance the queue, and cancel if the ConYard died.
void ps_tick(ra2engine::ProductionState& ps, const ra2engine::World& world,
             const BuildingAssets& ba, double dt, double low_mod) {
    const ra2engine::PowerTotals pt = ra2engine::power_totals(world.buildings(), ba.roster, 0);
    ra2engine::tick(ps, dt, ra2engine::build_speed_multiplier(pt, low_mod), ba.roster);
    if (ps.slot.type != -1 && !conyard_alive(world, ba, 0)) ra2engine::cancel(ps);
}

// The roster-index list of buildings that are factories for one queue category
// (a single id here — GAPILE for Infantry, GAWEAP for Vehicle, GACNST for the
// building queues). Empty if the id isn't in the roster.
std::vector<int> factory_types_for(const BuildingAssets& ba, const char* id) {
    std::vector<int> v;
    const int t = roster_index(ba, id);
    if (t >= 0) v.push_back(t);
    return v;
}

// Waypoint index -> cell table [RE-FALLBACK: ai-team.md deviations — the map
// [Waypoints] section is not parsed yet; scripted move-to-waypoint arguments
// resolve into this deterministic ring around the PLAYER base, so every
// recovered script marches at the player regardless of which waypoint id it
// names. Replace with real map waypoints in a later phase.]
std::vector<ra2engine::Cellxy> make_ai_waypoints(int px, int py) {
    static const int dx[8] = {0, 4, 4, 4, 0, -4, -4, -4};
    static const int dy[8] = {-4, -4, 0, 4, 4, 4, 0, -4};
    std::vector<ra2engine::Cellxy> w;
    w.reserve(32);
    for (int i = 0; i < 32; ++i)
        w.push_back(ra2engine::Cellxy{px + dx[i % 8], py + dy[i % 8]});
    return w;
}

// Real map waypoints for scripted AI move-to-waypoint arguments [RE: maps.md
// §4.3]. Index i is the map's waypoint i when the map defines it, else the
// synthetic ring entry from make_ai_waypoints(px,py) -- so a script naming a
// waypoint the map does not define still resolves to something sane. This
// RETIRES the [RE-FALLBACK] at make_ai_waypoints for every index the map
// actually defines. INTERACTIVE PATH ONLY: the two gate call sites of
// make_ai_team_config pass no map, so their tc.waypoints stay the pure ring
// (maps.md §7 rule 3).
// [RE-FALLBACK: maps.md §4.3 item 4 -- the PURPOSE of waypoints > 7 (10-55,
// 98, 99, 699=map center) was not determined; in-map script references were
// ruled out. We use them as positional nodes, which cannot contradict
// anything maps.md pinned.]
std::vector<ra2engine::Cellxy> make_ai_waypoints_from_map(const ra2assets::MapFile& map,
                                                          int px, int py) {
    std::vector<ra2engine::Cellxy> w = make_ai_waypoints(px, py);   // 32-entry ring baseline
    for (const ra2assets::MapWaypoint& mw : map.waypoints())
        if (mw.index >= 0 && mw.index < (int)w.size())
            w[(size_t)mw.index] = ra2engine::Cellxy{mw.x, mw.y};
    return w;
}

// Resolve the AI-2 team config from the real aimd.ini + the Soviet unit
// roster [RE: ai-team.md]. (player_x, player_y) anchors the waypoint table.
ra2engine::AiTeamConfig make_ai_team_config(const BuildingAssets& ba, const UnitRoster& ur_ai,
                                            const Rules& rules, const ra2assets::Ini& aimd_ini,
                                            ra2engine::AiDifficulty difficulty,
                                            int player_x, int player_y,
                                            bool enable_triggers = false,
                                            const ra2assets::MapFile* map = nullptr) {
    ra2engine::AiTeamConfig tc;
    tc.enabled = true;
    tc.unit_roster = ur_ai.defs;
    // UNITID -> roster index; unknown ids -1 -> parse_aimd art-guard-drops
    // the TaskForce and every team on it [RE: ai-team.md §1].
    auto unit_ix = [&](const std::string& id) -> int {
        for (int i = 0; i < (int)ur_ai.defs.size(); ++i)
            if (ur_ai.defs[i].id == id) return i;
        return -1;
    };
    tc.aimd = ra2engine::parse_aimd(aimd_ini, unit_ix);
    // AI-3 [RE: ai-trigger.md §1]: parse [AITriggerTypes] HOUSE-SCOPED through
    // the SAME resolver scoping as the teams above — UNIT condition objects
    // resolve in this house's (Soviet) unit roster, BUILDING objects in the
    // full shared building roster; an unresolvable object or a dropped/missing
    // team1 art-guard-drops the trigger whole, so only fieldable/resolvable
    // triggers survive. Parsed unconditionally (cheap, deterministic, cerr
    // only); the FIREWALL is triggers_enabled below.
    auto bld_ix = [&](const std::string& id) -> int {
        const int i = roster_index(ba, id);
        return (i >= 0 && i < (int)ba.art.size() && ba.art[i].ok) ? i : -1;
    };
    ra2engine::parse_ai_triggers(aimd_ini, tc.aimd, unit_ix, bld_ix);
    tc.triggers_enabled = enable_triggers;
    tc.trigger_side = 2;         // Soviet [RE-GATE APPLIED: ai-trigger.md §5 —
                                 // CONFIRMED SideIndex encoding 0=any,
                                 // 1=Allied, 2=Soviet, 3=Yuri]
    tc.trigger_tech_level = 10;  // skirmish tech ceiling [RE-FALLBACK: no
                                 // recovered per-house tech input; TechLevel
                                 // gates pass at 10]
    std::cerr << "[ai-trigger] aimd triggers parsed=" << tc.aimd.triggers.size()
              << " enabled=" << (enable_triggers ? "yes" : "no") << "\n";
    tc.inf_factory_types = factory_types_for(ba, "NAHAND");   // tab2 [RE: ai-base.md §2]
    tc.veh_factory_types = factory_types_for(ba, "NAWEAP");   // tab3
    tc.house_name = "Russians";  // [RE-GATE APPLIED: ai-team.md §1/§4] — the
                                 // OPTIONAL country restriction only; stock teams
                                 // are House=<none> so this does NOT filter them.
                                 // The real eligibility gate is that the Soviet
                                 // roster can field the TaskForce (parse_aimd
                                 // art-guard-drop). Interactive path is skirmish:
                                 // tc.rules.multiplay stays false (no dissolve).
    // nullptr => EXACTLY the historical synthetic ring (the gate call sites).
    tc.waypoints = (map && !map->waypoints().empty())
                       ? make_ai_waypoints_from_map(*map, player_x, player_y)
                       : make_ai_waypoints(player_x, player_y);
    // Team knobs from the real rulesmd, constants as fallbacks
    // [RE: ai-team.md §2/§4]. TeamDelays= is a CSV and section_double would
    // read only its head, so the per-difficulty value comes from the PINNED
    // constant array (the Task 3 install-gated test keeps constant and file
    // head consistent) [RE-FALLBACK: index binding]:
    // [G-63] TeamDelays= is indexed by house+0x184 = 2 - lobby (hardest first).
    tc.rules.team_delay_frames =
        ra2engine::kAiTeamDelayFrames[ra2engine::difficulty_class_index(difficulty)];
    tc.rules.autocreate_time_min = rules.section_double(
        "AI", "AutocreateTime", ra2engine::kAiAutocreateTimeMin);   // spawn cadence [§4]
    tc.rules.total_team_cap = (int)rules.section_double(
        "General", "TotalAITeamCap", (double)ra2engine::kAiTotalTeamCap);  // hard cap [§4]
    tc.rules.dissolve_frames = (int)rules.section_double(
        "General", "DissolveUnfilledTeamDelay",
        (double)ra2engine::kAiDissolveUnfilledDelayFrames);
    tc.rules.credit_reserve =
        rules.section_double("AI", "CreditReserve", ra2engine::kAiCreditReserve);
    tc.rules.infantry_reserve = (int)rules.section_double(
        "AI", "InfantryReserve", (double)ra2engine::kAiInfantryReserve);
    // BuildSlowdown is a difficulty BYTE (Easy off / Normal+Difficult on) — the
    // over-queue damp, NOT a time multiplier [RE-GATE APPLIED: ai-team.md §6].
    tc.rules.build_slowdown =   // [G-63] DifficultyClass 2 - lobby
        ra2engine::kDifficultyBuildSlowdown[ra2engine::difficulty_class_index(difficulty)];
    std::cerr << "[ai-team] aimd parsed: tf=" << tc.aimd.taskforces.size()
              << " sc=" << tc.aimd.scripts.size()
              << " teams=" << tc.aimd.teams.size() << "\n";
    return tc;
}

#include "ai_skirmish.inc"   // [G-60/G-62/G-64] real-play AI arming

// MultipleFactory build-SPEED multiplier for one category [RE-GATE APPLIED:
// production.md §1.2 — CONFIRMED MultipleFactory=0.8: each EXTRA same-class
// alive Idle owned factory multiplies build TIME by 0.8 (2->x0.8, 3->x0.64),
// so the tick SPEED multiplier is mf^-(n-1)]. n<=1 -> 1.0.
double factory_speedup(const ra2engine::World& world, const std::vector<int>& ftypes, double mf) {
    int n = 0;
    for (const ra2engine::Building& b : world.buildings()) {
        if (!b.alive || b.state != ra2engine::Building::State::Idle || b.house != 0) continue;
        for (int t : ftypes) if (b.type == t) { ++n; break; }
    }
    if (n <= 1 || mf <= 0.0) return 1.0;
    return ra2engine::om::ipow(1.0 / mf, n - 1);   // Net L0: deterministic (no libm pow)
}

// Per-frame production glue for the FOUR concurrent queues [RE-GATE APPLIED:
// production.md §1.1/§1.2/§1.5], headless-safe. Recompute power, advance every
// queue (each category's speed = power_mult x its MultipleFactory speedup;
// Structure+Defense share the ONE ConYard factory-count slot), then cancel a
// queue whose factory group was lost — buildings share the ConYard-alive gate
// (both building queues cancel together), Infantry/Vehicle each cancel on their
// own factory group. reconcile_refund settles the shared pool after a cancel.
void prod_tick(ra2engine::ProductionQueues& q, ra2engine::World& world, const BuildingAssets& ba,
               double dt, double low_mod, double mf, const std::vector<int>& inf_ft,
               const std::vector<int>& veh_ft,
               const std::vector<int>& nav_ft = std::vector<int>{},
               const std::vector<int>& air_ft = std::vector<int>{},
               const std::vector<int>* bld_ft_in = nullptr) {
    // Engineer/Spy Capture [RE: capture.md §B2]: a spied power plant forces this
    // house's power OUTPUT to 0 while the blackout timer runs (drain unaffected)
    // -> the existing low-power clamp + offline defenses follow. apply_blackout
    // is IDENTITY when !house_blacked_out, so every existing demo (never blacked
    // out) is byte-identical (production.cpp untouched).
    const ra2engine::PowerTotals pt =
        ra2engine::apply_blackout(ra2engine::power_totals(world.buildings(), ba.roster, 0),
                                  world.house_blacked_out(0));
    const double pmul = ra2engine::build_speed_multiplier(pt, low_mod);
    // Gap owner A: the real game passes its ConYard type list (GACNST+NACNST,
    // side-correct); gates keep the historical GACNST-only count.
    const std::vector<int> bld_ft = bld_ft_in ? *bld_ft_in : factory_types_for(ba, "GACNST");
    const double bsp = factory_speedup(world, bld_ft, mf);
    const double sp[ra2engine::kQueueCats] = {
        bsp, bsp, factory_speedup(world, inf_ft, mf), factory_speedup(world, veh_ft, mf),
        factory_speedup(world, nav_ft, mf), factory_speedup(world, air_ft, mf)};
    q.tick_all(dt, pmul, sp, ba.roster);
    // ConYard-died cancels BOTH building queues (Structure AND Defense share the
    // ConYard-alive factory group) [RE: production.md §1.1].
    if (!conyard_alive(world, ba, 0)) {
        // Both building queues must cancel through the SAME broadcast path
        // (ProductionQueues::cancel), so each refund lands in the shared pool
        // and ACCUMULATES. A raw ra2engine::cancel(q.structure()) refunds only
        // q_[0].credits without broadcasting; the following q.cancel(Defense)
        // then broadcasts q_[1]'s balance over all four queues, OVERWRITING the
        // Structure refund (reconcile_refund can't recover it — all four are
        // already equal). Cancel Structure FIRST so its refund is in the pool
        // before the Defense cancel builds on top of it.
        if (q.producing(ra2engine::QueueCat::Structure) != -1) q.cancel(ra2engine::QueueCat::Structure);
        if (q.producing(ra2engine::QueueCat::Defense) != -1) q.cancel(ra2engine::QueueCat::Defense);
    }
    // Factory-died cancels+refunds the matching unit queue (mirrors ConYard).
    if (q.producing(ra2engine::QueueCat::Infantry) != -1 && world.factory_category_lost(inf_ft, 0))
        q.cancel(ra2engine::QueueCat::Infantry);
    if (q.producing(ra2engine::QueueCat::Vehicle) != -1 && world.factory_category_lost(veh_ft, 0))
        q.cancel(ra2engine::QueueCat::Vehicle);
    if (q.producing(ra2engine::QueueCat::Naval) != -1 && world.factory_category_lost(nav_ft, 0))
        q.cancel(ra2engine::QueueCat::Naval);
    if (q.producing(ra2engine::QueueCat::Aircraft) != -1 && world.factory_category_lost(air_ft, 0))
        q.cancel(ra2engine::QueueCat::Aircraft);
    q.reconcile_refund();   // a refund raised one queue above the pool tail
}

// Building-roster indices for a building tab: GA* player buildings with a
// cameo, tech>0, art ok, split by the recovered BuildCat==Combat classifier
// [RE-GATE APPLIED: production.md §1.1]. tab 0 (Structures) = BuildCat!=Combat,
// tab 1 (Defenses) = BuildCat==Combat — tab 1 drives its OWN concurrent
// Defense queue (wired in Task 7), NOT a filtered view of the Structure queue.
// Ordered by tech_level then roster order.
std::vector<int> building_buildable_tab(const BuildingAssets& ba, bool defenses,
                                        const char* side_prefix);
std::vector<int> building_buildable_tab(const BuildingAssets& ba, bool defenses) {
    return building_buildable_tab(ba, defenses, "GA");
}
std::vector<int> building_buildable_tab(const BuildingAssets& ba, bool defenses,
                                        const char* side_prefix) {
    std::vector<int> v;
    for (int i = 0; i < static_cast<int>(ba.roster.size()); ++i) {
        const ra2engine::BuildingTypeDef& d = ba.roster[i];
        if (!ba.art[i].ok || d.cameo.empty() || d.tech_level <= 0) continue;
        // Player side prefix: "GA" (Allied, every existing caller) or "NA"
        // (P10 Soviet campaign).
        if (d.id.size() < 2 || d.id[0] != side_prefix[0] || d.id[1] != side_prefix[1]) continue;
        const bool def = i < static_cast<int>(ba.defense.size()) && ba.defense[i] != 0;
        if (def != defenses) continue;
        v.push_back(i);
    }
    std::stable_sort(v.begin(), v.end(),
                     [&](int a, int b) { return ba.roster[a].tech_level < ba.roster[b].tech_level; });
    return v;
}

// Structures tab (tab 0) — the DEMO-facing list of the player's non-defense
// buildable buildings. With the Economy phase's GAREFN appended to the roster
// it is {GAPOWR,GAREFN,GAPILE,GAWEAP} (tech-ordered), so it is not the bare
// pre-economy trio; the byte-identity demos build specific ids by roster_index,
// not this list, so their hashes are unaffected.
std::vector<int> sidebar_buildable(const BuildingAssets& ba) {
    return building_buildable_tab(ba, /*defenses=*/false);
}

// Built-in 5x7 digit strip (documented divergence [RE: construction.md §11 —
// the game font is not trivially extractable]); white, right-aligned.
static const uint8_t kDigits[10][7] = {
    {0x0E, 0x11, 0x13, 0x15, 0x19, 0x11, 0x0E}, {0x04, 0x0C, 0x04, 0x04, 0x04, 0x04, 0x0E},
    {0x0E, 0x11, 0x01, 0x02, 0x04, 0x08, 0x1F}, {0x1F, 0x02, 0x04, 0x02, 0x01, 0x11, 0x0E},
    {0x02, 0x06, 0x0A, 0x12, 0x1F, 0x02, 0x02}, {0x1F, 0x10, 0x1E, 0x01, 0x01, 0x11, 0x0E},
    {0x06, 0x08, 0x10, 0x1E, 0x11, 0x11, 0x0E}, {0x1F, 0x01, 0x02, 0x04, 0x08, 0x08, 0x08},
    {0x0E, 0x11, 0x11, 0x0E, 0x11, 0x11, 0x0E}, {0x0E, 0x11, 0x11, 0x0F, 0x01, 0x02, 0x0C},
};

void draw_number(SDL_Renderer* ren, int value, int right_x, int y, int scale) {
    const std::string s = std::to_string(value < 0 ? 0 : value);
    SDL_SetRenderDrawColor(ren, 255, 255, 255, 255);
    int x = right_x - static_cast<int>(s.size()) * 6 * scale;
    for (char ch : s) {
        const int d = ch - '0';
        if (d >= 0 && d <= 9)
            for (int row = 0; row < 7; ++row)
                for (int col = 0; col < 5; ++col)
                    if (kDigits[d][row] & (1 << (4 - col))) {
                        SDL_Rect px{x + col * scale, y + row * scale, scale, scale};
                        SDL_RenderFillRect(ren, &px);
                    }
        x += 6 * scale;
    }
}

// Centered variant: the original's credits tally prints "%d" centered at
// bar x+84 [RE: construction.md §11a, FUN_004A2280]. draw_number is
// right-aligned, so pass center + half the glyph run's width.
void draw_number_centered(SDL_Renderer* ren, int value, int center_x, int y, int scale) {
    const std::string s = std::to_string(value < 0 ? 0 : value);
    const int total_w = static_cast<int>(s.size()) * 6 * scale;
    draw_number(ren, value, center_x + total_w / 2, y, scale);
}

// [RE: skirmish.md §UI, D5] Draw a string as filled rects, same technique as
// draw_number. scale = pixel size of one glyph cell; 6px advance per glyph
// (5 wide + 1 space). Render-only; unhashed -- consumed only by the menu scenes
// (no byte-identity gate calls it), so it cannot affect any gate hash.
void draw_text(SDL_Renderer* ren, const std::string& s, int x, int y, int scale,
               std::uint8_t r = 255, std::uint8_t g = 255, std::uint8_t b = 255) {
    SDL_SetRenderDrawColor(ren, r, g, b, 255);
    int cx = x;
    for (char ch : s) {
        const std::array<std::uint8_t, 7>& rows = ra2engine::glyph_rows(ch);
        for (int row = 0; row < 7; ++row)
            for (int col = 0; col < 5; ++col)
                if (rows[row] & (1 << (4 - col))) {
                    SDL_Rect px{cx + col * scale, y + row * scale, scale, scale};
                    SDL_RenderFillRect(ren, &px);
                }
        cx += 6 * scale;
    }
}

// Blit one SHP frame at screen (x,y) (frame bbox offset applied), palettized
// via tc under `key` (position-independent, so the same key caches once).
void blit_shp(SDL_Renderer* ren, ra2engine::TextureCache& tc, const std::string& key_in,
              const ra2assets::ShpFile& shp, int frame, const ra2assets::Palette& pal, int x, int y) {
    if (frame < 0 || frame >= shp.count()) return;
    const std::string key = side_tex_key(key_in);   // W4-AM-04
    const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
    // An empty frame (0-dim, e.g. gclock2.shp frame 0 -- the build/recharge clock
    // starts its progress art at frame 1) draws nothing; skip it rather than let
    // TextureCache::get throw on a 0x0 SDL_CreateTexture. Render-only guard; no
    // gate folds textures (they fold world state), and any passing render path
    // already avoids empty frames, so gate outputs are unaffected.
    if (f.w <= 0 || f.h <= 0) return;
    SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
    if (!tex) {
        std::vector<uint8_t> idx = shp.decode_indexed(frame);
        tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, pal));
    }
    SDL_Rect dst{x + f.x, y + f.y, f.w, f.h};
    SDL_RenderCopy(ren, tex, nullptr, &dst);
}

// [Task 5] Return the cached SDL_Texture* for one SHP frame (decode+palettize
// once via `key`), so a caller can SDL_RenderCopy it into an ARBITRARY dst rect
// (blit_shp always draws at native size; the faithful menu needs the backdrop +
// buttons scaled/letterboxed). nullptr on an empty/out-of-range frame.
SDL_Texture* shp_frame_tex(ra2engine::TextureCache& tc, const std::string& key,
                           const ra2assets::ShpFile& shp, int frame,
                           const ra2assets::Palette& pal) {
    if (frame < 0 || frame >= shp.count()) return nullptr;
    const ra2assets::ShpFile::Frame f = shp.frame_info(frame);
    if (f.w <= 0 || f.h <= 0) return nullptr;
    SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
    if (!tex) {
        std::vector<uint8_t> idx = shp.decode_indexed(frame);
        tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, pal));
    }
    return tex;
}

// [Task 5] Blit a decoded PCX (opaque, a=255 for every pixel) at screen (x,y)
// through the TextureCache's ready-RGBA path (index-0-transparent does NOT apply
// -- PCX logos use index 0 as a real color). Cached by `key` (position-indep).

// [Task 5] Scaled variant of blit_pcx: fit the logo/title into a target width
// (preserving aspect), returned height via out_h. Used to size logo.pcx above
// the button column without distortion.

// [Task 5] The Westwood shell font stores per-pixel values as a small
// shading/bevel RAMP (0 = transparent, ~1..N = increasing "lit" level), NOT
// menu-palette indices -- routing them through cache.mix/palette.pal (whose low
// indices are near-black) is exactly the "garbled/near-invisible text" trap the
// brief flagged. So draw_fnt_text is given a SYNTHETIC ramp palette built here:
// index 0 transparent (handled by TextureCache::get), 1.. mapped to a warm
// metallic gold gradient that reads as the RA2 bevelled menu face.
ra2assets::Palette make_font_palette() {
    ra2assets::Palette p;
    for (int i = 0; i < 256; ++i) {
        int lvl = 40 + i * 55;                 // 1->95, 2->150, 3->205, 4->255...
        if (lvl > 255) lvl = 255;
        p[i] = ra2assets::Rgba{static_cast<uint8_t>(lvl),
                               static_cast<uint8_t>(lvl * 92 / 100),
                               static_cast<uint8_t>(lvl * 55 / 100), 255};
    }
    p[0] = ra2assets::Rgba{0, 0, 0, 0};        // (never used: idx 0 = transparent)
    return p;
}

// [P8 / options.md §4] The same shade ramp, but toward a solid control colour
// (the shell's control text is yellow 0x00FFFF, disabled dark red 0x00009F).
ra2assets::Palette make_font_palette_tinted(int r, int g, int b) {
    ra2assets::Palette p;
    for (int i = 0; i < 256; ++i) {
        int lvl = 40 + i * 55;
        if (lvl > 255) lvl = 255;
        p[i] = ra2assets::Rgba{static_cast<uint8_t>(r * lvl / 255),
                               static_cast<uint8_t>(g * lvl / 255),
                               static_cast<uint8_t>(b * lvl / 255), 255};
    }
    p[0] = ra2assets::Rgba{0, 0, 0, 0};
    return p;
}

// [Task 5] Pixel width of a string in the shell font (for centering labels).
int fnt_text_width(const ra2assets::Font& font, const std::string& s) {
    int w = 0;
    for (unsigned char ch : s) {
        const int cw = font.width(ch);
        w += (cw > 0 ? cw : font.height() / 2);
    }
    return w;
}

// [Task 5] Draw a string in the Westwood .fnt shell font at (x,y): each glyph is
// blitted as an indexed sprite through `pal` (the make_font_palette ramp; index
// 0 transparent), advancing x by the per-glyph width. `keypfx` namespaces the
// per-glyph TextureCache entries. `scale` enlarges the (small ~16px) glyphs to
// the 1280x720 menu.
void draw_fnt_text(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2assets::Font& font,
                   const ra2assets::Palette& pal, const std::string& s, int x, int y,
                   const std::string& keypfx, int scale = 1) {
    int cx = x;
    for (unsigned char ch : s) {
        const int w = font.width(ch);
        if (ch != ' ' && ch >= font.first() && ch <= font.last() && w > 0) {
            const ra2assets::FntGlyph& g = font.glyph(ch);
            if (g.w > 0 && g.h > 0) {
                const std::string key = keypfx + std::to_string((int)ch);
                SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
                if (!tex)
                    tex = static_cast<SDL_Texture*>(tc.get(key, g.pixels.data(), g.w, g.h, pal));
                SDL_Rect dst{cx, y, g.w * scale, g.h * scale};
                SDL_RenderCopy(ren, tex, nullptr, &dst);
            }
        }
        cx += (w > 0 ? w : font.height() / 2) * scale;   // space/missing glyph advance
    }
}

// [P8] draw_fnt_text with a FRACTIONAL scale (the options controls use a ~12px
// face inside 16px logical rows, scaled by the letterbox factor). Glyph dst
// rects are rounded from accumulated float positions so spacing stays even.
void draw_fnt_text_f(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2assets::Font& font,
                     const ra2assets::Palette& pal, const std::string& s, double x, double y,
                     const std::string& keypfx, double scale) {
    double cx = x;
    for (unsigned char ch : s) {
        const int w = font.width(ch);
        if (ch != ' ' && ch >= font.first() && ch <= font.last() && w > 0) {
            const ra2assets::FntGlyph& g = font.glyph(ch);
            if (g.w > 0 && g.h > 0) {
                const std::string key = keypfx + std::to_string((int)ch);
                SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
                if (!tex)
                    tex = static_cast<SDL_Texture*>(tc.get(key, g.pixels.data(), g.w, g.h, pal));
                const int x0 = static_cast<int>(std::lround(cx));
                const int x1 = static_cast<int>(std::lround(cx + g.w * scale));
                SDL_Rect dst{x0, static_cast<int>(std::lround(y)), x1 - x0,
                             static_cast<int>(std::lround(g.h * scale))};
                SDL_RenderCopy(ren, tex, nullptr, &dst);
            }
        }
        cx += (w > 0 ? w : font.height() / 2) * scale;
    }
}

void shade_rect(SDL_Renderer* ren, const ra2engine::SbRect& r, Uint8 alpha, Uint8 rr = 0,
                Uint8 gg = 0, Uint8 bb = 0) {
    SDL_SetRenderDrawBlendMode(ren, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(ren, rr, gg, bb, alpha);
    SDL_Rect rc{r.x, r.y, r.w, r.h};
    SDL_RenderFillRect(ren, &rc);
}

