// CB-4 Superweapons [spec §6]: draw the SW cameo + recharge indicator in a
// sidebar slot, reusing the EXISTING gclock2.shp 55-frame chrome + the flashing-
// green READY tint. Drawn ONLY when house 0 has a granted SW, so no existing
// demo (which grants none) changes its sidebar. `slot` is the target rect.
// W2-AN-04/23: the sidebar rect of house 0's k-th superweapon (grant order),
// a 2-wide grid from the radar area's top-left (the CB-4 slot is k = 0).
ra2engine::SbRect sw_slot_rect(const ra2engine::SidebarLayout& lay, int k) {
    return ra2engine::SbRect{lay.bar.x + ra2engine::kCameoX + (k % 2) * ra2engine::kCameoW,
                             lay.radar.y + 2 + (k / 2) * ra2engine::kCameoH, ra2engine::kCameoW,
                             ra2engine::kCameoH};
}

void draw_sw_slot(SDL_Renderer* ren, ra2engine::TextureCache& tc, const BuildingAssets& ba,
                  const ra2engine::World& world, const ra2engine::SbRect& slot0, double t_now) {
    const std::vector<ra2engine::SuperweaponType> types = world.sw_types(g_local_house);
    for (int k = 0; k < static_cast<int>(types.size()); ++k) {
    const ra2engine::SuperweaponType ty = types[k];
    const ra2engine::Superweapon* sw = world.sw_state(g_local_house, ty);
    if (!sw) continue;
    const ra2engine::SbRect slot{slot0.x + (k % 2) * ra2engine::kCameoW,
                                 slot0.y + (k / 2) * ra2engine::kCameoH, slot0.w, slot0.h};
    // Cameo (art-guarded): the SW's SidebarImage, else a placeholder shade.
    auto cam = ba.sw_cameos.find(static_cast<int>(ty));
    if (cam != ba.sw_cameos.end())
        blit_shp(ren, tc, "swcam:" + std::to_string(static_cast<int>(ty)), cam->second, 0,
                 ba.cameo_pal, slot.x, slot.y);
    else if (ba.sw_has_cameo)
        blit_shp(ren, tc, "swcam:nukeicon", ba.sb_nukeicon, 0, ba.cameo_pal, slot.x, slot.y);
    else
        shade_rect(ren, slot, 140);                     // placeholder tile
    (void)t_now;
    if (sw->ready) {
        // READY: the CSF "Ready" text, as on a production cameo (W2-UI-03).
        draw_cameo_text(ren, tc, slot.x, slot.y, g_txt_ready, 0);
    } else {
        // Charging: translucent gclock2 frame (W2-UI-02, the build-clock blit).
        int gframe = (int)std::lround(sw->charge_fraction() * 54.0);
        if (gframe < 0) gframe = 0;
        if (gframe >= ba.sb_gclock.count()) gframe = ba.sb_gclock.count() - 1;
        blit_shp_alpha(ren, tc, "sw:gclk" + std::to_string(gframe), ba.sb_gclock, gframe, ba.sb_pal,
                       slot.x, slot.y, 128);
    }
    }
}

// Shroud/Fog [RE: shroud.md §5 minimap]: the `Radar=yes` roster ids. A house
// "owns an operational radar" if it has an alive, non-Dead building of one of
// these types (a simple ownership scan; power gating is out of scope this
// phase — the interactive/demo paths that flip shroud on also own a radar).
static bool is_radar_id(const std::string& id) {
    return id == "GAAIRC" || id == "AMRADR" || id == "NARADR" || id == "NAPSIS";
}

// W9-05-05 [RE: MPlayer_Defeated FUN_004FBED0 -> FUN_00656830(1)]: the
// local observer of a network match has the radar forced on.
bool g_observer_radar = false;
bool house_owns_operational_radar(const ra2engine::World& world, const BuildingAssets& ba,
                                  int house) {
    if (g_observer_radar && house == g_local_house) return true;
    // G-29 (gap owner A) [RE: construction.md §8; RE-E4 consumer set PROBABLE]:
    // the radar goes offline while the house is on low power.
    if (world.house_low_power(house)) return false;
    for (const ra2engine::Building& b : world.buildings()) {
        if (b.house != house || !b.alive) continue;
        if (b.state == ra2engine::Building::State::Dead) continue;
        if (b.type < 0 || b.type >= static_cast<int>(ba.roster.size())) continue;
        if (is_radar_id(ba.roster[b.type].id)) return true;
    }
    return false;
}

// Shroud/Fog [RE: shroud.md §5 minimap]: draw a minimap into lay.radar. Paint
// ONLY cells EXPLORED by house 0 (terrain color); overlay unit blips ONLY for
// cells VISIBLE to house 0 (own house-0 units always shown). Gated on house 0
// owning an operational radar. Render-only; NOT part of any gate hash. With
// shroud off the grids are empty (all-explored) -> this is only reached when a
// radar is owned, matching today's behavior of showing the static logo
// otherwise. Falls back to the static "sb:radar" blit when no radar is owned.
void draw_radar_minimap(SDL_Renderer* ren, const ra2engine::SbRect& radar_rect,
                        const ra2engine::World& world, const BuildingAssets& ba) {
    // G-09: the live game's full radar picture (pres_radar.inc).
    if (g_radar && g_radar->ok()) {
        g_radar->draw(ren, radar_rect, world, ba);
        return;
    }
    const int gw = world.grid_w(), gh = world.grid_h();
    if (gw <= 0 || gh <= 0) return;
    // Map grid -> the 168x110 radar box (integer scale, letterboxed).
    const double sx = static_cast<double>(radar_rect.w) / gw;
    const double sy = static_cast<double>(radar_rect.h) / gh;
    for (int y = 0; y < gh; ++y)
        for (int x = 0; x < gw; ++x) {
            if (!world.explored_at(g_local_house, x, y)) continue;         // unexplored -> black (skip)
            SDL_Rect px{radar_rect.x + static_cast<int>(x * sx),
                        radar_rect.y + static_cast<int>(y * sy),
                        std::max(1, static_cast<int>(sx)), std::max(1, static_cast<int>(sy))};
            // terrain tint (dim if fogged, brighter if visible)
            Uint8 g = (!world.fog_of_war() || world.visible_at(g_local_house, x, y)) ? 120 : 60;   // W2-GA-03
            SDL_SetRenderDrawColor(ren, 30, g, 30, 255);
            SDL_RenderFillRect(ren, &px);
        }
    // Unit blips: only in currently-VISIBLE cells (own units always shown).
    // pal_for_house returns a full house-remapped palette (world.cpp:290); the
    // house remap ramp lives at indices 16..31, so a mid-ramp entry (24) is the
    // representative house color (blue=Allied, red=Soviet) — the same recolor
    // the building/unit sprites use.
    for (const ra2engine::Unit& u : world.units()) {
        if (!u.alive) continue;
        if (u.house != g_local_house && !world.object_visible_at(g_local_house, u.cell_x, u.cell_y)) continue;
        SDL_Rect bp{radar_rect.x + static_cast<int>(u.cell_x * sx),
                    radar_rect.y + static_cast<int>(u.cell_y * sy), 2, 2};
        const ra2assets::Rgba col = world.house_palette(ba.unit_pal, u.house)[24];
        SDL_SetRenderDrawColor(ren, col.r, col.g, col.b, 255);
        SDL_RenderFillRect(ren, &bp);
    }
}

// Draws the whole sidebar per the recovered composition [RE: construction.md
// §11a — credits(0,0) -> top cap(0,16) -> radar(0,48) -> side1(0,158) w/
// repair+sell -> tabs y=197 -> side2 x N rows from 227 -> side3 -> addon ->
// scroll buttons; §8 power pips]. `t_now` drives the Ready + outage flashes.
void draw_sidebar(SDL_Renderer* ren, ra2engine::TextureCache& tc, const BuildingAssets& ba,
                  const ra2engine::SidebarLayout& lay, const ra2engine::ProductionState& ps,
                  const ra2engine::World& world, int credits_shown, double t_now, int active_tab,
                  const UnitRoster* ur, bool unit_factory_alive, int armed_mode) {
    // Opaque backdrop behind any gaps (missing optional chrome), then the
    // recovered top-to-bottom stack.
    shade_rect(ren, lay.bar, 255, 24, 24, 28);
    // Credits strip at the very top; tally centered at x+84 [§11a].
    blit_shp(ren, tc, "sb:credits", ba.sb_credits, 0, ba.sb_pal, lay.credits.x, lay.credits.y);
    if (g_game_font && g_game_font_pal) {   // G-88: the game font in the live game
        const std::string cs = std::to_string(credits_shown);
        // W5-PRES R-142 [RE: credits draw 0x4A2280, colour 0xB0E98C by side
        // FUN_0072E520]: Allied RGB(164,210,255), Soviet/other RGB(255,255,0).
        const bool allied = std::string(g_sidebar_mix) == "sidec01.mix";
        hud_text_rgb(ren, tc, *g_game_font, cs, lay.credits.x + 84 - fnt_text_width(*g_game_font, cs) / 2,
                     lay.credits.y + 1, allied ? 164 : 255, allied ? 210 : 255, allied ? 255 : 0);
    } else {
        draw_number_centered(ren, credits_shown, lay.credits.x + 84, lay.credits.y + 2, 2);
    }
    // Bevel cap.
    blit_shp(ren, tc, "sb:top", ba.sb_top, 0, ba.sb_pal, lay.top_cap.x, lay.top_cap.y);
    // Options / diplomacy buttons over the cap (frame 0, inert).
    if (ba.has_optbtns) {
        blit_shp(ren, tc, "sb:optb", ba.sb_optbtn, 0, ba.sb_pal, lay.opt_btn.x, lay.opt_btn.y);     // W2-UI-08
        blit_shp(ren, tc, "sb:dipb", ba.sb_diplobtn, 0, ba.sb_pal, lay.diplo_btn.x, lay.diplo_btn.y);
    }
    // Radar area: a minimap when house 0 owns an operational radar (Shroud/Fog
    // [RE: shroud.md §5]); else radar.shp frame 0 = the pre-radar side logo
    // (today's behavior, byte-identical with shroud off / no radar) [§11a]. The
    // gate is behind world.shroud_enabled() (false in every existing gate), so
    // the static-logo branch runs exactly as today.
    if (world.shroud_enabled() && house_owns_operational_radar(world, ba, g_local_house)) {
        // G-09: radar.shp frames 1..N-1 are the power-up animation, the last
        // frame is the open frame drawn over the live map.
        const int boot = (g_radar && ba.has_radar) ? g_radar->boot_frame(ba.sb_radar.count()) : -1;
        if (boot > 0) {
            blit_shp(ren, tc, "sb:radar:" + std::to_string(boot), ba.sb_radar, boot, ba.sb_pal, lay.radar.x, lay.radar.y);
        } else {
            // The open frame is opaque; the map draws into the radar gadget's
            // viewport 140x108 at bar (16, 49) (W2-UI-09 [RE: construction.md
            // §11a radar gadget 223]) -- draw and click share it (cell_at).
            ra2engine::SbRect screen = lay.radar;
            if (g_radar && ba.has_radar && ba.sb_radar.count() > 1) {
                blit_shp(ren, tc, "sb:radar:open", ba.sb_radar, ba.sb_radar.count() - 1, ba.sb_pal,
                         lay.radar.x, lay.radar.y);
                screen = ra2engine::SbRect{lay.bar.x + 16, 49, 140, 108};
            }
            draw_radar_minimap(ren, screen, world, ba);
        }
    } else if (ba.has_radar) {
        // W2-UI-09: a radar that just went offline folds back (reverse boot).
        const int close = g_radar ? g_radar->close_frame(ba.sb_radar.count()) : 0;
        if (close > 0)
            blit_shp(ren, tc, "sb:radar:" + std::to_string(close), ba.sb_radar, close, ba.sb_pal, lay.radar.x,
                     lay.radar.y);
        else
            blit_shp(ren, tc, "sb:radar", ba.sb_radar, 0, ba.sb_pal, lay.radar.x, lay.radar.y);
    }
    // side1 band (carries the repair/sell socket art), then the buttons.
    blit_shp(ren, tc, "sb:side1", ba.sb_side1, 0, ba.sb_pal, lay.side1.x, lay.side1.y);
    // Repair / Sell buttons [RE: construction.md §11a rects; behaviour
    // repair-sell.md §C1]. Frame 1 is the PRESSED art, drawn while that mode is
    // armed (the mode-armed affordance §D8 keeps alongside the cursor). The
    // texture key carries the frame (blit_shp caches by key alone); frame 0
    // keeps its historical key, so the unarmed draw is unchanged.
    if (ba.has_repair_sell) {
        const bool rep_on = (armed_mode == 1), sell_on = (armed_mode == 2);
        blit_shp(ren, tc, rep_on ? "sb:rep1" : "sb:rep", ba.sb_repair, rep_on ? 1 : 0, ba.sb_pal,
                 lay.repair_btn.x, lay.repair_btn.y);
        blit_shp(ren, tc, sell_on ? "sb:sell1" : "sb:sell", ba.sb_sell, sell_on ? 1 : 0,
                 ba.sb_pal, lay.sell_btn.x, lay.sell_btn.y);
    }
    // Four tab buttons, tab0N.shp 5 frames (W2-UI-06): 0 normal, 1 lit (the
    // active tab), 2 blank (nothing to build on it). [ANCHORED: the TS-lineage
    // ShapeButtonClass frame order normal / on / disabled; frames 3/4 (the
    // new-cameo flash) are not played -- RE-OPEN Q2.]
    // W5-PRES R-142 [RE: StripClass::AI 0x6A81C0, tab tick 0x69D6A0, button
    // draw 0x69D540]: tabs 0/1 flash while a building there is ready to place,
    // toggling every 10 frames (on when (Frame/10) is odd): frame 3, or 4 on
    // the active tab.
    for (int i = 0; i < 4; ++i) {
        const bool flash_on = g_tab_flash[i] && ((g_pres_tick / 10) & 1) && ba.sb_tabs[i].count() >= 5;
        const int fr = (g_tab_has[i] == 0) ? 2 : flash_on ? (i == active_tab ? 4 : 3) : (i == active_tab ? 1 : 0);
        blit_shp(ren, tc, "sb:tab" + std::to_string(i) + ":" + std::to_string(fr), ba.sb_tabs[i], fr, ba.sb_pal,
                 lay.tabs[i].x, lay.tabs[i].y);
    }
    // Cameo strip: side2 tiled once per visible row (sockets are baked into
    // the art), side3 bottom cap, addon tail (clips at the window bottom),
    // scroll buttons frame 0 (inert) [§11a].
    for (int k = 0; k < lay.side2_rows; ++k)
        blit_shp(ren, tc, "sb:side2", ba.sb_side2, 0, ba.sb_pal, lay.bar.x,
                 lay.strip_top + k * 50);
    const int strip_bottom = lay.strip_top + lay.side2_rows * 50;
    if (ba.has_side3)
        blit_shp(ren, tc, "sb:side3", ba.sb_side3, 0, ba.sb_pal, lay.bar.x, strip_bottom);
    if (ba.has_addon)
        blit_shp(ren, tc, "sb:addon", ba.sb_addon, 0, ba.sb_pal, lay.bar.x,
                 strip_bottom + (ba.has_side3 ? ba.sb_side3.height() : 0));
    if (ba.has_scroll) {
        blit_shp(ren, tc, "sb:rdn", ba.sb_rdn, 0, ba.sb_pal, lay.scroll_dn.x, lay.scroll_dn.y);
        blit_shp(ren, tc, "sb:rup", ba.sb_rup, 0, ba.sb_pal, lay.scroll_up.x, lay.scroll_up.y);
    }
    // Power meter [RE: construction.md §8 pip model, §11a geometry — the
    // column runs from the strip top at x=+5, capacity (strip_h+3)/3
    // precomputed by SidebarLayout].
    // Engineer/Spy Capture [RE: capture.md §B2]: the HUD visibly blacks out while
    // a spied power plant's timer runs (identity when !house_blacked_out(0), so
    // every existing demo's readout is byte-identical).
    const ra2engine::PowerTotals pt =
        ra2engine::apply_blackout(ra2engine::power_totals(world.buildings(), ba.roster, g_local_house),
                                  world.house_blacked_out(g_local_house));
    const int output = pt.output, drain = pt.drain;
    int total_pips = lay.power_pips;
    if (total_pips < 1) total_pips = 1;
    // Capacity scale (FUN_0063F2F0): total_power = Sum output + Sum drain;
    // pips_used = total_pips - clamp(ftol(total_pips*400/(total_power+400)),
    // 0, total_pips-1) -- the clamp upper bound of total_pips-1 (not
    // total_pips) is what guarantees at least 1 pip whenever there is any
    // power at all (and, per the literal formula, even at zero power).
    const int total_power = output + drain;
    const int inner = std::clamp(
        static_cast<int>(total_pips * 400.0 / (total_power + 400.0)), 0, total_pips - 1);
    int pips_used = total_pips - inner;
    if ((output + drain) > 0 && pips_used < 1) pips_used = 1;
    // Color split (FUN_0063F400): surplus = output - drain; surplus<0 -> no
    // green/yellow (red_amt=drain only); else yellow_amt=min(surplus,100),
    // green_amt=surplus-yellow_amt, red_amt=drain. Pips are divided
    // proportionally by amt/(drain+yellow_amt+green_amt) -- for surplus>=0
    // that denominator collapses to `output` (drain+yellow+green = drain +
    // surplus = output), NOT output+drain.
    const int surplus = output - drain;
    int yellow_amt = 0, green_amt = 0;
    if (surplus >= 0) {
        yellow_amt = std::min(surplus, 100);
        green_amt = surplus - yellow_amt;
    }
    const int red_amt = drain;
    const int denom = red_amt + yellow_amt + green_amt;
    int red = 0, yellow = 0;
    if (denom > 0) {
        red = static_cast<int>(std::lround((double)pips_used * red_amt / denom));
        yellow = static_cast<int>(std::lround((double)pips_used * yellow_amt / denom));
    }
    int green = pips_used - red - yellow;
    if (green < 0) green = 0;
    const bool outage = drain > output;
    for (int i = 0; i < total_pips; ++i) {
        int frame = (i < red) ? 3 : (i < red + yellow) ? 2 : (i < pips_used) ? 1 : 0;
        if (outage && i < pips_used && (static_cast<int>(t_now / 0.2) % 2 == 0)) frame = 4;
        const int py = lay.power.y + lay.power.h - (i + 1) * 3;
        blit_shp(ren, tc, "sb:pp" + std::to_string(frame), ba.sb_powerp, frame, ba.sb_pal,
                 lay.power.x, py);
    }
    // Cameo grid + per-state overlay. On unit tabs (2/3) `c.type` indexes the
    // UnitRoster (not ba.art); the blit uses the unit cameo cache and the
    // overlay tracks THIS tab's own queue (`ps` = queues.state(cat)). The
    // disabled-shade can_start call is building-roster-based, so it is guarded
    // to building tabs only (unit tabs skip the cosmetic disabled shade).
    const bool unit_tab = (active_tab >= 2 && ur);
    for (const ra2engine::CameoCell& c : lay.cameos) {
        const int type = c.type;
        if (unit_tab) {
            if (type < 0 || type >= static_cast<int>(ur->defs.size())) continue;
            if (type < static_cast<int>(ur->has_cameo.size()) && ur->has_cameo[type])
                blit_shp(ren, tc, "ucam:" + ur->defs[type].id, ur->cameos[type], 0, ba.cameo_pal,
                         c.rect.x, c.rect.y);
        } else {
            if (type < 0 || type >= static_cast<int>(ba.art.size())) continue;
            if (ba.art[type].has_cameo)
                blit_shp(ren, tc, "cam:" + ba.roster[type].id, ba.art[type].cameo, 0, ba.cameo_pal,
                         c.rect.x, c.rect.y);
        }
        // CB-5 [RE: techtree.md §1]: unit tabs now compute buildability too (was
        // building-tabs-only). Unit cameo availability reuses can_start_unit
        // against the SAME predicate; building cameos keep can_start. Render-only;
        // no gate renders an interactive unit tab (spec §8).
        bool can;
        if (unit_tab)
            can = ra2engine::can_start_unit(ps, type, ur->defs, world.buildings(), ba.roster, 0,
                                            ba.groups, unit_factory_alive);
        else
            can = ra2engine::can_start(ps, type, ba.roster, world.buildings(), 0, ba.groups,
                                       conyard_alive(world, ba, g_local_house));
        // W2-UI-02/05 [RE: wave2/04 #2, FUN_0067F800]: DARKEN.SHP (0x401) when
        // the item cannot be built; while in production GCLOCK2 frame stage+1
        // TRANSLUCENT (0x404 = 50 %) with no shade under it; a ready item shows
        // only its "Ready" text (draw_queue_badges).
        if (ps.slot.type == type && ps.slot.ready) {
            // Ready: no clock (text drawn by GameScene::draw_queue_badges).
        } else if (ps.slot.type == type) {
            int gframe = 1 + ps.slot.stage;
            if (gframe >= ba.sb_gclock.count()) gframe = ba.sb_gclock.count() - 1;
            blit_shp_alpha(ren, tc, "sb:gclk" + std::to_string(gframe), ba.sb_gclock, gframe, ba.sb_pal,
                           c.rect.x, c.rect.y, 128);
        } else if (!can) {
            if (ba.has_darken) blit_shp_darken(ren, tc, "sb:darken", ba.sb_darken, 0, c.rect.x, c.rect.y);
            else shade_rect(ren, c.rect, 128);
        }
        // W5-PRES R-039 [RE: strip draw 0x6A8BD0, SidebarClass::FlashCameo
        // 0x6ABC80]: a flashed cameo shows DARKEN 50 % translucent (0x404)
        // while Frame < FlashEndFrame and Frame % 16 > 8.
        if (!unit_tab && ba.has_darken && !g_cameo_flash.empty()) {
            auto fl = g_cameo_flash.find(ba.roster[type].id);
            if (fl != g_cameo_flash.end() && g_pres_tick < fl->second && g_pres_tick % 16 > 8)
                blit_shp_alpha(ren, tc, "sb:darkf", ba.sb_darken, 0, ba.sb_pal, c.rect.x, c.rect.y, 128);
        }
    }
    // CB-4 Superweapons [spec §6]: the SW cameo + recharge clock in an unused
    // slot (the radar-area top-left). draw_sw_slot no-ops unless house 0 has a
    // granted SW, so no existing demo (which grants none) changes its sidebar.
    const ra2engine::SbRect sw_slot{lay.bar.x + ra2engine::kCameoX, lay.radar.y + 2,
                                    ra2engine::kCameoW, ra2engine::kCameoH};
    draw_sw_slot(ren, tc, ba, world, sw_slot, t_now);
}

// Placement cursor: draw the fw*fh foundation cell diamonds green (cell OK) /
// red (cell blocked OR adjacency fails -> whole grid red) [RE: construction.md §9].
#include "pres_place.inc"   // W5-PRES R-102 PLACE.SHP grid, R-144 primary / rally markers
void draw_placement_cursor(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ra2engine::World& world,
                           const BuildingAssets& ba, const ra2engine::Input& input,
                           const Assets& a, const ra2engine::Camera& cam, int W, int H,
                           const ra2engine::PlacementCheck* pre_chk = nullptr) {
    if (!input.placement_active()) return;
    const int type = input.placement_type();
    if (type < 0 || type >= static_cast<int>(ba.roster.size())) return;
    const ra2engine::BuildingTypeDef& d = ba.roster[type];
    int cx = 0, cy = 0;
    input.placement_cell(cx, cy);
    // Gap owner A: the real game passes the scene's own rule set (water-bound
    // Naval Yard, BaseNormal) so the cursor colour matches what a click does.
    const ra2engine::PlacementCheck chk = pre_chk ? *pre_chk : ra2engine::placement_check(
        cx, cy, d.fw, d.fh, 0, d.adjacent, world.passable(), world.grid_w(), world.grid_h(),
        world.occupancy(), world.buildings(), /*bypass_adjacency=*/false, nullptr,
        world.build_mask(d.wall));   // W8-03-01
    SDL_SetRenderDrawBlendMode(ren, SDL_BLENDMODE_BLEND);
    const std::vector<ra2engine::Cellxy> cells = ra2engine::foundation_cells(cx, cy, d.fw, d.fh);
    // W5-PRES R-102: the live game draws PLACE.SHP (CellClass::DrawPlacement).
    if (pres_draw_place_grid(ren, tc, chk, cells, a, cam, W, H)) return;
    for (std::size_t k = 0; k < cells.size(); ++k) {
        const ra2assets::MapCell* mc = a.map.at(cells[k].x, cells[k].y);
        const int level = mc ? mc->level : 0;
        const ra2engine::ScreenPt p =
            ra2engine::cell_to_screen(cells[k].x, cells[k].y, level, 60, 30, 15);
        const int sx = p.x + cam.x, sy = p.y + cam.y;
        const bool ok = chk.adjacency && (k < chk.cell_ok.size() ? chk.cell_ok[k] : false);
        if (ok) SDL_SetRenderDrawColor(ren, 0, 220, 0, 160);
        else SDL_SetRenderDrawColor(ren, 220, 0, 0, 160);
        SDL_Point diamond[5] = {{sx + 30, sy},      {sx + 60, sy + 15}, {sx + 30, sy + 30},
                                {sx, sy + 15},       {sx + 30, sy}};
        SDL_RenderDrawLines(ren, diamond, 5);
    }
}

// Repair / Sell mode cursor art [RE: repair-sell.md §D8]: MOUSE.SHP
// (ra2.mix/conquer.mix, 450 frames, 55x43 canvas) drawn with
// ra2.mix/cache.mix/mousepal.pal. Interactive-only; no gate constructs one.
struct ModeCursor {
    ra2assets::ShpFile shp;
    ra2assets::Palette pal{};
    bool ok = false;
};

// Draw the armed-mode software cursor at window pixel (mx, my). Frame groups
// are the six §D8 entries [30]..[35] of the cursor descriptor table at
// gamemd.exe 0x0082C038 (re-read from the binary for this task: {129,10,4},
// {139,10,4}, {149,1,0}, {150,20,4}, {170,20,4}, {190,1,0}), each animated at
// one cursor frame per 4 game frames. Pair assignment per §D8 (PROBABLE):
// brackets = over a valid target, plain spin = armed over nothing, crossed-out
// = over a building the action refuses. Hotspot: all six entries carry
// HotX = HotY = 12345, YRpp's MouseHotSpotX::Center / MouseHotSpotY::Middle,
// so the canvas CENTER sits on the pointer. Returns true iff it drew (so the
// caller can hide the OS cursor).
bool draw_mode_cursor(SDL_Renderer* ren, ra2engine::TextureCache& tc, const ModeCursor& mc,
                      const ra2engine::World& world, const BuildingAssets& ba,
                      const ra2engine::Input& input, int mx, int my, std::uint64_t game_frame) {
    const ra2engine::Input::BaseMode mode = input.base_mode();
    if (!mc.ok || mode == ra2engine::Input::BaseMode::None || mode == ra2engine::Input::BaseMode::PowerToggle)
        return false;   // W5-E2: no power-toggle cursor art in YR [RE-FALLBACK: the normal cursor]
    const bool repair = (mode == ra2engine::Input::BaseMode::Repair);
    const int bi = input.building_under(mx, my);
    // 0 = armed over nothing, 1 = valid target, 2 = refused target.
    int state = 0;
    if (bi >= 0) {
        const ra2engine::Building& b = world.buildings()[bi];
        bool valid = (b.house == g_local_house && b.type >= 0 && b.type < static_cast<int>(ba.roster.size()));
        if (valid)
            valid = repair ? (!b.selling && ra2engine::can_be_click_repaired(b, ba.roster[b.type]))
                           : ra2engine::can_be_sold(b, ba.roster[b.type], /*c4_applied=*/b.c4_applied);
        state = valid ? 1 : 2;
    }
    const int tick = static_cast<int>((game_frame / 4) % 20);
    int frame = 0;
    if (repair) frame = state == 1 ? 150 + tick : state == 2 ? 190 : 170 + tick;
    else        frame = state == 1 ? 129 + tick % 10 : state == 2 ? 149 : 139 + tick % 10;
    if (frame >= mc.shp.count()) return false;
    const ra2assets::ShpFile::Frame f = mc.shp.frame_info(frame);
    if (f.w <= 0 || f.h <= 0) return false;
    char key[32];
    std::snprintf(key, sizeof key, "mouse:%d", frame);
    SDL_Texture* tex = static_cast<SDL_Texture*>(tc.peek(key));
    if (!tex) {
        std::vector<uint8_t> idx = mc.shp.decode_indexed(frame);
        tex = static_cast<SDL_Texture*>(tc.get(key, idx.data(), f.w, f.h, mc.pal));
    }
    SDL_Rect dst{mx - mc.shp.width() / 2 + f.x, my - mc.shp.height() / 2 + f.y, f.w, f.h};
    SDL_RenderCopy(ren, tex, nullptr, &dst);
    return true;
}

// Production chrome [RE: production.md §1.2/§1.4] — cosmetic, never mutates the
// sim. A small filled yellow triangle marks each own (house 0) alive PRIMARY
// unit factory at its foundation screen center; a cyan X marks the selected
// factory's rally cell. Both are clipped to the playfield (left of the sidebar)
// and tagged like the divergent READY overlay. `playfield_w` is the world
// viewport width (window minus the sidebar strip).
void draw_production_chrome(SDL_Renderer* ren, const ra2engine::World& world,
                            const ra2engine::Input& input, const Assets& a,
                            const ra2engine::Camera& cam, int playfield_w,
                            ra2engine::TextureCache* tc = nullptr) {
    SDL_SetRenderDrawBlendMode(ren, SDL_BLENDMODE_BLEND);
    auto cell_center_px = [&](int cx, int cy, int& sx, int& sy) {
        const ra2assets::MapCell* mc = a.map.at(cx, cy);
        const int level = mc ? mc->level : 0;
        const ra2engine::ScreenPt p = ra2engine::cell_to_screen(cx, cy, level, 60, 30, 15);
        sx = p.x + cam.x + 30;   // + tile_w/2 (diamond center)
        sy = p.y + cam.y + 15;   // + tile_h/2
    };
    // W5-PRES R-144: the live game shows the original's TXT_PRIMARY label on
    // the selected primary factory (pres_place.inc) instead of the triangle.
    if (tc && g_fx && g_game_font) {
        const int sbi = input.selected_building();
        if (sbi >= 0 && sbi < static_cast<int>(world.buildings().size())) {
            const ra2engine::Building& b = world.buildings()[sbi];
            if (b.alive && b.house == g_local_house && b.primary) {
                const ra2engine::ScreenPt dp = ra2engine::building_draw_point(b.cx, b.cy,
                    a.map.at(b.cx, b.cy) ? a.map.at(b.cx, b.cy)->level : 0);
                pres_draw_primary_label(ren, *tc, world, b, dp.x + cam.x, dp.y + cam.y + 15 * (b.fw + b.fh) / 2,
                                        playfield_w);
            }
        }
    }
    // Primary-factory markers.
    SDL_SetRenderDrawColor(ren, 255, 220, 40, 220);
    for (const ra2engine::Building& b : world.buildings()) {
        if (tc && g_fx && g_game_font) break;   // W5-PRES: replaced by the label above
        if (!b.alive || b.house != g_local_house || !b.primary) continue;
        int sx = 0, sy = 0;
        cell_center_px(b.cx + b.fw / 2, b.cy + b.fh / 2, sx, sy);
        if (sx < 0 || sx >= playfield_w) continue;
        SDL_Point tri[4] = {{sx, sy - 10}, {sx - 7, sy + 4}, {sx + 7, sy + 4}, {sx, sy - 10}};
        SDL_RenderDrawLines(ren, tri, 4);
        for (int yy = -8; yy <= 3; ++yy) {  // crude fill
            const int half = (yy + 8) * 7 / 11;
            SDL_RenderDrawLine(ren, sx - half, sy + yy, sx + half, sy + yy);
        }
    }
    // Rally marker for the selected factory.
    const int sb = input.selected_building();
    if (sb >= 0 && sb < static_cast<int>(world.buildings().size())) {
        const ra2engine::Building& b = world.buildings()[sb];
        if (b.alive && b.has_rally && b.house == g_local_house && tc && g_fx) {
            // W5-PRES R-144: the original's marching-ants rally line.
            const ra2assets::MapCell* bm = a.map.at(b.cx, b.cy);
            const double bx = b.cx + (b.fw - 1) / 2.0, by = b.cy + (b.fh - 1) / 2.0;
            const int lv = bm ? bm->level : 0;
            const int ax = static_cast<int>(std::lround((bx - by) * 30.0)) + cam.x + 30;
            const int ay = static_cast<int>(std::lround((bx + by) * 15.0 - lv * 15)) + cam.y + 15;
            int rx = 0, ry = 0;
            cell_center_px(b.rally_x, b.rally_y, rx, ry);
            const SDL_Rect clip{0, 0, playfield_w, 10000};
            SDL_RenderSetClipRect(ren, &clip);
            pres_draw_rally_line(ren, world, b, ax, ay, rx, ry);
            SDL_RenderSetClipRect(ren, nullptr);
        } else if (b.alive && b.has_rally) {
            int sx = 0, sy = 0;
            cell_center_px(b.rally_x, b.rally_y, sx, sy);
            if (sx >= 0 && sx < playfield_w) {
                SDL_SetRenderDrawColor(ren, 40, 230, 230, 230);
                SDL_RenderDrawLine(ren, sx - 8, sy - 8, sx + 8, sy + 8);
                SDL_RenderDrawLine(ren, sx - 8, sy + 8, sx + 8, sy - 8);
            }
        }
    }
}

// [RE: skirmish.md §2, D4] launch_skirmish is DEFINED far below (near the demo
// gates); forward-declare it here so GameScene's ctor can build its World from a
// SkirmishConfig. Purely additive: the 16 gates never touch this path.
ra2engine::World launch_skirmish(const ra2engine::SkirmishConfig& cfg,
                                 Assets& a, UnitAssets& ua, BuildingAssets& ba,
                                 const Rules& rules, const Ini* gf_rules_ini = nullptr,
                                 std::vector<std::string>* gf_spawned = nullptr);

// ============================================================================
// [P8 Options + persistence, RE: docs/re/options.md] The user's RA2.INI.
// ============================================================================
// Published ONLY by run_menu (the interactive desktop default + Android entry)
// after it loads the file; null everywhere else. No gate ever calls run_menu,
// constructs GameScene or reads the settings file, and --menu-shot renders with
// built-in defaults -- so the byte-identity gates cannot see a user's settings.
ra2engine::Settings* g_user_settings = nullptr;
bool pres_target_lines() { return g_user_settings ? g_user_settings->unit_action_lines : true; }
bool pres_score_shuffle() { return g_user_settings ? g_user_settings->is_score_shuffle : false; }   // W2-GA-21
bool pres_score_repeat() { return g_user_settings ? g_user_settings->is_score_repeat : false; }

// <SDL pref dir>/RA2.INI: %APPDATA%\ra2engine\RA2\ on Windows, the app's
// internal (always writable) files dir on Android. Never the install dir. Empty
// string if SDL cannot provide a writable path (settings then stay in memory).
std::string settings_file_path() {
    // G0 --play isolates RA2.INI + saves under its out dir (RA2_PREF_DIR).
    if (const char* o = std::getenv("RA2_PREF_DIR")) return std::string(o) + "RA2.INI";
    char* p = SDL_GetPrefPath("ra2engine", "RA2");
    if (!p) return {};
    std::string s = std::string(p) + "RA2.INI";
    SDL_free(p);
    return s;
}

// The whole file as an IniDoc (empty doc if absent/unreadable).
ra2engine::IniDoc read_settings_doc(const std::string& path) {
    if (path.empty()) return ra2engine::IniDoc::parse("");
    std::ifstream f(path, std::ios::binary);
    if (!f) return ra2engine::IniDoc::parse("");
    std::ostringstream ss;
    ss << f.rdbuf();
    return ra2engine::IniDoc::parse(ss.str());
}

// FUN_005d8b00: absent file/keys -> the OptionsClass ctor defaults.
ra2engine::Settings load_user_settings() {
    const std::string path = settings_file_path();
    ra2engine::Settings s = ra2engine::load_settings(read_settings_doc(path));
    std::cerr << "[settings] " << (path.empty() ? "(no pref path)" : path)
              << " scroll_rate=" << s.scroll_rate << " sound=" << s.sound_volume
              << " voice=" << s.voice_volume << " score=" << s.score_volume << "\n";
    return s;
}

// FUN_005d91b0: read-modify-write so every foreign section/key/comment of an
// existing file survives; only the OptionsClass save list is rewritten.
bool save_user_settings(const ra2engine::Settings& s) {
    const std::string path = settings_file_path();
    if (path.empty()) return false;
    ra2engine::IniDoc doc = read_settings_doc(path);
    ra2engine::store_settings(s, doc);
    std::ofstream f(path, std::ios::binary | std::ios::trunc);
    if (!f) { std::cerr << "[settings] cannot write " << path << "\n"; return false; }
    const std::string text = doc.serialize();
    f.write(text.data(), static_cast<std::streamsize>(text.size()));
    std::cerr << "[settings] saved " << path << "\n";
    return static_cast<bool>(f);
}

// W5-E: the writable pref dir (with a trailing separator; "" if none).
std::string pref_dir_path() {
    const std::string s = settings_file_path();
    return s.size() >= 7 ? s.substr(0, s.size() - 7) : std::string();   // strip "RA2.INI"
}

// W5-E Keyboard page (0xA3) [RE: options.md §6 -- bindings persist in
// Keyboard.ini [Hotkey] <Command>=<code>]: the shipped defaults, then the
// install's Keyboard.ini (KeyboardMD.ini when absent), then the player's own
// <pref dir>/Keyboard.ini written by the page (the install is read-only).
ra2engine::HotkeyTable load_hotkey_table() {
    ra2engine::HotkeyTable t = ra2engine::HotkeyTable::defaults();
    for (const char* f : {"Keyboard.ini", "KeyboardMD.ini"}) {
        try {
            const std::vector<uint8_t> raw = ra2assets::read_file(env_install_dir() + f);
            t.load_ini_text(std::string(raw.begin(), raw.end()));
            break;
        } catch (const std::exception&) { /* next / defaults */ }
    }
    const std::string own = pref_dir_path();
    if (!own.empty()) {
        std::ifstream in(own + "Keyboard.ini", std::ios::binary);
        if (in) {
            std::ostringstream ss;
            ss << in.rdbuf();
            t.load_ini_text(ss.str());
        }
    }
    return t;
}
bool save_hotkey_table(const ra2engine::HotkeyTable& t) {
    const std::string own = pref_dir_path();
    if (own.empty()) return false;
    std::ofstream f(own + "Keyboard.ini", std::ios::binary | std::ios::trunc);
    if (!f) return false;
    const std::string text = t.to_ini_text();
    f.write(text.data(), static_cast<std::streamsize>(text.size()));
    return static_cast<bool>(f);
}

// options.md §5: SoundVolume -> SFX bus, VoiceVolume -> speech/EVA bus,
// ScoreVolume -> music bus; linear gain.
void apply_audio_settings(ra2engine::Mixer& m, const ra2engine::Settings& s) {
    m.set_bus_gain(ra2engine::AudioBus::Sound, ra2engine::volume_gain_permille(s.sound_volume));
    m.set_bus_gain(ra2engine::AudioBus::Voice, ra2engine::volume_gain_permille(s.voice_volume));
    m.set_bus_gain(ra2engine::AudioBus::Score, ra2engine::volume_gain_permille(s.score_volume));
}

// [RE: skirmish.md §2, D4] Minimal polymorphic scene interface. Additive: driven
// ONLY at the two non-gate main() seams (Android + desktop fallthrough); no gate
// constructs or enters it. NOT hashed.
struct Scene {
    virtual void   handle(const ra2engine::InputEvent& ev) { (void)ev; }
    virtual void   update(double dt)                        { (void)dt; }
    virtual void   render(ra2engine::Platform& plat, ra2engine::TextureCache& tc) {
        (void)plat; (void)tc;
    }
    virtual Scene* next()                                   { return nullptr; }  // non-null => transition (takes ownership)
    virtual bool   wants_quit() const                       { return false; }
    // G0 --play harness: report state + named click targets (play_driver.inc).
    // Default: an unprobed scene ("unknown"). Never called outside --play.
    virtual void   play_probe(ra2play::Probe& p)            { (void)p; }
    virtual ~Scene()                                        = default;
    // G0 --play harness hooks (engine/play_driver.inc). name() tags the probe;
    // locate() resolves a semantic target ("button:<label>", "cell:x,y",
    // "unit:H:IMAGE:n", "cameo:ID") to a window pixel; probe() reports the
    // scene's observable state as integers; cheat() applies a test-only edit.
    virtual const char* name() const                        { return "scene"; }
    virtual bool   locate(const std::string& what, int& x, int& y) const {
        (void)what; (void)x; (void)y; return false;
    }
    virtual void   probe(std::map<std::string, long long>& out) const { (void)out; }
    virtual bool   cheat(const std::vector<std::string>& args) { (void)args; return false; }
    // W2-AR-06: the logical canvas width this scene lays out for (height is
    // always 720). The shell pages are fixed 1280 (the original's 800x600
    // shell, centred); GameScene widens with the panel's aspect.
    virtual int    logical_width() const                    { return 1280; }
    virtual int    logical_height() const                   { return 720; }
};

// G0: per-frame observer of run_scene_driver (the --play harness). begin()
// runs before the frame's events are polled (the harness queues scripted
// events there) and returns false to stop the run; end() runs after the frame
// is presented (captures, probes, assertions); quit() reports that the
// PROCESS WOULD EXIT (a Quit event or a scene's wants_quit) at frame f.
struct DriverHooks {
    virtual bool begin(int f, Scene& s) = 0;
    virtual void end(int f, Scene& s, ra2engine::Platform& plat) = 0;
    virtual void quit(int f, Scene* s, const char* why) = 0;
    // G0 --play additions (defaults = the behaviour above): render this frame?
    // (end() still runs every frame); swallow a Quit event after recording it
    // (`set on_quit continue`); a scene swap happened at frame f.
    virtual bool want_render(int f) { (void)f; return true; }
    virtual bool swallow_quit(int f) { (void)f; return false; }
    virtual void transition(int f) { (void)f; }
    // W6-01-10 --play `lifecycle relaunch`: true once to end the current scene
    // (its destructor runs, as on an Android activity restart) and start the
    // next from relaunch_scene() -- the app's startup path.
    virtual bool want_relaunch() { return false; }
    virtual Scene* relaunch_scene() { return nullptr; }
    virtual ~DriverHooks() = default;
};

// W2-AR-02/-03/-05/-10/-30: loading screen, deferred scene construction,
// error page, missing-files page, SDL assertion handler.
// W6-01-15: `set canvas WxH` in a --play script -- the game canvas a phone
// would get (e.g. 974x548), instead of the harness's 1280x720 (0 = default).
int g_play_canvas_w = 0, g_play_canvas_h = 0;
#include "app_robust.inc"

// The scene-loop driver: owns the active Scene*, pumps input -> handle, ticks
// update(dt) with the real wall-clock dt, calls render, and on a non-null next()
// swaps scenes (deleting the old). Returns 0 on clean quit.
// G0: `src` replaces the Platform as the event source (the --play harness's
// scripted events); `fixed_dt > 0` steps update(fixed_dt) once per iteration
// with no wall clock and no frame delay (deterministic); `hooks` observes
// every frame. The defaults are exactly the interactive behaviour.
void net_linger_pump();   // NET-PLAY (net_play.inc): finished matches flush their EXIT
int run_scene_driver(ra2engine::Platform& plat, ra2engine::TextureCache& tc, Scene* initial,
                     ra2engine::EventSource* src = nullptr, double fixed_dt = 0.0,
                     DriverHooks* hooks = nullptr) {
    std::unique_ptr<Scene> scene(initial);
    ra2engine::EventSource& events = src ? *src : static_cast<ra2engine::EventSource&>(plat);
    Uint32 prev = SDL_GetTicks();
    int frame = 0;
    g_platform = &plat;
    // R-184: --record writes this run's events + time steps; --replay
    // (run_menu passes the InputReplay as `src`) plays them back.
    std::unique_ptr<InputRecorder> rec;
    if (!g_record_path.empty()) {
        rec.reset(new InputRecorder);
        if (!rec->open(g_record_path)) rec.reset();
        else SDL_Log("[replay] recording input to %s", g_record_path.c_str());
        g_record_path.clear();   // one driver run per recording
    }
    InputReplay* replay = dynamic_cast<InputReplay*>(src);
    auto finish = [&](const char* why) {
        if (rec || replay) replay_report(replay ? "replay" : "record", frame, scene.get());
        (void)why;
    };
    // W2-GA-P6: frame pacing by deadline (60 Hz) instead of a fixed 16 ms
    // sleep AFTER the frame's work; with the vsync'd renderer present()
    // already waits, so this only sleeps the part of the budget left.
    Uint64 frame_start = SDL_GetPerformanceCounter();
    const double perf_ms = 1000.0 / static_cast<double>(SDL_GetPerformanceFrequency());
    while (scene && !scene->wants_quit()) {
        // W2-AR-06: the canvas follows the scene (shell 1280x720, the game
        // as wide as the panel's aspect allows) BEFORE input is polled, so
        // pointer/finger coordinates map to the same canvas.
        g_ui_w = scene->logical_width();
        g_ui_h = scene->logical_height();
        plat.set_logical_size(g_ui_w, g_ui_h);
        const Uint64 pc0 = SDL_GetPerformanceCounter();   // R-170 perf phases
        if (replay) {
            replay->begin_frame(frame);
            if (replay->done()) { finish("end of recording"); return 0; }
        }
        if (hooks && !hooks->begin(frame, *scene)) { finish("hooks"); return 0; }
        ra2engine::InputEvent ev;
        while (events.poll(ev)) {
            // R-170: the perf overlay toggle never reaches a scene.
            if (ev.kind == ra2engine::InputEvent::Key &&
                (ev.key == ra2engine::kKeyPerfToggle || (ev.vk == 'F' && ev.ctrl && ev.shift))) {
                perf_toggle();
                continue;
            }
            if (rec) rec->event(ev);
            if (ev.kind == ra2engine::InputEvent::Quit) {
                if (hooks && hooks->swallow_quit(frame)) continue;   // --play on_quit continue
                // W6-01-10: Android is restarting the activity (not the
                // player quitting). SDL queues this Quit (nativeQuit) ahead
                // of the pause's WILLENTERBACKGROUND, so the scene would never
                // see the background event: hand it one now, which writes
                // the autosave the next start offers to resume.
                if (ra2engine::os_keep_autosave() && scene) {
                    ra2engine::InputEvent bg;
                    bg.kind = ra2engine::InputEvent::AppBackground;
                    scene->handle(bg);
                }
                if (hooks) hooks->quit(frame, scene.get(), "Quit event");
                if (rec) rec->frame(frame, 0.0);
                finish("quit");
                return 0;
            }
            // W2-AR-26/-09: GL context lost -> every texture handle is dead
            // (entries rebuild lazily); low memory -> drop unpinned textures.
            if (ev.kind == ra2engine::InputEvent::RenderReset) {
                tc.clear();
                SDL_Log("[lifecycle] render device reset: texture cache cleared");
            } else if (ev.kind == ra2engine::InputEvent::AppLowMemory) {
                SDL_Log("[lifecycle] low memory: freed %lu texture bytes", static_cast<unsigned long>(tc.trim()));
            }
            scene->handle(ev);
        }
        const Uint32 now = SDL_GetTicks();
        const double dt = replay ? replay->dt() : fixed_dt > 0.0 ? fixed_dt : (now - prev) / 1000.0;
        prev = now;
        if (rec) rec->frame(frame, dt);
        const Uint64 pc1 = SDL_GetPerformanceCounter();
        net_linger_pump();   // NET-PLAY
        scene->update(dt);
        const Uint64 pc2 = SDL_GetPerformanceCounter();
        Uint64 pc3 = pc2;
        if (!hooks || hooks->want_render(frame)) {   // --play may render sparsely
            plat.begin_frame();
            scene->render(plat, tc);
            perf_draw(static_cast<SDL_Renderer*>(plat.renderer()), g_ui_w, g_ui_h);
            pc3 = SDL_GetPerformanceCounter();
        }
        if (hooks) hooks->end(frame, *scene, plat);   // captures read the back buffer
        if (!hooks || hooks->want_render(frame)) plat.present();
        perf_frame((pc1 - pc0) * perf_ms, (pc2 - pc1) * perf_ms, (pc3 - pc2) * perf_ms,
                   (SDL_GetPerformanceCounter() - pc3) * perf_ms);
        if (hooks && hooks->want_relaunch()) {   // W6-01-10 (--play only)
            scene.reset();
            scene.reset(hooks->relaunch_scene());
            hooks->transition(frame);
            ++frame;
            continue;
        }
        if (Scene* nx = scene->next()) {   // transition (variable dt continues)
            if (auto* d = dynamic_cast<DeferredScene*>(nx)) {
                // W2-AR-10: tear the current scene down BEFORE building the
                // next one (a loaded save used to hold two games at once);
                // W2-AR-02: a loading screen with progress while it builds
                // (not under --play, whose frames stay exactly as before);
                // W2-AR-05: a build that throws becomes an error page.
                std::unique_ptr<DeferredScene> hold(d);
                scene.reset();
                scene.reset(build_deferred(*d, plat, tc, /*show_screen=*/hooks == nullptr));
                prev = SDL_GetTicks();   // the load is not game time
            } else {
                scene.reset(nx);
            }
            if (hooks) hooks->transition(frame);
        }
        if (fixed_dt <= 0.0 && !(replay && g_replay_hidden)) {   // a hidden replay runs flat out
            const double used = (SDL_GetPerformanceCounter() - frame_start) * perf_ms;
            if (used < 16.0) SDL_Delay(static_cast<Uint32>(16.667 - used));
            frame_start = SDL_GetPerformanceCounter();
        }
        ++frame;
    }
    if (hooks) hooks->quit(frame, scene.get(), "scene wants_quit");
    finish("scene wants_quit");
    return 0;
}

